/*
 * 化学(4単位)のテキスト本文。このアプリのオリジナル。書式は lessons_1.js 冒頭のコメントと同じ。
 * 単元:c4_state / c4_thermo / c4_rate / c4_redox / c4_inorg / c4_org / c4_poly
 */
window.WPS = window.WPS || {};
WPS.LESSONS = WPS.LESSONS || {};
(function (L) {
  var PHASE = '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="水の状態図"><line x1="20" y1="135" x2="210" y2="135" class="ax"/><line x1="20" y1="135" x2="20" y2="10" class="ax"/><path d="M28 128 Q60 114 80 95" class="cv"/><path d="M80 95 Q130 70 180 32" class="cv"/><path d="M80 95 L72 16" class="cv2"/><circle cx="80" cy="95" r="3.5" class="pt"/><circle cx="180" cy="32" r="3.5" class="pt"/><text x="30" y="60">固体</text><text x="104" y="50">液体</text><text x="120" y="118">気体</text><text x="88" y="110">三重点</text><text x="140" y="24">臨界点</text><text x="178" y="148">温度</text><text x="24" y="10">圧力</text></svg>';
  var ENTH = '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="発熱反応のエンタルピー図"><line x1="20" y1="140" x2="20" y2="12" class="ax"/><text x="26" y="14">エンタルピー H(高)</text><line x1="40" y1="45" x2="105" y2="45" class="cv"/><text x="42" y="38">反応物</text><line x1="125" y1="112" x2="190" y2="112" class="cv"/><text x="130" y="128">生成物</text><line x1="115" y1="45" x2="115" y2="108" class="dash"/><path d="M110 99 L115 109 L120 99" class="ax"/><text x="122" y="76">ΔH＜0</text><text x="122" y="92">(発熱)</text></svg>';
  var ACT = '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="活性化エネルギーと触媒"><line x1="20" y1="140" x2="20" y2="10" class="ax"/><line x1="20" y1="140" x2="210" y2="140" class="ax"/><path d="M25 90 L55 90 Q100 -10 145 115 L200 115" class="cv"/><path d="M55 90 Q100 40 145 115" class="cv2"/><line x1="55" y1="90" x2="104" y2="90" class="dash"/><line x1="100" y1="46" x2="100" y2="90" class="dash"/><text x="104" y="84">Ea</text><text x="24" y="104">反応物</text><text x="150" y="132">生成物</text><line x1="140" y1="16" x2="156" y2="16" class="cv"/><text x="160" y="20">触媒なし</text><line x1="140" y1="32" x2="156" y2="32" class="cv2"/><text x="160" y="36">触媒あり</text></svg>';
  var DANIELL = '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="ダニエル電池"><rect x="20" y="50" width="180" height="85" class="bx"/><line x1="110" y1="50" x2="110" y2="135" class="dash"/><rect x="50" y="30" width="10" height="80" class="tr"/><rect x="160" y="30" width="10" height="80" class="tr"/><path d="M55 30 L55 16 L165 16 L165 30" class="ax"/><text x="88" y="12">e⁻ →</text><text x="64" y="70">Zn</text><text x="64" y="86">負極</text><text x="128" y="70">Cu</text><text x="128" y="86">正極</text><text x="26" y="126">ZnSO₄aq</text><text x="118" y="126">CuSO₄aq</text><text x="86" y="147">素焼き板</text></svg>';

  // ===== 物質の状態と溶液 =====
  L.c4_state = {
    goal: '状態図・気体の法則(ボイル・シャルルの法則、気体の状態方程式)・溶液の性質(溶解度・沸点上昇・凝固点降下・浸透圧・コロイド)を理解し、量的な計算ができるようになる。',
    intro: 'やかんの水は約100℃で沸とうしますが、富士山の山頂では90℃より低い温度で沸とうします。冬に道路にまく融雪剤は、水がこおる温度を下げます。こうした現象は、「粒子がどれだけ激しく動いているか」と「まわりからどれだけ押されているか」で説明できます。この単元では、物質の状態が決まるしくみと、気体・溶液の量的な関係を学びます。',
    pre: '【物質量】(mol)は粒子の数を表す量で、1 mol は 6.0×10²³ 個です。質量(g)÷モル質量(g/mol)で求めます。例:水 H₂O 36 g は 36÷18＝2.0 mol です。\n物質をつくる粒子は、いつもふるえたり飛び回ったりしています。これを【熱運動】といい、温度が高いほど激しくなります。粒子どうしは引き合う力(分子間力など)でまとまろうとし、熱運動はばらばらになろうとします。この2つの力関係で、固体・液体・気体が決まります。\n気体の計算では、温度を【絶対温度】T(単位 K、ケルビン)で表します。T＝t＋273(t はセルシウス温度℃)です。−273℃が 0 K で、これより低い温度はありません。\n【圧力】は面を垂直に押す力の大きさで、単位は Pa(パスカル)です。地表の大気圧はおよそ 1.013×10⁵ Pa で、これを 1 気圧ともいいます。\n濃度には、溶液 1 L あたりの溶質の物質量を表す【モル濃度】(mol/L)があります。この単元では、溶媒 1 kg あたりの溶質の物質量を表す【質量モル濃度】(mol/kg)も使います。',
    secs: [
      { h: '物質の三態と状態変化', t: '物質には【固体・液体・気体】の3つの状態があり、これを【物質の三態】といいます。固体は粒子が決まった位置でふるえているだけ、液体は粒子が互いに位置を変えながら集まっている状態、気体は粒子がばらばらに飛び回っている状態です。\n状態の変化には名前があります。固体→液体が【融解】、液体→固体が【凝固】、液体→気体が【蒸発】、気体→液体が【凝縮】、固体→気体が【昇華】、気体→固体が【凝華】です。\n純物質を加熱していくと、融解や沸騰が起きている間は、加えた熱が粒子を引きはなすことに使われるため、温度が一定のままになります。このとき必要な熱を、1 mol あたりで表したものが融解エンタルピー・蒸発エンタルピーです。\n例:氷を加熱すると、0℃で温度が止まって氷がとけ、すべて水になってから再び温度が上がります。100℃でまた温度が止まり、沸騰が続きます。',
        key: '状態変化の途中は、温度が一定に保たれる(熱は粒子を引きはなすのに使われる)。' },
      { h: '蒸気圧・沸騰と状態図', t: '密閉容器に液体を入れておくと、蒸発する分子の数と凝縮する分子の数が等しくなり、見かけ上蒸発が止まります。このときの蒸気の圧力を【飽和蒸気圧】(蒸気圧)といいます。蒸気圧は温度が高いほど大きくなります。\n液体の蒸気圧が外の圧力(大気圧)と等しくなると、液体の内部からも蒸発が起こります。これが【沸騰】で、そのときの温度が【沸点】です。山の上は大気圧が低いので、蒸気圧が低い(温度が低い)うちに外圧と等しくなり、沸点が下がります。\n温度と圧力によって、物質がどの状態になるかを表した図を【状態図】といいます。3本の曲線で、固体・液体・気体の領域に分かれます。3つの状態が共存する点を【三重点】、液体と気体の区別がなくなる点を【臨界点】といいます。\n水の状態図では、固体と液体の境界線(融解曲線)がわずかに左に傾いています。そのため、圧力を高くすると氷の融点は少し下がります。これは水の特別な性質で、多くの物質では右に傾きます。\n二酸化炭素は三重点の圧力が約 5.2×10⁵ Pa と大気圧より高いため、大気圧のもとでは液体にならず、ドライアイスは固体から直接気体に昇華します。',
        fig: PHASE,
        key: '沸点は「蒸気圧＝外圧」となる温度。状態図の三重点では3つの状態が共存する。' },
      { h: '気体の法則:ボイル・シャルルの法則', t: '気体の体積は、圧力と温度で大きく変わります。その関係をまとめたのが気体の法則です。\n【ボイルの法則】:温度が一定のとき、一定量の気体の体積 V は圧力 P に反比例します(PV＝一定)。圧力を2倍にすると、体積は1/2倍になります。\n【シャルルの法則】:圧力が一定のとき、一定量の気体の体積 V は絶対温度 T に比例します(V/T＝一定)。温度を℃のまま比例させてはいけません。\n2つをまとめた【ボイル・シャルルの法則】は、PV/T＝一定です。変化の前後で P₁V₁/T₁＝P₂V₂/T₂ と書けます。\n使い方のコツは、「変わらないもの」を確かめてから式を立てることです。気体の量(mol)が一定であれば、この式が使えます。',
        key: 'P₁V₁/T₁＝P₂V₂/T₂(T は絶対温度)。気体の物質量が一定のときに使える。',
        ex: [{ q: '27℃、2.0×10⁵ Pa で 6.0 L を占める気体を、127℃、1.0×10⁵ Pa にすると、体積は何 L になる?', hint: '温度を絶対温度に直してから、ボイル・シャルルの法則に入れます。', steps: ['温度を絶対温度に直す:27℃→300 K、127℃→400 K。', 'P₁V₁/T₁＝P₂V₂/T₂ に代入:(2.0×10⁵×6.0)/300＝(1.0×10⁵×V₂)/400。', 'V₂＝6.0×(2.0×10⁵/1.0×10⁵)×(400/300)＝6.0×2.0×4/3。', '計算すると V₂＝16 L。'], a: '16 L', check: '圧力が半分(体積は2倍に)、温度が 4/3 倍(体積は 4/3 倍に)なので、6.0×2×4/3＝16 で一致します。' }] },
      { h: '気体の状態方程式と混合気体', t: 'ボイル・シャルルの法則の「一定」の値は、気体の物質量 n に比例します。その比例定数を R とすると、PV＝nRT と書けます。これを【気体の状態方程式】といい、R を【気体定数】といいます。\nP を Pa、V を L で表すと、R＝8.3×10³ Pa·L/(K·mol) です。単位をそろえることが大切で、V を m³ にすると R の値が変わります。\n物質量 n は w/M(質量÷モル質量)なので、PV＝(w/M)RT と書きかえると、気体の質量を測って【分子量】M を求めることができます。\n2種類以上の気体が混ざった混合気体では、それぞれの気体が単独で容器全体を占めたときの圧力を【分圧】といいます。全圧は分圧の和になり(ドルトンの分圧の法則)、各気体の分圧＝全圧×その気体のモル分率(物質量の割合)です。\n状態方程式に完全に従う仮想の気体を【理想気体】といいます。実際の気体(実在気体)は分子に大きさがあり、分子間力もはたらくのでずれが生じますが、高温・低圧ほど理想気体に近づきます。',
        key: 'PV＝nRT(R＝8.3×10³ Pa·L/(K·mol))。分圧＝全圧×モル分率。',
        ex: [{ q: 'ある気体 1.0 g は、27℃、1.0×10⁵ Pa で 0.83 L を占めた。この気体の分子量はいくつ?(R＝8.3×10³ Pa·L/(K·mol))', hint: 'PV＝(w/M)RT を M について解きます。', steps: ['PV＝(w/M)RT を変形して、M＝wRT/(PV)。', '値を代入する:w＝1.0 g、T＝300 K、P＝1.0×10⁵ Pa、V＝0.83 L。', 'M＝1.0×8.3×10³×300/(1.0×10⁵×0.83)＝2.49×10⁶/8.3×10⁴。', '計算すると M＝30。'], a: '30', check: '分子量 30 なら 1.0 g は 1/30 mol。nRT/P＝(1/30)×8.3×10³×300/(1.0×10⁵)＝0.83 L となり、問題文と一致します。' },
          { q: '窒素 0.30 mol と酸素 0.10 mol の混合気体の全圧が 1.0×10⁵ Pa のとき、酸素の分圧は?', hint: '分圧＝全圧×モル分率です。', steps: ['全体の物質量は 0.30＋0.10＝0.40 mol。', '酸素のモル分率は 0.10/0.40＝0.25。', '酸素の分圧＝1.0×10⁵×0.25＝2.5×10⁴ Pa。'], a: '2.5×10⁴ Pa', check: '窒素の分圧は 1.0×10⁵×0.75＝7.5×10⁴ Pa。2つを足すと 1.0×10⁵ Pa になり、全圧と一致します。' }] },
      { h: '溶解度とヘンリーの法則', t: '溶媒 100 g に溶ける溶質の最大の質量(g)を、固体の【溶解度】といいます。溶解度まで溶けた溶液が【飽和溶液】です。多くの固体は、温度が高いほど溶解度が大きくなります。温度と溶解度の関係をグラフにしたものが【溶解度曲線】です。\n高温の飽和溶液を冷やすと、溶けきれなくなった分が結晶として出てきます。これを利用して物質を精製する方法が【再結晶】です。計算では「溶液全体の質量」と「出てくる結晶の質量」の比が一定になることを使います。\n気体の溶解度は、固体と逆に、温度が高いほど小さくなります。炭酸飲料が温まると気がぬけやすいのはこのためです。\n【ヘンリーの法則】:溶解度の小さい気体では、温度が一定のとき、一定量の溶媒に溶ける気体の物質量(質量)は、その気体の圧力(混合気体なら分圧)に比例します。',
        ex: [{ q: '硝酸カリウムの溶解度(水 100 g に溶ける質量)を 60℃で 109、20℃で 32 とする。60℃の飽和水溶液 209 g を 20℃に冷やすと、何 g の結晶が出てくる?', hint: '飽和水溶液 209 g は「水 100 g＋硝酸カリウム 109 g」です。', steps: ['60℃の飽和水溶液 209 g は、水 100 g に硝酸カリウム 109 g が溶けたもの。', '20℃では水 100 g に 32 g までしか溶けない。', '出てくる結晶は 109−32＝77 g。'], a: '77 g', check: '冷やした後の溶液は水 100 g＋32 g＝132 g。結晶 77 g と合わせると 209 g になり、全体の質量が保存されています。' }] },
      { h: '希薄溶液の性質:沸点上昇・凝固点降下・浸透圧', t: '不揮発性の物質を溶かした溶液は、溶媒の分子が表面から飛び出しにくくなるため、蒸気圧が純溶媒より低くなります。これを【蒸気圧降下】といいます。\n蒸気圧が下がると、外圧と等しくなるまでより高い温度が必要になり、沸点が上がります(【沸点上昇】)。また、溶液は純溶媒より低い温度でこおります(【凝固点降下】)。どちらも、薄い溶液では温度の変化 Δt が質量モル濃度 m に比例します。\nΔt＝Kb×m(沸点上昇)、Δt＝Kf×m(凝固点降下)。Kb・Kf は溶媒ごとに決まる定数で、水では Kb＝0.52 K·kg/mol、Kf＝1.85 K·kg/mol です。\n大切なのは、m が「溶けている粒子の濃度」だということです。NaCl は水中で Na⁺ と Cl⁻ に電離するので、粒子の数は2倍として計算します。\n水は通すが溶質は通さない膜(半透膜)で溶液と水を仕切ると、水が溶液側へ移動しようとします。これを止めるのに必要な圧力が【浸透圧】Π で、Π＝cRT(c はモル濃度)が成り立ちます(ファントホッフの法則)。',
        key: 'Δt＝K×m(m は溶媒 1 kg あたりの溶質粒子の物質量)。浸透圧は Π＝cRT。電解質は電離後の粒子数で数える。',
        ex: [{ q: '水 1.0 kg に塩化ナトリウム NaCl 0.10 mol を溶かした水溶液の凝固点は何℃?(水のモル凝固点降下 Kf＝1.85 K·kg/mol、NaCl は完全に電離するとする)', hint: 'NaCl→Na⁺＋Cl⁻ で、粒子の数は2倍になります。', steps: ['NaCl は Na⁺ と Cl⁻ に電離するので、溶質粒子は 0.10×2＝0.20 mol。', '水 1.0 kg あたりなので、粒子の質量モル濃度は 0.20 mol/kg。', 'Δt＝Kf×m＝1.85×0.20＝0.37 K。', '凝固点は 0−0.37＝−0.37℃。'], a: '−0.37℃', check: '電離を考えないと −0.185℃ になります。グルコース(非電解質)0.10 mol の場合の2倍の下がり方になっているかを確かめます。' }] },
      { h: 'コロイド', t: '直径がおよそ 10⁻⁹ m〜10⁻⁷ m(1〜100 nm 程度)の粒子を【コロイド粒子】といい、これが分散したものをコロイドといいます。牛乳・墨汁・ゼラチンなどが例です。\nコロイド粒子は、ふつうの分子やイオンより大きいので光を散乱します。横から強い光を当てると光の通り道が明るく見える現象を【チンダル現象】といいます。また、限外顕微鏡で見ると、粒子が不規則にふるえるように動きます。これは、まわりの溶媒分子が不規則にぶつかるためで、【ブラウン運動】といいます。\nコロイド粒子は、ろ紙は通りますが半透膜(セロハンなど)は通りません。この性質で、コロイド溶液から小さなイオンなどを取り除く操作を【透析】といいます。コロイド粒子は正または負に帯電しているので、電圧をかけると一方の電極へ移動します(【電気泳動】)。\n水との親和力が小さい【疎水コロイド】(水酸化鉄(Ⅲ)など)は、少量の電解質で集まって沈殿します(【凝析】)。水を強く引きつけている【親水コロイド】(ゼラチン・デンプンなど)は、多量の電解質を加えると沈殿します(【塩析】)。疎水コロイドに親水コロイドを加えて凝析しにくくしたものを【保護コロイド】といい、墨汁のにかわがその例です。',
        key: 'チンダル現象(光の散乱)・ブラウン運動(溶媒分子の衝突)・透析・電気泳動。疎水コロイドは凝析、親水コロイドは塩析。' },
      { h: 'もっと深く:溶液の性質は「蒸気圧が下がる」ことから始まる', t: '沸点上昇・凝固点降下・浸透圧は別々の現象に見えますが、根っこは同じです。溶質の粒子が溶けていると、液体の表面のうち溶媒の分子が占める割合が減り、単位時間に蒸発できる溶媒分子が少なくなります。その結果、溶液の蒸気圧は純溶媒より低くなります。これを【蒸気圧降下】といいます。\n沸騰は「蒸気圧＝外圧」になったときに起こるので、蒸気圧が下がった溶液は、純溶媒より高い温度まで温めないと沸騰しません。これが【沸点上昇】です。凝固点降下も、溶液中では溶媒分子が結晶に加わりにくくなるために起こり、どちらも溶質の種類ではなく【粒子の数】で大きさが決まります。このような性質をまとめて【束一的性質】とよぶことがあります。\n濃度に質量モル濃度(溶媒 1 kg あたりの物質量)を使うのは、温度が変わっても値が変わらないからです。モル濃度(溶液 1 L あたり)は、温度で溶液の体積が変わると値も変わってしまいます。沸点や凝固点のように温度が動く現象には、質量モル濃度が向いています。\n浸透圧の式 Π＝cRT は、気体の状態方程式 P＝(n/V)RT とまったく同じ形をしています(ファントホッフの法則)。溶媒の中に散らばった溶質の粒子が、容器の中の気体分子のようにふるまうと考えるとイメージしやすいでしょう。\n粒子の数で決まるということは、逆に「粒子の数が変わる」と測定結果が変わるということです。電解質は電離して粒子がふえ、反対に酢酸はベンゼン中で2分子が水素結合で結びついた【二量体】をつくるので、粒子がへります。そのため、凝固点降下から求めた酢酸の見かけの分子量は 60 より大きくなり、すべて二量体なら 120 になります。',
        key: '蒸気圧降下→沸点上昇・凝固点降下。どれも溶質の「粒子の数」で決まる。電離ではふえ、二量体ではへる。' },
      { h: '入試ではこう出る:液体が残るか、全部気体か(蒸気圧の判定)', t: '密閉容器に水などの液体と気体を入れる問題は、共通テストでも個別試験でも定番です。ポイントは、液体と蒸気が共存しているとき、その物質の分圧は【飽和蒸気圧より大きくなれない】ということです。\n解き方の型は次の3段階です。①まず「すべて気体になった」と仮定して、状態方程式で分圧 P を計算する。②その P を、その温度の飽和蒸気圧と比べる。③ P が飽和蒸気圧以下なら仮定どおり全部気体で、分圧は P のまま。P が飽和蒸気圧より大きければ一部が液体として残り、分圧は飽和蒸気圧に等しくなる。\nひっかけになりやすいのは、液体が残ったときに、状態方程式に「入れた全物質量」を代入してしまうことです。気体として存在するのは、飽和蒸気圧から逆算した物質量だけです。\nほかの気体(窒素など)が一緒に入っていても、水の分圧の判定は水だけで行います。全圧は「ほかの気体の分圧＋水の分圧」です。冷やすと水の分圧だけが飽和蒸気圧に頭打ちされる、という変化をグラフで問う問題もよく出ます。\n時間配分のコツ:R や体積の値は、計算がきれいになるように選ばれていることが多いので、先に文字式で整理してから数値を入れると速く確実です。',
        key: 'まず全部気体と仮定→分圧を飽和蒸気圧と比べる。液体が残れば、分圧＝飽和蒸気圧。',
        ex: [{ q: '容積 8.3 L の真空容器に水 0.10 mol を入れ、27℃に保った。容器内の圧力と、液体として残る水の物質量を求めよ。(27℃の水の飽和蒸気圧 3.6×10³ Pa、R＝8.3×10³ Pa·L/(K·mol))', hint: 'まず、すべて水蒸気になったと仮定して圧力を計算します。', steps: ['すべて気体と仮定すると、P＝nRT/V＝0.10×8.3×10³×300/8.3＝3.0×10⁴ Pa。', 'これは飽和蒸気圧 3.6×10³ Pa より大きいので、仮定はまちがいで、水の一部は液体として残る。', '液体が残るので、水蒸気の圧力は飽和蒸気圧に等しく 3.6×10³ Pa。', '気体の水の物質量は n＝PV/(RT)＝3.6×10³×8.3/(8.3×10³×300)＝0.012 mol。', '液体の水は 0.10−0.012＝0.088 mol。'], a: '圧力 3.6×10³ Pa、液体の水 0.088 mol', check: '気体の水 0.012 mol で圧力を計算し直すと 0.012×8.3×10³×300/8.3＝3.6×10³ Pa となり、飽和蒸気圧と一致します。' },
          { q: '容積 8.3 L の容器に、窒素 0.10 mol と水 0.010 mol を入れた。(1)27℃での全圧はいくらか。(2)7℃に冷やしたときの全圧はいくらか。(飽和蒸気圧は 27℃で 3.6×10³ Pa、7℃で 1.0×10³ Pa。R＝8.3×10³ Pa·L/(K·mol)。液体の水の体積は無視する)', hint: '窒素と水は分けて考えます。水だけ、蒸気圧の判定をします。', steps: ['(1)水がすべて気体なら分圧は 0.010×8.3×10³×300/8.3＝3.0×10³ Pa。飽和蒸気圧 3.6×10³ Pa 以下なので、すべて気体。', '窒素の分圧は 0.10×8.3×10³×300/8.3＝3.0×10⁴ Pa。全圧は 3.0×10⁴＋3.0×10³＝3.3×10⁴ Pa。', '(2)7℃(280 K)で水がすべて気体なら 0.010×8.3×10³×280/8.3＝2.8×10³ Pa。飽和蒸気圧 1.0×10³ Pa より大きいので一部が凝縮し、水の分圧は 1.0×10³ Pa。', '窒素の分圧は 0.10×8.3×10³×280/8.3＝2.8×10⁴ Pa。全圧は 2.8×10⁴＋1.0×10³＝2.9×10⁴ Pa。'], a: '(1)3.3×10⁴ Pa (2)2.9×10⁴ Pa', check: '(1)は全物質量 0.11 mol で nRT/V＝0.11×8.3×10³×300/8.3＝3.3×10⁴ Pa と一致します。(2)で水も全部気体とすると 3.08×10⁴ Pa になり、正解より大きくなることも確認できます。' }] }
    ],
    drill: [
      { lv: 1, q: '温度一定で、1.0×10⁵ Pa で 2.0 L を占める気体の圧力を 4.0×10⁵ Pa にした。体積は何 L になるか。', a: '0.50 L', exp: '温度と物質量が一定なので、ボイルの法則 P₁V₁＝P₂V₂ が使えます。\n1.0×10⁵×2.0＝4.0×10⁵×V₂ より V₂＝0.50 L。圧力が4倍になったので体積は 1/4 になる、と確かめられます。' },
      { lv: 1, q: '0.20 mol の気体が 27℃で 4.15 L を占めている。圧力は何 Pa か。(R＝8.3×10³ Pa·L/(K·mol))', a: '1.2×10⁵ Pa', exp: '状態方程式 PV＝nRT を P について解きます。温度は絶対温度 300 K に直します。\nP＝0.20×8.3×10³×300/4.15＝0.20×300×2000＝1.2×10⁵ Pa(8.3×10³÷4.15＝2000 を先に計算すると楽です)。' },
      { lv: 1, q: '水 500 g にグルコース 0.10 mol を溶かした水溶液の沸点上昇度は何 K か。(水のモル沸点上昇 Kb＝0.52 K·kg/mol)', a: '約 0.10 K', exp: '沸点上昇度は Δt＝Kb×m で、m は溶媒 1 kg あたりの物質量(質量モル濃度)です。\n溶媒は 500 g＝0.500 kg なので、m＝0.10/0.500＝0.20 mol/kg。グルコースは非電解質なので粒子の数はそのままです。\nΔt＝0.52×0.20＝0.104 ≒ 0.10 K。' },
      { lv: 2, q: 'グルコース(分子量 180)1.8 g を水に溶かして 100 mL にした水溶液の、27℃での浸透圧は何 Pa か。(R＝8.3×10³ Pa·L/(K·mol))', a: '約 2.5×10⁵ Pa', exp: '浸透圧は Π＝cRT で、c はモル濃度(mol/L)です。質量モル濃度ではない点に注意します。\nグルコースは 1.8/180＝0.010 mol、溶液は 0.100 L なので c＝0.10 mol/L。\nΠ＝0.10×8.3×10³×300＝2.49×10⁵ ≒ 2.5×10⁵ Pa。' },
      { lv: 2, q: '窒素と酸素が物質量の比 4:1 で混ざった気体(空気のモデル)の平均分子量はいくらか。(N₂＝28、O₂＝32)', a: '28.8', exp: '平均分子量は、各成分の分子量に「モル分率」をかけて足したものです。混合気体 1 mol の質量を考えると分かりやすくなります。\n窒素のモル分率 0.8、酸素 0.2 なので、28×0.8＋32×0.2＝22.4＋6.4＝28.8。\nこの値は、気体が空気より重いか軽いかの判断(下方置換・上方置換の選び方)にも使います。' },
      { lv: 2, q: '0℃で、1.0×10⁵ Pa の酸素は水 1.0 L に 2.2×10⁻³ mol 溶ける。0℃で、5.0×10⁵ Pa の酸素に接している水 2.0 L には、何 g の酸素が溶けるか。(O₂＝32)', a: '約 0.70 g', exp: 'ヘンリーの法則より、溶ける気体の物質量は、その気体の圧力(分圧)と水の量に比例します。\n圧力 5 倍、水 2 倍なので、2.2×10⁻³×5×2＝2.2×10⁻² mol。\n質量は 2.2×10⁻²×32＝0.704 ≒ 0.70 g。物質量で比例計算してから最後に質量に直すのが安全です。' },
      { lv: 3, q: '硫黄 1.28 g をベンゼン 50.0 g に溶かすと、凝固点が 0.512 K 下がった。硫黄の分子量を求め、ベンゼン中での硫黄の分子式を答えよ。(ベンゼンのモル凝固点降下 Kf＝5.12 K·kg/mol、S＝32)', a: '分子量 256、S₈', exp: 'Δt＝Kf×m より、m＝0.512/5.12＝0.100 mol/kg。\n溶媒は 0.0500 kg なので、溶けている硫黄分子は 0.100×0.0500＝5.00×10⁻³ mol。\n分子量は 1.28/(5.00×10⁻³)＝256。256÷32＝8 なので、分子式は S₈ です。\n凝固点降下は「分子の数」を数える方法なので、原子がいくつ結びついた分子なのかが分かります。' },
      { lv: 3, q: '酢酸(分子量 60)1.20 g をベンゼン 100 g に溶かすと、凝固点が 0.640 K 下がった。酢酸の一部が二量体 (CH₃COOH)₂ になっているとすると、二量体になった酢酸分子は、溶かした酢酸分子の何% か。(Kf＝5.12 K·kg/mol)', a: '75%', exp: 'まず、溶けている粒子の総物質量を求めます。m＝0.640/5.12＝0.125 mol/kg、溶媒 0.100 kg なので粒子は 0.0125 mol。\n溶かした酢酸は 1.20/60＝0.0200 mol。そのうち割合 β が二量体になると、単量体 0.0200(1−β) mol と二量体 0.0100β mol で、粒子の合計は 0.0200−0.0100β mol。\n0.0200−0.0100β＝0.0125 より β＝0.75、つまり 75%。\n確かめ:単量体 0.0050 mol＋二量体 0.0075 mol＝0.0125 mol で一致します。粒子がへるほど凝固点降下は小さくなります。' }
    ],
    faq: [
      ['気体の計算で、温度を必ず絶対温度にするのはなぜ?', 'シャルルの法則で体積が比例するのは、℃ではなく絶対温度だからです。例えば 0℃から 10℃にしても体積は「無限倍」になるわけではありません。273 K→283 K と考えれば、体積は 283/273 倍とわかります。'],
      ['電解質だと、なぜ凝固点がより大きく下がるの?', '凝固点降下や沸点上昇は、溶質の種類ではなく「溶けている粒子の数」で決まるからです。NaCl 1 mol は Na⁺ 1 mol と Cl⁻ 1 mol、合わせて 2 mol の粒子になるので、非電解質の2倍の効果があります。'],
      ['実在気体が、低温・高圧で理想気体からずれるのはなぜ?', '低温では分子の運動がおだやかになり、分子間力の影響が大きくなります。高圧では分子どうしが近づき、分子自身の大きさが無視できなくなります。そのため、高温・低圧のほうが理想気体に近くなります。'],
      ['蒸発と沸騰は、結局なにがちがうの?', '蒸発は液体の【表面】から分子が飛び出す現象で、沸点より低い温度でも起こります。沸騰は、液体の【内部】からも気泡ができる現象です。\n液体の中に気泡ができるには、泡の中の蒸気の圧力が、外から押す圧力(外圧)に負けないことが必要です。だから沸騰は「蒸気圧＝外圧」になった温度で始まります。外圧が低い山の上で沸点が下がるのはこのためです。']
    ],
    terms: [['飽和蒸気圧', '液体と蒸気が共存してつり合ったときの蒸気の圧力'], ['三重点', '固体・液体・気体の3つの状態が共存する温度と圧力'], ['臨界点', 'これより高温・高圧では液体と気体の区別がなくなる点'], ['気体の状態方程式', 'PV＝nRT。圧力・体積・物質量・絶対温度の関係'], ['分圧', '混合気体の各成分が、単独で全体積を占めたときの圧力'], ['ヘンリーの法則', '溶ける気体の量は、その気体の圧力(分圧)に比例する'], ['質量モル濃度', '溶媒 1 kg あたりの溶質の物質量(mol/kg)'], ['浸透圧', '半透膜を通って溶媒が溶液側へ移動するのを止めるのに必要な圧力']],
    miss: ['温度を℃のまま式に入れてしまう。気体の式では、まず「＋273」して絶対温度に直す習慣をつけます。', '質量モル濃度とモル濃度を混同する。質量モル濃度は「溶媒 1 kg あたり」、モル濃度は「溶液 1 L あたり」です。単位(mol/kg と mol/L)を書いて区別します。', 'NaCl や CaCl₂ などの電解質で、電離して粒子が増えることを忘れる。「1つの式から何個のイオンができるか」を最初に確かめます。', '気体定数 R の単位と体積の単位が合っていない。R＝8.3×10³ を使うなら、体積は L、圧力は Pa です。', '凝析と塩析を逆に覚える。「疎水コロイドは少量で凝析、親水コロイドは多量で塩析」と、水との仲の良さで区別します。'],
    sum: ['沸騰は蒸気圧が外圧と等しくなったときに起こる。状態図で三重点・臨界点を読み取る。', 'ボイル・シャルルの法則は P₁V₁/T₁＝P₂V₂/T₂(T は絶対温度)。', '気体の状態方程式は PV＝nRT。分子量や分圧の計算にも使う。', '沸点上昇・凝固点降下は Δt＝K×m、浸透圧は Π＝cRT。電解質は粒子数で数える。', 'コロイドはチンダル現象・ブラウン運動・透析・電気泳動・凝析・塩析で特徴づけられる。'],
    next: '次は「化学反応とエネルギー」(反応エンタルピー・ヘスの法則)に進みましょう。状態変化にともなう熱の出入りが、反応全体のエネルギーの考え方につながります。'
  };

  // ===== 化学反応とエネルギー =====
  L.c4_thermo = {
    goal: '反応エンタルピー ΔH を使って反応の熱の出入りを表し、ヘスの法則・生成エンタルピー・結合エネルギーから未知の ΔH を求められるようになる。',
    intro: 'ガスコンロでメタンを燃やすと熱が出ます。使い捨てカイロも、鉄が酸化するときの熱を利用しています。逆に、冷却パックは物質が水に溶けるときに熱を吸収します。化学反応には、必ずエネルギーの出入りがともないます。この単元では、その量を【反応エンタルピー】で表し、計算する方法を学びます。',
    pre: '化学反応式の【係数】は、反応する粒子の数の比、つまり物質量(mol)の比を表します。2H₂＋O₂→2H₂O なら、H₂ 2 mol と O₂ 1 mol から H₂O 2 mol ができます。\n中学では、熱を出す反応を【発熱反応】、熱を吸収する反応を【吸熱反応】と学びました。燃焼は発熱反応、炭酸水素ナトリウムの熱分解は吸熱反応の例です。\nエネルギーはなくなったり、急に生まれたりはしません(【エネルギー保存の法則】)。反応で熱が出たなら、その分だけ物質のもつエネルギーが減っています。\n熱量の単位は J(ジュール)で、化学では kJ(キロジュール、1 kJ＝1000 J)をよく使います。水 1 g の温度を 1 K 上げるのに必要な熱量(比熱)は約 4.2 J です。',
    secs: [
      { h: '反応エンタルピーとは', t: '一定の圧力のもとで物質がもっているエネルギーを表す量を【エンタルピー】(記号 H)といいます。直接その値は測れませんが、反応の前後の差は、出入りした熱として測ることができます。\n化学反応にともなうエンタルピーの変化を【反応エンタルピー】ΔH といい、ΔH＝(生成物のエンタルピー)−(反応物のエンタルピー)です。\n発熱反応では、熱を出した分だけ生成物のエンタルピーが小さくなるので、ΔH＜0(負)になります。吸熱反応では ΔH＞0(正)です。\n書き方の例:CH₄(気)＋2O₂(気)→CO₂(気)＋2H₂O(液) ΔH＝−891 kJ。これは「メタン 1 mol が燃焼すると 891 kJ の熱が出る」ことを表します。物質の状態(気・液・固)を書くのは、状態によってエンタルピーが違うからです。\n以前は、熱を右辺に「＋891 kJ」と書く熱化学方程式が使われていました。反応エンタルピーでは発熱が負になり、符号が逆になることに注意します。',
        fig: ENTH,
        key: 'ΔH＝生成物の H−反応物の H。発熱反応は ΔH＜0、吸熱反応は ΔH＞0。物質の状態も書く。' },
      { h: 'いろいろな反応エンタルピー', t: '反応エンタルピーには、反応の種類ごとに名前がついています。どれも「着目する物質 1 mol あたり」で表します。\n【燃焼エンタルピー】:物質 1 mol が完全燃焼するときの反応エンタルピー。例:H₂(気)＋1/2O₂(気)→H₂O(液) ΔH＝−286 kJ。H₂ 1 mol に合わせるため、O₂ の係数が 1/2 になっています。\n【生成エンタルピー】:化合物 1 mol が、その成分元素の単体から生成するときの反応エンタルピー。例:C(黒鉛)＋O₂(気)→CO₂(気) ΔH＝−394 kJ。\n【中和エンタルピー】:酸と塩基の中和で水 1 mol が生じるときの反応エンタルピー。強酸と強塩基のうすい水溶液では、約 −56 kJ/mol です。\n【溶解エンタルピー】:物質 1 mol が多量の水に溶けるときの反応エンタルピー。例:NaOH(固)は溶けるときに発熱し、硝酸アンモニウム NH₄NO₃(固)は吸熱します。\n状態変化にもエンタルピー変化があります。H₂O(固)→H₂O(液) ΔH＝＋6.0 kJ(融解)、H₂O(液)→H₂O(気) ΔH＝＋44 kJ(25℃での蒸発)。どちらも吸熱です。',
        key: '燃焼・生成・中和・溶解エンタルピーは、着目する物質 1 mol(中和は水 1 mol)あたりで表す。',
        ex: [{ q: 'プロパン C₃H₈ の燃焼エンタルピーを −2220 kJ/mol とする。プロパン 11 g が完全燃焼すると、何 kJ の熱が発生する?(H＝1.0、C＝12)', hint: 'まず質量を物質量に直します。', steps: ['C₃H₈ のモル質量は 12×3＋1.0×8＝44 g/mol。', '11 g は 11÷44＝0.25 mol。', '1 mol で 2220 kJ の発熱なので、0.25 mol では 2220×0.25＝555 kJ。'], a: '555 kJ(約 5.6×10² kJ)', check: '1 mol(44 g)の 1/4 の質量なので、熱量も 2220 kJ の 1/4 になっているかを確かめます。' }] },
      { h: 'ヘスの法則', t: '炭素が燃えて CO₂ になるとき、「一気に CO₂ になる」経路と「いったん CO になってから CO₂ になる」経路があります。どちらの経路でも、出入りする熱の合計は同じです。\n【ヘスの法則】(総熱量保存の法則):反応エンタルピーは、反応の始めの状態と終わりの状態だけで決まり、途中の経路によらない。\nこの法則のおかげで、反応式を数式のように足したり引いたり、何倍かしたりして、直接測りにくい反応の ΔH を求めることができます。式を何倍かしたら、ΔH も同じ倍にします。式を逆向きにしたら、ΔH の符号を変えます。\n解き方のコツは、求めたい式に出てくる物質に注目し、「その物質を含む式を、必要な係数になるように何倍するか」を決めていくことです。求めたい式に出てこない物質は、最後に消えるようにします。',
        key: 'ΔH は経路によらない。式を足し引きすれば、ΔH も同じように足し引きする(逆向きにすると符号が変わる)。',
        ex: [{ q: 'C(黒鉛)＋O₂(気)→CO₂(気) ΔH＝−394 kJ …①、CO(気)＋1/2O₂(気)→CO₂(気) ΔH＝−283 kJ …② から、C(黒鉛)＋1/2O₂(気)→CO(気) の ΔH を求めよう。', hint: '求めたい式では CO が右辺にあります。②を逆向きにして考えます。', steps: ['求めたい式で、C は左辺に 1 mol → ①をそのまま使う。', 'CO は右辺に 1 mol → ②を逆向きにする:CO₂(気)→CO(気)＋1/2O₂(気) ΔH＝＋283 kJ。', '①と逆向きの②を足すと、CO₂ が消えて C(黒鉛)＋1/2O₂(気)→CO(気) になる。', 'ΔH＝−394＋283＝−111 kJ。'], a: 'ΔH＝−111 kJ', check: '「C→CO(−111)」と「CO→CO₂(−283)」を合わせると −394 kJ になり、C→CO₂ の ΔH と一致します。' }] },
      { h: '生成エンタルピーから ΔH を求める', t: 'ヘスの法則を使うと、どんな反応の ΔH も、関係する物質の生成エンタルピーから計算できます。\n考え方:反応物をいったん成分元素の単体にばらし、そこから生成物を組み立てると考えます。ばらすときは生成エンタルピーの符号が逆、組み立てるときはそのままです。\nまとめると、ΔH＝(生成物の生成エンタルピーの和)−(反応物の生成エンタルピーの和)。それぞれに反応式の係数をかけて足します。\n単体(O₂、H₂、C(黒鉛)など、その元素のもっとも安定な単体)の生成エンタルピーは 0 です。単体から単体をつくるので、変化がないからです。',
        key: 'ΔH＝(生成物の生成エンタルピーの和)−(反応物の生成エンタルピーの和)。単体は 0。',
        ex: [{ q: '生成エンタルピーを C₂H₅OH(液) −277、CO₂(気) −394、H₂O(液) −286(kJ/mol)とする。エタノールの燃焼 C₂H₅OH(液)＋3O₂(気)→2CO₂(気)＋3H₂O(液) の ΔH を求めよう。', hint: 'O₂ は単体なので生成エンタルピーは 0 です。', steps: ['生成物の和:2×(−394)＋3×(−286)＝−788−858＝−1646 kJ。', '反応物の和:(−277)＋3×0＝−277 kJ。', 'ΔH＝(−1646)−(−277)＝−1369 kJ。'], a: 'ΔH＝−1369 kJ', check: '燃焼なので ΔH が負(発熱)になっているかを確かめます。正になったら、引く順番が逆になっています。' }] },
      { h: '結合エネルギー', t: '気体分子の中の共有結合 1 mol を切って、ばらばらの原子にするのに必要なエネルギーを【結合エネルギー】といいます。結合を切るにはエネルギーが必要なので、正の値で表します。例:H−H 436 kJ/mol。\n反応は「反応物の結合を切って原子にばらし、原子を組みかえて生成物の結合をつくる」と考えられます。切るときはエネルギーを吸収し、つくるときは放出します。\nしたがって、ΔH＝(切れる結合のエネルギーの和)−(できる結合のエネルギーの和)。生成エンタルピーの式とは引く順番が逆になるので、注意しましょう。\nこの方法が正確に使えるのは、反応物も生成物もすべて気体の場合です。液体や固体が含まれるときは、蒸発エンタルピーなどを加えて調整する必要があります。',
        key: '結合エネルギーからは ΔH＝(切れる結合の和)−(できる結合の和)。すべて気体のときに使う。',
        ex: [{ q: '結合エネルギーを N≡N 945、H−H 436、N−H 391(kJ/mol)とする。N₂(気)＋3H₂(気)→2NH₃(気) の ΔH を求めよう。', hint: 'NH₃ 1分子には N−H 結合が3本あります。', steps: ['切れる結合:N≡N が 1 mol、H−H が 3 mol → 945＋3×436＝945＋1308＝2253 kJ。', 'できる結合:NH₃ 2 mol に N−H が 3×2＝6 mol → 6×391＝2346 kJ。', 'ΔH＝2253−2346＝−93 kJ。'], a: 'ΔH＝−93 kJ(NH₃ 1 mol あたりでは約 −46 kJ)', check: 'できる結合のエネルギーのほうが大きいので発熱(ΔH＜0)。アンモニアの合成が発熱反応であることと合っています。' }] },
      { h: '熱量の測定と、化学反応と光', t: '反応で出入りする熱は、水溶液の温度変化から測れます。熱量 q＝(溶液の質量)×(比熱)×(温度変化)です。水溶液の比熱は水と同じ約 4.2 J/(g·K) とみなすことが多いです。\n求めた熱量を、反応した物質の物質量で割れば、1 mol あたりの反応エンタルピーになります。温度が上がったなら発熱なので、ΔH には負の符号をつけます。\n化学反応では、エネルギーが熱だけでなく光として出入りすることもあります。ルミノール反応のように、反応で光を出す現象を【化学発光】といいます。逆に、光合成は光のエネルギーを吸収して進む反応です。\n光合成 6CO₂＋6H₂O→C₆H₁₂O₆＋6O₂ は大きな吸熱反応(ΔH＞0)で、植物は光のエネルギーを、糖のもつエンタルピーとしてたくわえています。',
        ex: [{ q: '水 48 g に水酸化ナトリウム NaOH(固)2.0 g を溶かしたところ、溶液の温度が 10 K 上がった。NaOH の溶解エンタルピーを求めよう。(溶液の比熱 4.2 J/(g·K)、NaOH＝40)', hint: '溶液全体の質量は、水と NaOH の合計です。', steps: ['溶液の質量は 48＋2.0＝50 g。', '発生した熱量 q＝50×4.2×10＝2100 J＝2.1 kJ。', 'NaOH の物質量は 2.0÷40＝0.050 mol。', '1 mol あたり 2.1÷0.050＝42 kJ の発熱なので、ΔH＝−42 kJ/mol。'], a: '約 −42 kJ/mol', check: '温度が上がった(発熱)ので符号は負。教科書の値(約 −45 kJ/mol)に近く、熱が外へ逃げた分だけ小さめに出ると考えられます。' }] },
      { h: 'もっと深く:ヘスの法則が成り立つ理由 ― エンタルピーは「高さ」と同じ', t: 'ヘスの法則は「反応エンタルピーは、反応の道すじによらず、最初と最後の状態だけで決まる」という法則です。なぜそう言えるのでしょうか。\nエンタルピーは、物質がその状態でもっている量で、どうやってその状態になったかには関係しません。このような量を【状態量】といいます。山登りにたとえると、エンタルピーは「標高」です。ふもとから山頂までの標高差は、どの登山道を通っても同じです。同じように、反応物から生成物への ΔH も、途中でどの反応を経由しても同じになります。\nこの考え方を使うと、直接は測れない反応の ΔH も求められます。たとえば、炭素から一酸化炭素だけをつくる反応は、どうしても一部が CO₂ になってしまうので直接測れません。しかし、C→CO₂ と CO→CO₂ の ΔH を測れば、その差として求められます。\nイオン結晶をばらばらのイオンにするのに必要なエネルギー(【格子エネルギー】)も、直接は測れない量の代表です。これは、昇華・イオン化・結合の切断・電子の受けとり・結晶の生成という段階を一周させた図(【ボルン・ハーバーサイクル】)を使って、ヘスの法則から計算します。\n注意点として、結合エネルギーは【気体】の分子についての値です。液体の水が関わる反応で結合エネルギーを使うときは、蒸発エンタルピーの分を補正する必要があります。また、結合エネルギーはいろいろな化合物での平均値なので、計算結果は近似値になります。',
        key: 'エンタルピーは状態量(標高のようなもの)。だから道すじによらず ΔH は同じ=ヘスの法則。' },
      { h: '入試ではこう出る:ΔH の計算は「エネルギー図」か「公式」で', t: '反応エンタルピーの計算は、大きく3つの型に分かれます。①いくつかの熱化学的な式を足し引きして目的の式をつくる型、②生成エンタルピーや燃焼エンタルピーを使って公式で求める型、③結合エネルギーを使う型です。\n②の公式は、生成エンタルピーなら「ΔH＝(生成物の生成エンタルピーの和)−(反応物の生成エンタルピーの和)」、燃焼エンタルピーなら逆に「ΔH＝(反応物の燃焼エンタルピーの和)−(生成物の燃焼エンタルピーの和)」です。順番が逆になる理由は、燃焼エンタルピーが「燃えて CO₂ と H₂O になるときの値」だからで、エネルギー図をかけばすぐ確かめられます。\nよくあるひっかけは、水が【液体か気体か】です。H₂O(液)と H₂O(気)では、蒸発エンタルピー(約 44 kJ/mol)の分だけ値がちがいます。また、係数が2以上の物質の値を、係数倍し忘れるミスも多く見られます。\n混合気体の燃焼で発生した熱量から、組成を求める問題もよく出ます。物質量を x、y とおいて「物質量の合計」と「熱量の合計」の連立方程式を立てるのが型です。\n時間配分のコツ:式の足し引きで迷ったら、目的の式に1回しか出てこない物質に注目して、その物質の係数がそろうように各式を何倍するかを決めると速く解けます。',
        key: '燃焼エンタルピーからは「反応物の和−生成物の和」。水の状態(液・気)と係数に注意。',
        ex: [{ q: '燃焼エンタルピーを C(黒鉛) −394、H₂(気) −286、C₂H₆(気) −1560(kJ/mol、生じる水は液体)とする。エタン C₂H₆ の生成エンタルピーを求めよ。', hint: '生成反応 2C(黒鉛)＋3H₂(気)→C₂H₆(気) の ΔH を、燃焼エンタルピーで表します。', steps: ['目的の反応は 2C(黒鉛)＋3H₂(気)→C₂H₆(気)。', '燃焼エンタルピーを使う公式:ΔH＝(反応物の燃焼エンタルピーの和)−(生成物の燃焼エンタルピーの和)。', '反応物:2×(−394)＋3×(−286)＝−788−858＝−1646 kJ。生成物:−1560 kJ。', 'ΔH＝−1646−(−1560)＝−86 kJ。'], a: '−86 kJ/mol', check: 'エネルギー図で考えると、2C＋3H₂ を燃やすと 1646 kJ、C₂H₆ を燃やすと 1560 kJ 出ます。前者のほうが 86 kJ 多いので、2C＋3H₂ のほうが C₂H₆ より 86 kJ 高い位置にあり、生成は発熱(−86 kJ)と分かります。' },
          { q: 'メタンとプロパンの混合気体 0.50 mol を完全燃焼させたところ、711 kJ の熱が発生した。混合気体中のメタンとプロパンはそれぞれ何 mol か。(燃焼エンタルピー:CH₄ −890、C₃H₈ −2220 kJ/mol)', hint: 'メタンを x mol、プロパンを y mol として連立方程式を立てます。', steps: ['物質量の合計:x＋y＝0.50。', '発生した熱量の合計:890x＋2220y＝711。', 'y＝0.50−x を代入すると 890x＋1110−2220x＝711、−1330x＝−399。', 'x＝0.30 mol、y＝0.20 mol。'], a: 'メタン 0.30 mol、プロパン 0.20 mol', check: '890×0.30＝267 kJ、2220×0.20＝444 kJ で、合計 711 kJ となり一致します。' }] }
    ],
    drill: [
      { lv: 1, q: 'H₂(気)＋1/2O₂(気)→H₂O(液) ΔH＝−286 kJ である。水素 4.0 g が完全燃焼したとき、発生する熱量は何 kJ か。(H＝1.0)', a: '572 kJ', exp: '水素 H₂ のモル質量は 2.0 g/mol なので、4.0 g は 2.0 mol です。\nΔH は H₂ 1 mol あたりの値なので、2.0 mol では 286×2.0＝572 kJ の熱が発生します(ΔH としては −572 kJ)。' },
      { lv: 1, q: 'N₂(気)＋O₂(気)→2NO(気) ΔH＝＋180 kJ である。この反応は発熱か吸熱か。また、NO の生成エンタルピーはいくらか。', a: '吸熱反応。NO の生成エンタルピーは ＋90 kJ/mol', exp: 'ΔH が正なので、生成物のほうがエンタルピーが高く、周りから熱を吸収する【吸熱反応】です。\n生成エンタルピーは「化合物 1 mol を単体からつくるときの ΔH」です。この式では NO が 2 mol できているので、1 mol あたり 180÷2＝＋90 kJ/mol となります。' },
      { lv: 1, q: '水 200 g の温度を 20℃から 45℃まで上げるのに必要な熱量は何 kJ か。(水の比熱 4.2 J/(g·K))', a: '21 kJ', exp: '熱量＝質量×比熱×温度変化 で求めます。温度変化は 45−20＝25 K です(温度差は℃でも K でも同じ数値)。\n200×4.2×25＝21000 J＝21 kJ。' },
      { lv: 2, q: 'H₂(気)＋1/2O₂(気)→H₂O(液) ΔH＝−286 kJ、H₂O(液)→H₂O(気) ΔH＝＋44 kJ とする。水素が燃えて水蒸気 H₂O(気) ができる反応の ΔH を求めよ。', a: '−242 kJ', exp: '2つの式を足すと、H₂O(液)が消えて H₂(気)＋1/2O₂(気)→H₂O(気) になります。\nΔH も足して、−286＋44＝−242 kJ。\n水蒸気ができる場合は、液体の水になる場合より 44 kJ だけ発生する熱が少ない、と覚えておくと符号の確認ができます。' },
      { lv: 2, q: '結合エネルギーを H−H 436、Cl−Cl 243、H−Cl 432(kJ/mol)とする。H₂(気)＋Cl₂(気)→2HCl(気) の ΔH を求めよ。', a: '−185 kJ', exp: '結合エネルギーを使うときは、ΔH＝(切れる結合のエネルギーの和)−(できる結合のエネルギーの和) です。結合を切るには吸熱、つくると発熱だからです。\n切れる結合:H−H と Cl−Cl で 436＋243＝679 kJ。できる結合:H−Cl が 2 つで 2×432＝864 kJ。\nΔH＝679−864＝−185 kJ(発熱)。' },
      { lv: 2, q: '1.0 mol/L 塩酸 50 mL と 1.0 mol/L 水酸化ナトリウム水溶液 50 mL を混ぜると、温度が 6.7 K 上がった。中和エンタルピー(水 1 mol 生成あたり)を求めよ。(溶液の密度 1.0 g/mL、比熱 4.2 J/(g·K))', a: '約 −56 kJ/mol', exp: '溶液は合計 100 mL＝100 g なので、発生した熱量は 100×4.2×6.7＝2814 J。\n反応した H⁺ と OH⁻ はそれぞれ 1.0×0.050＝0.050 mol なので、水は 0.050 mol できます。\n1 mol あたり 2814÷0.050＝5.6×10⁴ J＝56 kJ。発熱なので ΔH＝約 −56 kJ/mol です。' },
      { lv: 3, q: '次の値から、塩化ナトリウムの格子エネルギー(NaCl(固)→Na⁺(気)＋Cl⁻(気) の ΔH)を求めよ。Na(固)→Na(気) ＋107 kJ、Na(気)→Na⁺(気)＋e⁻ ＋496 kJ、1/2Cl₂(気)→Cl(気) ＋122 kJ、Cl(気)＋e⁻→Cl⁻(気) −349 kJ、NaCl(固)の生成エンタルピー −411 kJ/mol。', a: '＋787 kJ/mol', exp: 'ボルン・ハーバーサイクルの問題です。単体 Na(固)＋1/2Cl₂(気) から出発して、2通りの道で Na⁺(気)＋Cl⁻(気) にたどりつくと考えます。\n道1:単体→(各段階)→Na⁺(気)＋Cl⁻(気)。ΔH＝107＋496＋122−349＝376 kJ。\n道2:単体→NaCl(固)(−411 kJ)→Na⁺(気)＋Cl⁻(気)(格子エネルギー Q)。ΔH＝−411＋Q。\nヘスの法則で両者は等しいので、−411＋Q＝376、Q＝＋787 kJ/mol。' },
      { lv: 3, q: '燃焼エンタルピーを C₂H₂(気) −1301 kJ/mol、C₆H₆(液) −3268 kJ/mol とする。アセチレン3分子からベンゼンができる反応 3C₂H₂(気)→C₆H₆(液) の ΔH を求めよ。', a: '−635 kJ', exp: '燃焼エンタルピーを使うので、ΔH＝(反応物の燃焼エンタルピーの和)−(生成物の燃焼エンタルピーの和) です。\n反応物:3×(−1301)＝−3903 kJ。生成物:−3268 kJ。\nΔH＝−3903−(−3268)＝−635 kJ。\nどちらも燃えると同じ 6CO₂＋3H₂O になるので、燃焼で出る熱が多い 3C₂H₂ のほうがエネルギーが高い、と図で確かめられます。' }
    ],
    faq: [
      ['熱化学方程式と、反応エンタルピーを使った書き方は何がちがうの?', '熱化学方程式は「出てきた熱」を右辺に書くので、発熱が＋でした。反応エンタルピーは「物質のエンタルピーの変化」なので、発熱すると物質のエネルギーが減り、ΔH は−になります。見ている立場がちがうので、符号が逆になります。'],
      ['生成エンタルピーと結合エネルギーで、引く順番が逆なのはなぜ?', '生成エンタルピーは「単体からつくるとき」の値なので、生成物−反応物になります。結合エネルギーは「結合を切るとき」に必要な値なので、切る分(反応物)からつくる分(生成物)を引きます。基準とする向きがちがうためです。'],
      ['ΔH が負の反応は、必ず自然に進むの?', '必ずではありません。反応が進むかどうかには、エンタルピーのほかに「乱雑さ(エントロピー)」も関わります。例えば硝酸アンモニウムが水に溶けるのは吸熱ですが、自然に進みます。高校では、発熱反応の多くが自然に進みやすいと理解しておけば十分です。'],
      ['結合エネルギーで求めた ΔH が、生成エンタルピーから求めた値と少しずれるのはなぜ?', '結合エネルギーは、いろいろな分子の中の同じ種類の結合について平均した値だからです。たとえば C−H 結合でも、メタンの中とエタノールの中では少しずつ強さがちがいます。\nまた、結合エネルギーは気体の分子についての値なので、液体や固体が関わる反応では、状態変化の分も考えないとずれが大きくなります。結合エネルギーを使った計算は「よい近似」と考えましょう。']
    ],
    terms: [['エンタルピー', '一定圧力のもとで物質がもつエネルギーを表す量(H)'], ['反応エンタルピー', '反応にともなうエンタルピーの変化 ΔH(生成物−反応物)'], ['燃焼エンタルピー', '物質 1 mol が完全燃焼するときの反応エンタルピー'], ['生成エンタルピー', '化合物 1 mol が成分元素の単体から生成するときの反応エンタルピー'], ['中和エンタルピー', '中和で水 1 mol が生じるときの反応エンタルピー'], ['ヘスの法則', '反応エンタルピーは始めと終わりの状態だけで決まり、経路によらない'], ['結合エネルギー', '気体分子の共有結合 1 mol を切るのに必要なエネルギー']],
    miss: ['発熱反応の ΔH を正にしてしまう。「熱を出す→物質のエネルギーが減る→ΔH は負」と、エネルギー図で確かめます。', '生成エンタルピーの式と結合エネルギーの式で、引く順番を取りちがえる。「生成は生成物から、結合は切るほうから」と覚えます。', 'ヘスの法則で式を何倍かしたのに、ΔH を同じ倍にし忘れる。式と ΔH はいつもセットで操作します。', 'H₂O(液)と H₂O(気)の区別をしない。状態がちがうと ΔH が 44 kJ/mol もちがうので、状態を必ず確認します。', '単体の生成エンタルピーにも値があると思いこむ。O₂ や H₂ など、もっとも安定な単体は 0 です。'],
    sum: ['反応エンタルピー ΔH＝生成物の H−反応物の H。発熱は負、吸熱は正。', '燃焼・生成・中和・溶解エンタルピーは 1 mol あたりで表す。', 'ヘスの法則により、式を足し引きして未知の ΔH を求められる。', 'ΔH＝(生成物の生成エンタルピーの和)−(反応物の和)。単体は 0。', 'ΔH＝(切れる結合エネルギーの和)−(できる結合エネルギーの和)。'],
    next: '次は「反応速度と化学平衡」に進みましょう。反応が進むかどうかだけでなく、どれくらいの速さで、どこまで進むのかを学びます。'
  };

  // ===== 反応速度と化学平衡 =====
  L.c4_rate = {
    goal: '反応速度を変える要因を説明し、平衡定数・ルシャトリエの原理・電離平衡・緩衝液・溶解度積を使って、平衡の計算と判断ができるようになる。',
    intro: '食べ物を冷蔵庫に入れるとくさりにくいのは、温度が低いと反応がおそくなるからです。また、炭酸飲料のふたを開けると泡が出るのは、それまでつり合っていた状態がくずれたからです。この単元では、反応の「速さ」と、反応が「どこまで進んで止まって見えるか(平衡)」を学びます。',
    pre: '【モル濃度】(mol/L)は、溶液 1 L に溶けている溶質の物質量です。平衡の式では、濃度を [A] のように角かっこで表します。\n化学基礎で学んだように、【酸】は H⁺ を与える物質、【塩基】は H⁺ を受け取る物質です(ブレンステッド・ローリーの定義)。塩酸のようにほぼ完全に電離する酸を強酸、酢酸のように一部しか電離しない酸を弱酸といいます。\n【電離度】α は、溶けた酸のうち電離したものの割合です。0.10 mol/L の酢酸で α＝0.010 なら、[H⁺]＝0.10×0.010＝1.0×10⁻³ mol/L です。\n【pH】は [H⁺] の大きさを表す数で、[H⁺]＝1.0×10⁻ⁿ mol/L のとき pH＝n です。pH＝−log₁₀[H⁺] と表します。pH が 1 小さくなると、[H⁺] は 10 倍になります。\n対数の値として log₁₀2＝0.30、log₁₀3＝0.48 を使うことがあります。例:[H⁺]＝2.0×10⁻³ mol/L なら pH＝3−0.30＝2.7 です。',
    secs: [
      { h: '反応速度と、速さを変える条件', t: '【反応速度】は、単位時間あたりの物質の濃度の変化量で表します。例えば A→B の反応で、10 秒間に A の濃度が 0.50 mol/L から 0.30 mol/L に減ったら、平均の速さは 0.20÷10＝0.020 mol/(L·s) です。\n反応が起こるには、粒子どうしが衝突し、しかもある大きさ以上のエネルギーをもっている必要があります。反応の途中で通る、エネルギーの高い不安定な状態を【遷移状態】(活性化状態)といい、そこに達するのに必要なエネルギーを【活性化エネルギー】Ea といいます。\n反応を速くする条件は4つあります。①濃度を大きくする(衝突の回数が増える)。②温度を上げる(活性化エネルギーをこえる粒子の割合が増える。多くの反応では、10 K 上げると速さが2〜4倍になる)。③触媒を使う。④固体なら細かくして表面積を大きくする。\n【触媒】は、活性化エネルギーの小さい別の反応経路をつくり、反応を速くします。触媒自身は反応の前後で変化しません。反応エンタルピー ΔH は変えないことに注意しましょう。\n反応の速さと濃度の関係を表した式を【反応速度式】といいます。例:v＝k[A]ˣ[B]ʸ。k を【反応速度定数】といい、温度で変わります。指数 x・y は実験で決まり、反応式の係数と一致するとは限りません。',
        fig: ACT,
        key: '速さを上げる条件は、濃度・温度・触媒・表面積。触媒は活性化エネルギーを下げるが、ΔH は変えない。',
        ex: [{ q: 'A→B の反応で、[A]＝0.10 mol/L のとき v＝2.0×10⁻³ mol/(L·s)、[A]＝0.20 mol/L のとき v＝8.0×10⁻³ mol/(L·s) だった。v＝k[A]ˣ とするとき、x と k を求めよう。', hint: '濃度を2倍にしたとき、速さは何倍になったかを見ます。', steps: ['濃度が 0.10→0.20 で2倍になると、速さは 2.0×10⁻³→8.0×10⁻³ で4倍になった。', '2ˣ＝4 なので x＝2。つまり v＝k[A]²。', '1回目の値を代入:2.0×10⁻³＝k×(0.10)²＝k×0.010。', 'k＝2.0×10⁻³÷0.010＝0.20 L/(mol·s)。'], a: 'x＝2、k＝0.20 L/(mol·s)', check: '2回目の値で確かめる:0.20×(0.20)²＝0.20×0.040＝8.0×10⁻³ となり、一致します。' }] },
      { h: '化学平衡と平衡定数', t: '逆向きにも進む反応を【可逆反応】といい、⇄ で表します。例:H₂＋I₂ ⇄ 2HI。右向きを正反応、左向きを逆反応といいます。\n反応が進むと、反応物が減って正反応はおそくなり、生成物が増えて逆反応は速くなります。やがて両方の速さが等しくなり、見かけ上反応が止まった状態になります。これを【化学平衡の状態】(平衡状態)といいます。反応は止まったのではなく、正反応と逆反応が同じ速さで起こり続けています。\naA＋bB ⇄ cC＋dD が平衡状態のとき、K＝[C]ᶜ[D]ᵈ/([A]ᵃ[B]ᵇ) は一定の値になります。これを【平衡定数】(濃度平衡定数)といい、この関係を化学平衡の法則(質量作用の法則)といいます。\nK は温度が変わらなければ一定で、はじめの濃度によりません。K が大きいほど、平衡状態で生成物が多いことを意味します。\n平衡の計算では、「はじめ」「変化量」「平衡時」の3行の表をつくると、まちがえにくくなります。変化量の比は反応式の係数の比になります。',
        key: 'K＝[生成物]の係数乗の積/[反応物]の係数乗の積。K は温度だけで決まる。',
        ex: [{ q: '1.0 L の容器に H₂ 1.0 mol と I₂ 1.0 mol を入れて一定温度に保つと、H₂＋I₂ ⇄ 2HI が平衡に達した。この温度で K＝64 のとき、生成した HI は何 mol?', hint: '反応した H₂ を x mol として、3行の表をつくります。', steps: ['反応した H₂ を x mol とすると、I₂ も x mol 反応し、HI は 2x mol 生じる。', '平衡時:H₂ (1.0−x)、I₂ (1.0−x)、HI 2x(体積 1.0 L なので、そのまま濃度 mol/L になる)。', 'K＝(2x)²/(1.0−x)²＝64。両辺は正なので平方根をとると、2x/(1.0−x)＝8。', '2x＝8−8x より 10x＝8、x＝0.80。HI は 2x＝1.6 mol。'], a: '1.6 mol', check: '平衡時は H₂ 0.20、I₂ 0.20、HI 1.6。K＝1.6²/(0.20×0.20)＝2.56/0.040＝64 となり一致します。' }] },
      { h: 'ルシャトリエの原理(平衡の移動)', t: '平衡状態にある反応で、濃度・圧力・温度などの条件を変えると、その変化をやわらげる向きに反応が進み、新しい平衡状態になります。これを【ルシャトリエの原理】(平衡移動の原理)といいます。\n①濃度:ある物質を加えると、その物質が減る向きに移動します。取り除くと、その物質が増える向きに移動します。\n②圧力(気体の反応):圧力を上げると、気体分子の総数が減る向きに移動します。例:N₂＋3H₂ ⇄ 2NH₃ では左辺 4 分子、右辺 2 分子なので、加圧すると右に移動します。両辺の分子数が等しい H₂＋I₂ ⇄ 2HI では移動しません。\n③温度:温度を上げると、吸熱の向きに移動します。N₂＋3H₂→2NH₃ ΔH＝−92 kJ(右向きが発熱)では、温度を上げると左に移動して NH₃ が減ります。温度を変えると平衡定数 K の値も変わります。\n④触媒:正反応と逆反応の両方を同じように速くするので、平衡は移動しません。平衡に達するまでの時間が短くなるだけです。\n工業的なアンモニアの合成(ハーバー・ボッシュ法)では、平衡だけを考えれば低温・高圧が有利です。しかし低温では反応がおそすぎるため、Fe₃O₄ を主成分とする触媒を使い、400〜600℃程度・高圧で行います。',
        key: '加えた変化をやわらげる向きに平衡が移動する。加圧→分子数が減る向き、昇温→吸熱の向き。触媒では移動しない。' },
      { h: '電離平衡と電離定数', t: '弱酸は水中で一部だけ電離し、電離平衡の状態になります。例:CH₃COOH ⇄ CH₃COO⁻＋H⁺。\nこの平衡の平衡定数 Ka＝[CH₃COO⁻][H⁺]/[CH₃COOH] を【電離定数】(酸解離定数)といいます。水の濃度はほぼ一定なので式に入れません。Ka が大きいほど強い酸です。\n濃度 c(mol/L)の弱酸で電離度を α とすると、平衡時は [CH₃COOH]＝c(1−α)、[CH₃COO⁻]＝[H⁺]＝cα です。よって Ka＝cα²/(1−α)。\nα が 1 より十分小さいとき 1−α≒1 とみなせるので、Ka≒cα²、α≒√(Ka/c)、[H⁺]＝cα≒√(cKa) となります。\nこの式から、弱酸はうすくするほど電離度 α が大きくなることがわかります。',
        key: '弱酸では α≒√(Ka/c)、[H⁺]≒√(cKa)(α が十分小さいとき)。',
        ex: [{ q: '0.050 mol/L の1価の弱酸 HA の水溶液がある。電離定数 Ka＝2.0×10⁻⁵ mol/L のとき、電離度 α と pH を求めよう。', hint: 'α が小さいとみなして、[H⁺]≒√(cKa) を使います。', steps: ['cKa＝0.050×2.0×10⁻⁵＝1.0×10⁻⁶。', '[H⁺]≒√(1.0×10⁻⁶)＝1.0×10⁻³ mol/L。', 'pH＝3。', 'α＝[H⁺]/c＝1.0×10⁻³/0.050＝0.020。'], a: 'α＝0.020、pH＝3', check: 'α＝0.020 は 1 より十分小さいので、1−α≒1 とした近似が使えることを確かめます。' }] },
      { h: '水のイオン積と塩基の pH・塩の加水分解', t: '純粋な水もわずかに電離しています:H₂O ⇄ H⁺＋OH⁻。25℃では [H⁺][OH⁻]＝1.0×10⁻¹⁴ (mol/L)² が、どんな水溶液でも成り立ちます。これを【水のイオン積】Kw といいます。\n中性では [H⁺]＝[OH⁻]＝1.0×10⁻⁷ mol/L で pH＝7 です。塩基の水溶液では、まず [OH⁻] を求め、Kw を使って [H⁺] に直してから pH を出します。\n塩(えん)の水溶液が中性とは限りません。酢酸ナトリウム CH₃COONa の水溶液では、CH₃COO⁻＋H₂O ⇄ CH₃COOH＋OH⁻ が少し起こり、塩基性になります。これを【塩の加水分解】といいます。\n「弱酸と強塩基からできた塩は塩基性」「強酸と弱塩基からできた塩(NH₄Cl など)は酸性」と覚えておくと、判断が速くなります。',
        ex: [{ q: '0.010 mol/L の水酸化ナトリウム水溶液の pH を求めよう(25℃、NaOH は完全に電離する)。', hint: 'まず [OH⁻] を求め、水のイオン積で [H⁺] に直します。', steps: ['NaOH→Na⁺＋OH⁻ なので、[OH⁻]＝1.0×10⁻² mol/L。', '[H⁺]＝Kw/[OH⁻]＝1.0×10⁻¹⁴/1.0×10⁻²＝1.0×10⁻¹² mol/L。', 'pH＝12。'], a: 'pH＝12', check: '塩基性なので pH が 7 より大きくなっているか確かめます。[OH⁻] から直接「pH＝2」としてしまうのが典型的なまちがいです。' }] },
      { h: '緩衝液', t: '酢酸と酢酸ナトリウムの混合水溶液のように、弱酸とその塩(または弱塩基とその塩)を含む水溶液は、少量の酸や塩基を加えても pH がほとんど変わりません。このような溶液を【緩衝液】といい、その作用を緩衝作用といいます。\nなぜ変わらないのか:この溶液には CH₃COOH と CH₃COO⁻ がどちらも多量にあります。酸(H⁺)を加えると CH₃COO⁻＋H⁺→CH₃COOH で H⁺ が消費され、塩基(OH⁻)を加えると CH₃COOH＋OH⁻→CH₃COO⁻＋H₂O で OH⁻ が消費されます。\n計算:酢酸の電離定数の式を変形すると、[H⁺]＝Ka×[CH₃COOH]/[CH₃COO⁻]。緩衝液では、[CH₃COOH] は加えた酢酸の濃度、[CH₃COO⁻] は加えた酢酸ナトリウムの濃度とみなせます。\n身近な例として、血液は炭酸 H₂CO₃ と炭酸水素イオン HCO₃⁻ などのはたらきで、pH が約 7.4 に保たれています。',
        key: '緩衝液は弱酸とその塩の混合液。[H⁺]＝Ka×[酸]/[塩]。加えた H⁺ や OH⁻ が消費されるので pH が変わりにくい。',
        ex: [{ q: '1.0 L の水溶液に酢酸 0.20 mol と酢酸ナトリウム 0.10 mol を溶かした緩衝液の [H⁺] を求めよう。(酢酸の Ka＝2.7×10⁻⁵ mol/L)', hint: '[CH₃COOH]≒0.20 mol/L、[CH₃COO⁻]≒0.10 mol/L とみなします。', steps: ['酢酸ナトリウムはほぼ完全に電離するので、[CH₃COO⁻]≒0.10 mol/L。', '酢酸は CH₃COO⁻ が多いため電離がおさえられ、[CH₃COOH]≒0.20 mol/L とみなせる。', '[H⁺]＝Ka×[CH₃COOH]/[CH₃COO⁻]＝2.7×10⁻⁵×0.20/0.10。', '計算すると [H⁺]＝5.4×10⁻⁵ mol/L。'], a: '5.4×10⁻⁵ mol/L(pH は約 4.3)', check: '酸と塩が同じ濃度なら [H⁺]＝Ka です。今回は酸が2倍なので、[H⁺] も Ka の2倍になっているかを確かめます。' }] },
      { h: '溶解度積', t: '水に溶けにくい塩も、ごくわずかに溶けて平衡になります。例:AgCl(固) ⇄ Ag⁺＋Cl⁻。\nこのとき [Ag⁺][Cl⁻] は温度が一定なら一定の値になり、これを【溶解度積】Ksp といいます。固体の濃度は一定なので式に入れません。AgCl の Ksp は 25℃で約 1.8×10⁻¹⁰ (mol/L)² です。\n沈殿ができるかの判定:混合した直後のイオン濃度の積 [Ag⁺][Cl⁻] を計算し、Ksp より大きければ沈殿が生じ、Ksp 以下なら沈殿は生じません。\nAgCl の飽和水溶液に NaCl を加えると、Cl⁻ が増えるので平衡が左に移動し、AgCl がさらに沈殿します。このように、共通のイオンを加えると溶解度が小さくなる現象を【共通イオン効果】といいます。',
        key: 'イオン濃度の積＞Ksp なら沈殿が生じる。共通イオンを加えると溶けにくくなる。' },
      { h: 'もっと深く:平衡定数と反応速度のつながり', t: '平衡定数 K と反応速度は、別々の話に見えますが、じつは深くつながっています。1段階で進む可逆反応 A ⇄ B を考えましょう。正反応の速さは v₁＝k₁[A]、逆反応の速さは v₂＝k₂[B] と表せます。\n平衡状態では v₁＝v₂ なので、k₁[A]＝k₂[B]、つまり [B]/[A]＝k₁/k₂ になります。左辺は平衡定数 K そのものです。K は「正反応と逆反応の速度定数の比」なのです(多段階の反応でも、K が濃度によらない定数になることは変わりません)。\n速度定数 k は温度で変わりますが、濃度では変わりません。だから K も温度だけで決まり、濃度や圧力を変えても変わりません。濃度を変えると平衡が移動するのは、K を一定に保つように各物質の濃度が調整されるからです。\n温度を上げると、k₁ も k₂ も大きくなりますが、ふえ方がちがいます。活性化エネルギーが大きい反応ほど、温度による速さの変化が大きいのです。発熱反応では、逆反応(吸熱方向)の活性化エネルギーのほうが大きいので、温度を上げると k₂ のほうが大きくふえ、K は小さくなります。これは、ルシャトリエの原理で「温度を上げると吸熱方向に移動する」というのと一致します。\n触媒は、正反応と逆反応の活性化エネルギーを同じだけ下げるので、k₁ と k₂ を同じ割合で大きくします。だから K は変わらず、平衡に達するまでの時間だけが短くなります。',
        key: 'K＝k₁/k₂。速度定数は温度だけで変わるので、K も温度だけで決まる。触媒は k₁・k₂ を同じ割合で大きくする。' },
      { h: '入試ではこう出る:平衡の量計算は「反応前・変化量・平衡時」の表で', t: '平衡の計算問題は、ほぼ必ず「反応前・変化量・平衡時」の3行の表をつくると解けます。変化量は、反応式の【係数の比】になるので、未知数は1つにまとまります。\n気体の反応で注意するのは、平衡定数が【濃度】(mol/L)で定義されていることです。容器の体積が 1 L でない場合は、物質量を体積で割ってから代入します。ただし H₂＋I₂ ⇄ 2HI のように左右の係数の和が等しい反応では、体積が約分されて消えるので、物質量のまま代入しても同じ結果になります。\n電離平衡では、電離度 α が小さいとき 1−α≒1 と近似して、α＝√(Ka/c)、[H⁺]＝√(cKa) を使うのが定番です。近似を使ってよいかは、求めた α が 0.05 程度以下になっているかで確かめられます。\n緩衝液に少量の酸や塩基を加える問題では、加えた H⁺ や OH⁻ が、まず緩衝液の成分と完全に反応すると考えて物質量を書きかえ、そのあとで [H⁺]＝Ka×[酸]/[塩] に代入します。\n時間配分のコツ:pH の問題では log 2＝0.30、log 3＝0.48 がよく与えられます。答えの数値が 2 や 3 の積になるように問題がつくられていることが多いので、途中で 2ⁿ×3ᵐ の形を意識すると計算が速くなります。',
        key: '「反応前・変化量・平衡時」の表。K は濃度で代入(係数の和が左右で等しいときは体積が消える)。',
        ex: [{ q: '容積 1.0 L の容器に四酸化二窒素 N₂O₄ 0.50 mol を入れて一定温度に保つと、N₂O₄ ⇄ 2NO₂ の平衡に達し、N₂O₄ の 20% が解離していた。この温度での平衡定数 K を求めよ。', hint: '解離した N₂O₄ の物質量の2倍の NO₂ ができます。', steps: ['解離した N₂O₄ は 0.50×0.20＝0.10 mol。', '表をつくる:反応前 N₂O₄ 0.50、NO₂ 0。変化量 N₂O₄ −0.10、NO₂ ＋0.20。平衡時 N₂O₄ 0.40、NO₂ 0.20(mol)。', '体積は 1.0 L なので、[N₂O₄]＝0.40 mol/L、[NO₂]＝0.20 mol/L。', 'K＝[NO₂]²/[N₂O₄]＝0.20²/0.40＝0.10 mol/L。'], a: 'K＝0.10 mol/L', check: 'この反応は左右の係数の和が 1 と 2 でちがうので、K に単位(mol/L)が残り、体積は約分されません。もし容器が 2.0 L なら、物質量を 2.0 で割った濃度を代入しないと正しい K になりません。' },
          { q: '酢酸 0.10 mol と酢酸ナトリウム 0.10 mol を含む水溶液 1.0 L に、塩化水素 0.010 mol を加えた(体積変化は無視)。加える前と後の [H⁺] を求めよ。(酢酸の Ka＝2.7×10⁻⁵ mol/L)', hint: '加えた H⁺ は、酢酸イオンと反応して酢酸になると考えます。', steps: ['加える前:[H⁺]＝Ka×[CH₃COOH]/[CH₃COO⁻]＝2.7×10⁻⁵×0.10/0.10＝2.7×10⁻⁵ mol/L。', 'HCl を加えると CH₃COO⁻＋H⁺→CH₃COOH が起こる。CH₃COO⁻ は 0.10−0.010＝0.090 mol、CH₃COOH は 0.10＋0.010＝0.11 mol になる。', '加えた後:[H⁺]＝2.7×10⁻⁵×0.11/0.090≒3.3×10⁻⁵ mol/L。', 'pH にすると、約 4.57 から約 4.48 へと、0.1 程度しか変わらない。'], a: '加える前 2.7×10⁻⁵ mol/L、加えた後 約 3.3×10⁻⁵ mol/L', check: '同じ 0.010 mol の HCl を純水 1.0 L に加えると [H⁺]＝1.0×10⁻² mol/L(pH 2)になります。緩衝液では [H⁺] が約 1.2 倍にしかならず、緩衝作用がはたらいていることが確かめられます。' }] }
    ],
    drill: [
      { lv: 1, q: '0.10 mol/L の塩酸を水で 100 倍に薄めた水溶液の pH はいくつか。(塩化水素は完全に電離する)', a: '3', exp: '100 倍に薄めると濃度は 0.10÷100＝1.0×10⁻³ mol/L です。\n塩化水素は1価の強酸で完全に電離するので、[H⁺]＝1.0×10⁻³ mol/L、pH＝3 です。\n強酸は 10 倍に薄めるごとに pH が 1 ずつ大きくなります(ただし pH 7 をこえることはありません)。' },
      { lv: 1, q: '2SO₂(気)＋O₂(気) ⇄ 2SO₃(気) ΔH＜0 が平衡状態にある。(1)温度一定で加圧する (2)圧力一定で温度を上げる (3)触媒を加える のとき、平衡はそれぞれどちらに移動するか。', a: '(1)右 (2)左 (3)移動しない', exp: '(1)加圧すると、気体の分子の数がへる向き(左辺 3 分子→右辺 2 分子)に移動するので右です。\n(2)温度を上げると吸熱の向きに移動します。正反応が発熱(ΔH＜0)なので、逆反応の向き、つまり左です。\n(3)触媒は正反応・逆反応を同じ割合で速くするだけなので、平衡は移動しません。' },
      { lv: 1, q: '反応速度式が v＝k[A][B] で表される反応で、[A] を 2 倍、[B] を 3 倍にすると、反応速度は何倍になるか。(温度は一定)', a: '6 倍', exp: '速度定数 k は温度が一定なら変わりません。v は [A] と [B] のそれぞれに比例するので、2×3＝6 倍になります。' },
      { lv: 2, q: '反応速度が温度 10 K 上昇ごとに 2 倍になる反応がある。20℃から 50℃にすると、反応速度は何倍になるか。', a: '8 倍', exp: '温度差は 30 K で、10 K ごとに 2 倍になるので、2×2×2＝2³＝8 倍です。\n足し算(2＋2＋2)ではなく、かけ算になる点に注意しましょう。温度が上がると、活性化エネルギーをこえるエネルギーをもつ分子の割合が急にふえるためです。' },
      { lv: 2, q: '0.050 mol/L のアンモニア水の pH を求めよ。(アンモニアの電離定数 Kb＝2.0×10⁻⁵ mol/L、Kw＝1.0×10⁻¹⁴ (mol/L)²、電離度は 1 より十分小さいとする)', a: '11', exp: '弱塩基では弱酸と同じ考え方で、[OH⁻]＝√(cKb) です。\n[OH⁻]＝√(0.050×2.0×10⁻⁵)＝√(1.0×10⁻⁶)＝1.0×10⁻³ mol/L。\n[H⁺]＝Kw/[OH⁻]＝1.0×10⁻¹¹ mol/L なので pH＝11。電離度は 1.0×10⁻³/0.050＝0.02 で、近似は妥当です。' },
      { lv: 2, q: '塩化銀の溶解度積を Ksp＝1.8×10⁻¹⁰ (mol/L)² とする。0.010 mol/L 塩化ナトリウム水溶液に、塩化銀は何 mol/L まで溶けるか。', a: '1.8×10⁻⁸ mol/L', exp: '溶ける AgCl を s mol/L とすると、[Ag⁺]＝s、[Cl⁻]＝0.010＋s です。s はとても小さいので [Cl⁻]≒0.010 mol/L とします。\nKsp＝[Ag⁺][Cl⁻] より、s＝1.8×10⁻¹⁰/0.010＝1.8×10⁻⁸ mol/L。\n純水への溶解度 √(1.8×10⁻¹⁰)≒1.3×10⁻⁵ mol/L と比べると約 1/700 で、【共通イオン効果】で溶けにくくなっていることが分かります。' },
      { lv: 3, q: 'N₂O₄ ⇄ 2NO₂ が全圧 1.0×10⁵ Pa で平衡に達し、N₂O₄ の解離度は 0.50 だった。圧平衡定数 Kp を求めよ。', a: '約 1.3×10⁵ Pa', exp: 'はじめの N₂O₄ を n mol とすると、平衡時は N₂O₄ 0.50n、NO₂ 1.0n、合計 1.5n mol です。\n分圧は全圧×モル分率なので、P(N₂O₄)＝1.0×10⁵×(1/3)、P(NO₂)＝1.0×10⁵×(2/3)。\nKp＝P(NO₂)²/P(N₂O₄)＝(4/9)/(1/3)×10⁵＝(4/3)×10⁵≒1.3×10⁵ Pa。\n一般に Kp＝4α²P/(1−α²) となり、α＝0.50、P＝1.0×10⁵ を入れても同じ値になります。' },
      { lv: 3, q: '1価の弱酸 HA(Ka＝1.0×10⁻⁵ mol/L)のナトリウム塩 NaA の 0.10 mol/L 水溶液の pH を求めよ。(Kw＝1.0×10⁻¹⁴ (mol/L)²)', a: '9', exp: 'A⁻ は水と反応して A⁻＋H₂O ⇄ HA＋OH⁻ となります(塩の加水分解)。この平衡定数は Kh＝Kw/Ka＝1.0×10⁻⁹ mol/L です。\n加水分解する割合は小さいので、[OH⁻]＝√(cKh)＝√(0.10×1.0×10⁻⁹)＝√(1.0×10⁻¹⁰)＝1.0×10⁻⁵ mol/L。\npOH＝5 なので pH＝14−5＝9。弱酸の塩は塩基性を示す、という結論が数値でも確かめられます。' }
    ],
    faq: [
      ['平衡状態では、反応は止まっているの?', '止まっていません。正反応と逆反応が同じ速さで起こり続けているため、それぞれの物質の量が変わらず、止まっているように見えるだけです。これを動的平衡といいます。'],
      ['触媒を加えても平衡が移動しないのはなぜ?', '触媒は正反応の活性化エネルギーも逆反応の活性化エネルギーも同じだけ下げ、両方を速くします。そのため、どちらか一方に偏ることがなく、平衡の位置(K の値)は変わりません。'],
      ['反応速度式の指数が、反応式の係数と一致しないことがあるのはなぜ?', '反応式は反応全体の結果を表しているだけで、実際には途中でいくつかの段階を経て進む反応が多いからです。いちばんおそい段階で速さが決まるため、指数は実験で求める必要があります。'],
      ['平衡定数の式に、固体や溶媒の水を入れないのはなぜ?', '固体や純粋な液体(溶媒の水など)は、反応で少し量が変わっても、その「濃さ」はほとんど変わらないからです。たとえば固体の炭素は、量が半分になっても固体の炭素そのものの密度は同じです。\n変わらない量は定数として平衡定数の中にまとめてしまうので、式には書きません。溶解度積 Ksp の式に固体の AgCl が入らないのも、水のイオン積 Kw に [H₂O] が入らないのも同じ理由です。']
    ],
    terms: [['活性化エネルギー', '反応物が遷移状態に達するのに必要な最小のエネルギー'], ['触媒', '活性化エネルギーを下げて反応を速くし、自身は変化しない物質'], ['化学平衡', '正反応と逆反応の速さが等しく、見かけ上反応が止まった状態'], ['平衡定数', '平衡時の濃度から決まる、温度だけで決まる定数 K'], ['ルシャトリエの原理', '条件の変化をやわらげる向きに平衡が移動するという原理'], ['電離定数', '弱酸・弱塩基の電離平衡の平衡定数(Ka・Kb)'], ['緩衝液', '少量の酸や塩基を加えても pH がほとんど変わらない溶液'], ['溶解度積', '難溶性の塩の飽和溶液でのイオン濃度の積 Ksp']],
    miss: ['触媒で平衡が移動すると考えてしまう。触媒は「速さ」を変えるだけで「到達点」は変えない、と区別します。', '温度を上げると必ず右に移動すると思いこむ。ΔH の符号を見て、吸熱の向きを確かめます。', '平衡定数の式で、係数を指数にし忘れる。2HI なら [HI]² です。', '塩基の pH で、[OH⁻] の指数をそのまま pH にしてしまう。必ず Kw を使って [H⁺] に直します。', '溶解度積の判定で、混合による体積変化(うすまり)を忘れる。混ぜた後の濃度で計算します。'],
    sum: ['反応速度は濃度・温度・触媒・表面積で変わる。触媒は活性化エネルギーを下げる。', '平衡定数 K は温度だけで決まる。「はじめ・変化・平衡」の表で計算する。', 'ルシャトリエの原理:変化をやわらげる向きに平衡が移動する。', '弱酸は [H⁺]≒√(cKa)。塩基は Kw＝1.0×10⁻¹⁴ で [H⁺] に直す。', '緩衝液は [H⁺]＝Ka×[酸]/[塩]。溶解度積は沈殿の判定に使う。'],
    next: '次は「電池と電気分解」に進みましょう。酸化還元反応をエネルギーの出入りとして利用するしくみを学びます。'
  };

  // ===== 電池と電気分解 =====
  L.c4_redox = {
    goal: 'ダニエル電池・鉛蓄電池・燃料電池の各電極の反応を書けるようになり、電気分解の生成物の判断とファラデーの法則による量計算ができるようになる。',
    intro: 'スマートフォンの電池も、自動車のバッテリーも、中では化学反応が起きています。逆に、電気を使えば、自然には起こらない反応を起こすこともできます。アルミニウムや水酸化ナトリウムは、電気の力でつくられています。この単元では、化学反応と電気のエネルギーを結びつける【電池】と【電気分解】を学びます。',
    pre: '【酸化】は電子を失うこと、【還元】は電子を受け取ることです。電子を失った物質があれば、必ずその電子を受け取った物質があるので、酸化と還元は同時に起こります。\n【酸化数】は、原子がどれだけ電子を失ったか(＋)、受け取ったか(−)を表す数です。単体の原子は 0、化合物中の H は＋1、O は−2 が基本です。酸化数が増えれば酸化された、減れば還元されたことになります。\n金属が水溶液中で陽イオンになろうとする性質を【イオン化傾向】といいます。大きい順に K＞Ca＞Na＞Mg＞Al＞Zn＞Fe＞Ni＞Sn＞Pb＞(H₂)＞Cu＞Hg＞Ag＞Pt＞Au です。\n電流の向きは、電子の流れる向きと逆です。電子は負極から導線を通って正極へ流れます。\n電気量の単位は C(クーロン)で、電気量(C)＝電流(A)×時間(s) です。',
    secs: [
      { h: '電池のしくみ', t: '酸化還元反応で移動する電子を、導線を通して取り出すしくみが【電池】(化学電池)です。化学エネルギーを電気エネルギーに変えています。\n電子を出す(酸化反応が起こる)電極を【負極】、電子を受け取る(還元反応が起こる)電極を【正極】といいます。2種類の金属を使う電池では、イオン化傾向の大きい金属が負極になります。\n電極で実際に反応して電子をやりとりする物質を【活物質】といいます。両極の間の電位差を【起電力】といい、電池の能力を表します。\n放電すると元にもどせない電池を【一次電池】(マンガン乾電池・アルカリマンガン乾電池など)、充電してくり返し使える電池を【二次電池】(鉛蓄電池・リチウムイオン電池など)といいます。充電は、外部の電源で放電と逆向きの反応を起こすことです。',
        key: '負極=電子を出す(酸化)、正極=電子を受け取る(還元)。イオン化傾向の大きい金属が負極。' },
      { h: 'ダニエル電池', t: '【ダニエル電池】は、亜鉛板を硫酸亜鉛 ZnSO₄ 水溶液に、銅板を硫酸銅(Ⅱ) CuSO₄ 水溶液に入れ、2つの水溶液を素焼き板で仕切った電池です。電池式は (−)Zn|ZnSO₄aq|CuSO₄aq|Cu(＋) と表します。\n負極:Zn→Zn²⁺＋2e⁻(亜鉛が溶けて電子を出す)。正極:Cu²⁺＋2e⁻→Cu(銅(Ⅱ)イオンが電子を受け取り、銅が析出する)。全体では Zn＋Cu²⁺→Zn²⁺＋Cu で、起電力は約 1.1 V です。\n素焼き板は、2つの水溶液がすぐに混ざるのを防ぎながら、イオンは通します。放電が進むと負極側では Zn²⁺ が増え、正極側では Cu²⁺ が減るので、イオンが素焼き板を通って移動し、電気的なつり合いが保たれます。\n長く電流を取り出すには、ZnSO₄ 水溶液をうすく、CuSO₄ 水溶液を濃くすると有利です。正極で反応する Cu²⁺ が多くあれば、それだけ長く反応が続くからです。',
        fig: DANIELL,
        key: 'ダニエル電池:負極 Zn→Zn²⁺＋2e⁻、正極 Cu²⁺＋2e⁻→Cu。起電力約 1.1 V。',
        ex: [{ q: 'ダニエル電池を放電させて、電子 0.20 mol が流れた。亜鉛板と銅板の質量はそれぞれどう変化する?(Zn＝65、Cu＝64)', hint: 'どちらの反応も、電子 2 mol で金属 1 mol が変化します。', steps: ['負極 Zn→Zn²⁺＋2e⁻ より、電子 0.20 mol で Zn は 0.10 mol 溶ける。', '亜鉛板は 65×0.10＝6.5 g 減る。', '正極 Cu²⁺＋2e⁻→Cu より、Cu は 0.10 mol 析出する。', '銅板は 64×0.10＝6.4 g 増える。'], a: '亜鉛板は 6.5 g 減少、銅板は 6.4 g 増加', check: '負極では金属が溶け(減る)、正極では金属が析出する(増える)という向きが合っているかを確かめます。' }] },
      { h: '実用電池:鉛蓄電池と燃料電池', t: '【鉛蓄電池】は、負極に鉛 Pb、正極に酸化鉛(Ⅳ) PbO₂、電解液に希硫酸を使った二次電池で、起電力は約 2.0 V です。自動車のバッテリーに使われています。\n負極:Pb＋SO₄²⁻→PbSO₄＋2e⁻。正極:PbO₂＋4H⁺＋SO₄²⁻＋2e⁻→PbSO₄＋2H₂O。全体:Pb＋PbO₂＋2H₂SO₄→2PbSO₄＋2H₂O。\n放電すると、両極とも水に溶けにくい PbSO₄ でおおわれて質量が増え、硫酸が消費され水ができるので、電解液の濃度(密度)が下がります。充電すると逆の反応が起こり、元にもどります。\n【燃料電池】は、水素などの燃料と酸素を外から供給し続けて電気を取り出す装置です。リン酸形燃料電池では、負極:H₂→2H⁺＋2e⁻、正極:O₂＋4H⁺＋4e⁻→2H₂O、全体:2H₂＋O₂→2H₂O で、起電力は約 1.2 V です。生成物が水だけなので、環境への負担が小さいのが特長です。\nほかに、マンガン乾電池(約 1.5 V、一次電池)や、スマートフォンなどに使われるリチウムイオン電池(約 3.7 V、二次電池)があります。',
        key: '鉛蓄電池:(−)Pb|H₂SO₄aq|PbO₂(＋)。放電で両極が PbSO₄ になり質量が増え、硫酸がうすくなる。',
        ex: [{ q: '鉛蓄電池を放電させて、電子 0.20 mol が流れた。負極と正極の質量はそれぞれ何 g 増える?(O＝16、S＝32)', hint: '負極は Pb→PbSO₄(SO₄ 分増える)、正極は PbO₂→PbSO₄(SO₂ 分増える)です。', steps: ['どちらの電極も、電子 2 mol で 1 mol が PbSO₄ に変わる。電子 0.20 mol なので 0.10 mol ずつ変化する。', '負極:Pb→PbSO₄ で SO₄(式量 96)が加わる → 96×0.10＝9.6 g 増加。', '正極:PbO₂→PbSO₄ で、O₂ が SO₄ に変わる。差は SO₂ 分(式量 64)→ 64×0.10＝6.4 g 増加。'], a: '負極 9.6 g 増加、正極 6.4 g 増加', check: '放電では両極とも PbSO₄ になり質量が増える、という性質と合っています。' }] },
      { h: '電気分解のしくみ', t: '外部の電源から電気エネルギーを加えて、自然には起こらない酸化還元反応を起こすことを【電気分解】といいます。\n電源の負極につないだ電極を【陰極】、正極につないだ電極を【陽極】といいます。陰極には電子が流れこむので還元反応、陽極からは電子が出ていくので酸化反応が起こります。電池の「負極・正極」と名前を混同しないようにしましょう。\n陰極(還元)で何が起こるか:Cu²⁺ や Ag⁺ のようにイオン化傾向の小さい金属のイオンがあれば、金属が析出します(Cu²⁺＋2e⁻→Cu)。K⁺・Na⁺・Al³⁺ などイオン化傾向の大きい金属のイオンは還元されにくいので、代わりに水が還元されて水素が発生します(2H₂O＋2e⁻→H₂＋2OH⁻)。酸性の水溶液では 2H⁺＋2e⁻→H₂ です。\n陽極(酸化)で何が起こるか:白金や炭素の電極では、Cl⁻ や I⁻ があればそれが酸化されます(2Cl⁻→Cl₂＋2e⁻)。SO₄²⁻ や NO₃⁻ は酸化されにくいので、水が酸化されて酸素が発生します(2H₂O→O₂＋4H⁺＋4e⁻)。塩基性の水溶液では 4OH⁻→O₂＋2H₂O＋4e⁻ です。\n陽極に銅や銀を使うと、電極自身が酸化されて溶け出します(Cu→Cu²⁺＋2e⁻)。',
        key: '陰極=還元、陽極=酸化。イオン化傾向の大きい金属イオンや SO₄²⁻・NO₃⁻ は反応せず、代わりに水が反応する。' },
      { h: 'ファラデーの法則と量計算', t: '電気分解で変化する物質の量は、流れた電気量に比例します。これを【ファラデーの法則】といいます。\n電子 1 mol がもつ電気量の大きさを【ファラデー定数】F といい、F＝9.65×10⁴ C/mol です。したがって、流れた電子の物質量(mol)＝電気量(C)÷9.65×10⁴＝電流(A)×時間(s)÷9.65×10⁴。\n量計算の手順は、①電子の物質量を求める、②各電極の反応式から「電子何 mol で物質何 mol か」を読む、③質量や気体の体積に直す、の3段階です。\n例えば陰極 Ag⁺＋e⁻→Ag なら電子 1 mol で Ag 1 mol、Cu²⁺＋2e⁻→Cu なら電子 2 mol で Cu 1 mol、陽極 2H₂O→O₂＋4H⁺＋4e⁻ なら電子 4 mol で O₂ 1 mol です。',
        key: '電子の mol＝It÷(9.65×10⁴)。まず電子の mol を出し、反応式の係数で物質の mol に直す。',
        ex: [{ q: '硝酸銀 AgNO₃ 水溶液を白金電極で、2.0 A の電流を 965 秒間流して電気分解した。陰極に析出する銀の質量と、陽極で発生する気体の物質量を求めよう。(Ag＝108、F＝9.65×10⁴ C/mol)', hint: '陽極では、NO₃⁻ ではなく水が酸化されます。', steps: ['電気量は 2.0×965＝1930 C。電子は 1930÷(9.65×10⁴)＝0.020 mol。', '陰極:Ag⁺＋e⁻→Ag より、Ag は 0.020 mol → 108×0.020＝2.16 g≒2.2 g。', '陽極:2H₂O→O₂＋4H⁺＋4e⁻ より、O₂ は 0.020÷4＝0.0050 mol。'], a: '銀 約 2.2 g、酸素 5.0×10⁻³ mol', check: '陰極で受け取った電子と陽極で出た電子は同じ 0.020 mol になっているかを確かめます(Ag 0.020 mol×1、O₂ 0.0050 mol×4)。' },
          { q: '塩化ナトリウム水溶液を、陽極に炭素、陰極に鉄を使って電気分解し、電子 0.10 mol を流した。両極で発生する気体の体積は、標準状態でそれぞれ何 L?(気体 1 mol は標準状態で 22.4 L)', hint: '陽極では Cl⁻、陰極では水が反応します。', steps: ['陽極:2Cl⁻→Cl₂＋2e⁻ より、Cl₂ は 0.10÷2＝0.050 mol。', '陰極:2H₂O＋2e⁻→H₂＋2OH⁻ より、H₂ は 0.10÷2＝0.050 mol。', '体積はどちらも 22.4×0.050＝1.12 L。'], a: '陽極 Cl₂ 1.12 L、陰極 H₂ 1.12 L', check: '陰極付近では OH⁻ が 0.10 mol でき、溶液中の Na⁺ と合わせて NaOH ができます。これが工業的な NaOH の製法につながります。' }] },
      { h: '電気分解の工業への応用', t: '【水酸化ナトリウムの製造】(イオン交換膜法):塩化ナトリウム水溶液を、陽イオンだけを通す膜で仕切って電気分解します。陽極では 2Cl⁻→Cl₂＋2e⁻、陰極では 2H₂O＋2e⁻→H₂＋2OH⁻ が起こり、Na⁺ が膜を通って陰極側に移るので、純度の高い NaOH が得られます。\n【銅の電解精錬】:粗銅(不純物を含む銅)を陽極、純銅を陰極にして、硫酸銅(Ⅱ)水溶液を電気分解します。陽極では銅が Cu²⁺ になって溶け出し、陰極に純粋な銅が析出します。\n粗銅に含まれる不純物のうち、銅よりイオン化傾向の大きい Zn・Fe・Ni などは陽イオンとなって溶液中に残ります。銅よりイオン化傾向の小さい Ag・Au などは溶けずに陽極の下にたまります(【陽極泥】)。\n【アルミニウムの製造】(溶融塩電解):アルミニウムはイオン化傾向が大きく、水溶液の電気分解では得られません。そこで、氷晶石 Na₃AlF₆ を融解したものに酸化アルミニウム Al₂O₃ を溶かし、炭素電極で電気分解します。陰極に Al が得られます。',
        key: 'NaOH はイオン交換膜法、銅は電解精錬(陽極泥に Ag・Au)、Al は氷晶石を使った溶融塩電解でつくる。' },
      { h: 'もっと深く:電子はなぜ流れるのか ― イオン化傾向と電池の電圧', t: '電池で電子が流れるのは、2つの金属の「電子を手放したがる度合い(イオン化傾向)」に差があるからです。ダニエル電池では、亜鉛のほうが銅よりイオンになりやすいので、亜鉛が電子を放出し、その電子が導線を通って銅板側に移り、そこで Cu²⁺ が電子を受けとります。\nイオン化傾向の差が大きい組み合わせほど、電子を押し出す力が強く、電池の電圧(起電力)が大きくなります。ダニエル電池の起電力は約 1.1 V です。高校の範囲をこえますが、この「押し出す力」を数値で表したものを標準電極電位といい、2つの電極の値の差が起電力になります。\n素焼き板や塩橋はなぜ必要なのでしょうか。放電が進むと、亜鉛側の溶液では Zn²⁺ がふえて陽イオンが多くなり、銅側では Cu²⁺ がへって陰イオン(SO₄²⁻)が多くなります。このままだと電気的なかたよりが反応を止めてしまいます。素焼き板はイオンを少しずつ通すので、両側の電荷のかたよりを打ち消し、反応を続けさせます。一方で、2つの溶液がすぐには混ざらないようにもしています。\n電気分解は、電池とは反対に、外から電圧をかけて、自然には起こらない向きの酸化還元反応を起こすことです。たとえば水の電気分解は、水素と酸素から水ができる反応(燃料電池の反応)の逆向きです。そのため電気分解には、その逆反応の電池がつくる電圧より大きな電圧が必要になります。\nこのように、電池と電気分解は「自然に進む向き」と「無理に進める向き」の関係にあり、どちらも電子の受けわたし(酸化還元)で説明できます。',
        key: 'イオン化傾向の差が大きいほど起電力が大きい。素焼き板はイオンを通して電荷のかたよりを打ち消す。電気分解は電池の逆向き。' },
      { h: '入試ではこう出る:電子の物質量を軸にすべてをつなぐ', t: '電池・電気分解の計算は、ほぼすべて【流れた電子の物質量】を中心に考えると解けます。電気量 Q(C)＝電流(A)×時間(s)、電子の物質量＝Q÷F(F＝9.65×10⁴ C/mol)です。\n電解槽を【直列】につないだ場合は、どの電解槽にも同じ電気量が流れます。【並列】の場合は、それぞれに流れた電気量の和が全体の電気量になります。直列か並列かを最初に確認しましょう。\n電子の物質量が分かったら、各電極の反応式の係数から、析出・発生する物質の物質量を求めます。たとえば Cu²⁺＋2e⁻→Cu なら電子 2 mol で銅 1 mol、2H₂O→O₂＋4H⁺＋4e⁻ なら電子 4 mol で酸素 1 mol です。\n鉛蓄電池では、全体の反応 Pb＋PbO₂＋2H₂SO₄→2PbSO₄＋2H₂O より、電子 2 mol が流れると硫酸 2 mol が消費され、水 2 mol ができます。電解液の濃度変化を求める問題では、溶質(H₂SO₄)の減少と、溶液の質量変化(H₂SO₄ がへり H₂O がふえる)の両方を考えます。\nひっかけは、陽極に銅や銀などの金属を使った場合です。このときは陰イオンではなく、陽極の金属自身が溶け出します。電極の種類は必ず確認しましょう。',
        key: 'まず電子の物質量(Q/F)。直列なら同じ電気量。各電極の半反応式の係数で物質量に変換する。',
        ex: [{ q: '硫酸銅(Ⅱ)水溶液の入った電解槽 A と、硝酸銀水溶液の入った電解槽 B を直列につなぎ、白金電極を使って 5.0 A の電流を 1930 秒間流した。A・B の陰極に析出する金属の質量をそれぞれ求めよ。(Cu＝64、Ag＝108、F＝9.65×10⁴ C/mol)', hint: '直列なので、A にも B にも同じ量の電子が流れます。', steps: ['電気量は 5.0×1930＝9650 C。電子の物質量は 9650÷(9.65×10⁴)＝0.10 mol。', 'A の陰極:Cu²⁺＋2e⁻→Cu。銅は 0.10÷2＝0.050 mol、質量は 0.050×64＝3.2 g。', 'B の陰極:Ag⁺＋e⁻→Ag。銀は 0.10 mol、質量は 0.10×108＝10.8 g。', '直列なので、両方とも同じ 0.10 mol の電子で計算すればよい。'], a: 'A の陰極に銅 3.2 g、B の陰極に銀 10.8 g(約 11 g)', check: '銅と銀の物質量の比は 0.050:0.10＝1:2 で、イオンの価数の比(2:1)の逆になっています。同じ電子の量なら、価数が大きいイオンほど析出する物質量は少なくなります。' },
          { q: '質量パーセント濃度 30% の硫酸 1000 g を電解液とする鉛蓄電池を放電させ、電子 0.20 mol が流れた。放電後の硫酸の質量パーセント濃度を求めよ。(H₂SO₄＝98、H₂O＝18)', hint: '電子 2 mol で H₂SO₄ が 2 mol へり、H₂O が 2 mol ふえます。', steps: ['はじめの H₂SO₄ は 1000×0.30＝300 g。', '電子 0.20 mol で H₂SO₄ が 0.20 mol(0.20×98＝19.6 g)へり、H₂O が 0.20 mol(0.20×18＝3.6 g)ふえる。', '放電後の H₂SO₄ は 300−19.6＝280.4 g、溶液は 1000−19.6＋3.6＝984.0 g。', '濃度は 280.4÷984.0×100≒28.5%。'], a: '約 28.5%', check: '放電で濃度が下がるのは、硫酸が PbSO₄ として電極に取りこまれ、水ができるからです。充電するとこの逆が起こり、濃度はもとにもどります。' }] }
    ],
    drill: [
      { lv: 1, q: '硫酸銅(Ⅱ)水溶液を白金電極で電気分解し、2.0 A の電流を 1930 秒間流した。陰極に析出する銅は何 g か。(Cu＝64、F＝9.65×10⁴ C/mol)', a: '約 1.3 g', exp: '電気量は 2.0×1930＝3860 C、電子は 3860÷(9.65×10⁴)＝0.040 mol です。\n陰極では Cu²⁺＋2e⁻→Cu なので、銅は 0.040÷2＝0.020 mol、質量は 0.020×64＝1.28≒1.3 g です。' },
      { lv: 1, q: '次の下線の原子の酸化数を答えよ。(1)K₂Cr₂O₇ の Cr (2)MnO₄⁻ の Mn (3)H₂O₂ の O', a: '(1)＋6 (2)＋7 (3)−1', exp: '化合物全体の酸化数の和は 0、イオンではイオンの電荷に等しくなります。K は ＋1、O はふつう −2、H は ＋1 です。\n(1)2×(＋1)＋2x＋7×(−2)＝0 より x＝＋6。(2)x＋4×(−2)＝−1 より x＝＋7。\n(3)過酸化水素は例外で、2×(＋1)＋2y＝0 より y＝−1 です。O が −1 なので、酸化剤にも還元剤にもなれます。' },
      { lv: 1, q: '水酸化ナトリウム水溶液を白金電極で電気分解し、電子 0.40 mol を流した。陰極と陽極で発生する気体の名前と、標準状態での体積を答えよ。(気体 1 mol は標準状態で 22.4 L)', a: '陰極:水素 4.48 L、陽極:酸素 2.24 L', exp: '陰極では 2H₂O＋2e⁻→H₂＋2OH⁻ で、Na⁺ は還元されません。電子 2 mol で水素 1 mol なので、0.20 mol＝4.48 L。\n陽極では 4OH⁻→O₂＋2H₂O＋4e⁻ で、電子 4 mol で酸素 1 mol なので、0.10 mol＝2.24 L。\n水素と酸素の体積比は 2:1 で、全体として水が分解されたことになります。' },
      { lv: 2, q: '鉄板に亜鉛をめっきしたトタンと、スズをめっきしたブリキがある。どちらも表面に傷がついて鉄が露出したとき、鉄がさびにくいのはどちらか。理由も答えよ。', a: 'トタン。亜鉛は鉄よりイオン化傾向が大きく、亜鉛が先に酸化されて鉄を守るから。', exp: '傷口では、めっきの金属と鉄が水を介して電池をつくります。イオン化傾向が大きいほうが負極となって酸化され(溶け)ます。\nトタンでは Zn＞Fe なので亜鉛が溶け、鉄は守られます。ブリキでは Fe＞Sn なので鉄のほうが溶け、傷がつくとかえって鉄がさびやすくなります。\nブリキは傷がつかなければ、スズがイオン化しにくいのでさびにくく、缶詰の内側などに使われます。' },
      { lv: 2, q: '粗銅を陽極、純銅を陰極にして、硫酸銅(Ⅱ)水溶液中で電解精錬を行った。電子 0.50 mol を流したとき、陰極の質量は何 g 増加するか。また、陽極の下にたまる沈殿(陽極泥)に含まれる金属を2つ答えよ。(Cu＝64)', a: '16 g 増加。陽極泥には銀・金など。', exp: '陰極では Cu²⁺＋2e⁻→Cu だけが起こるので、銅は 0.50÷2＝0.25 mol、0.25×64＝16 g 増えます。\n陽極では銅だけでなく、銅よりイオン化傾向が大きい亜鉛・鉄・ニッケルなども溶け出します。一方、銅よりイオン化傾向が小さい銀や金は溶けずに、陽極の下に陽極泥としてたまります。\nそのため、陽極の質量の減少は、陰極の増加(16 g)とは一致しません。' },
      { lv: 2, q: '濃度不明の過酸化水素水 10.0 mL を硫酸で酸性にし、0.020 mol/L の過マンガン酸カリウム水溶液で滴定したところ、16.0 mL で反応が終わった。過酸化水素水のモル濃度を求めよ。', a: '0.080 mol/L', exp: '半反応式は MnO₄⁻＋8H⁺＋5e⁻→Mn²⁺＋4H₂O、H₂O₂→O₂＋2H⁺＋2e⁻ です。電子の数をそろえると、MnO₄⁻ 2 mol と H₂O₂ 5 mol が反応します。\nMnO₄⁻ は 0.020×0.0160＝3.2×10⁻⁴ mol なので、H₂O₂ は 3.2×10⁻⁴×5/2＝8.0×10⁻⁴ mol。\n濃度は 8.0×10⁻⁴÷0.0100＝0.080 mol/L。「酸化剤が受けとる電子の物質量＝還元剤が出す電子の物質量」と考えても同じ式になります。' },
      { lv: 3, q: 'リン酸形燃料電池で、標準状態で 0.448 L の水素が消費された。このとき 0.50 A の電流が流れ続けたとすると、何秒間発電したことになるか。(気体 1 mol は標準状態で 22.4 L、F＝9.65×10⁴ C/mol)', a: '7720 秒', exp: '水素は 0.448÷22.4＝0.020 mol です。負極では H₂→2H⁺＋2e⁻ なので、電子は 0.040 mol 流れます。\n電気量は 0.040×9.65×10⁴＝3860 C。\n時間＝電気量÷電流＝3860÷0.50＝7720 秒(約 2 時間 9 分)です。' },
      { lv: 3, q: '塩化ナトリウム水溶液を、陽イオン交換膜で仕切った装置で電気分解し(陽極は炭素、陰極は鉄)、電子 2.0 mol を流した。陰極側で生じる水酸化ナトリウムは何 g か。また、陽イオン交換膜を使う理由を答えよ。(NaOH＝40)', a: '80 g。陽極で生じた塩素と、陰極側の水酸化物イオンが混ざって反応するのを防ぐため。', exp: '陰極では 2H₂O＋2e⁻→H₂＋2OH⁻ で、電子 2.0 mol から OH⁻ が 2.0 mol できます。陽極側の Na⁺ が膜を通って陰極側に移動するので、陰極側に NaOH が 2.0 mol、つまり 80 g できます。\n陽イオン交換膜は陽イオン(Na⁺)だけを通し、陰イオン(OH⁻・Cl⁻)を通しません。もし OH⁻ が陽極側に移ると、塩素と反応してしまい、純粋な NaOH が得られなくなります。\nこの方法を【イオン交換膜法】といい、水酸化ナトリウムの工業的製法です。' }
    ],
    faq: [
      ['電池の「負極・正極」と、電気分解の「陰極・陽極」はどう対応するの?', '電池の負極と電気分解の陽極は、どちらも電子を出す(酸化)電極です。電池の正極と電気分解の陰極は、どちらも電子を受け取る(還元)電極です。名前ではなく「酸化か還元か」で考えると混乱しません。'],
      ['水溶液の電気分解で、Na⁺ が還元されないのはなぜ?', 'Na はイオン化傾向がとても大きく、Na⁺ は電子を受け取りにくいからです。水のほうが先に還元されて H₂ が発生します。Na の単体を得るには、水のない融解した NaCl を電気分解します。'],
      ['燃料電池は、水素を燃やしているの?', '燃やしてはいません。水素の酸化(負極)と酸素の還元(正極)を別々の電極で起こし、その間の電子の移動を電流として取り出しています。全体の反応式は燃焼と同じですが、熱ではなく電気としてエネルギーを取り出せます。'],
      ['電気分解で、陽極に銅や銀を使うと結果が変わるのはなぜ?', '陽極では、いちばん電子を出しやすい(酸化されやすい)ものが反応します。銅や銀は、Cl⁻ や水よりも酸化されやすいので、電極そのものが Cu→Cu²⁺＋2e⁻ のように溶け出します。\n白金や炭素は非常に酸化されにくいので、陽極に使うと溶液中のイオンや水が反応します。だから、問題では「電極が何か」を最初に確認することが大切です。銅の電解精錬は、この性質を利用しています。']
    ],
    terms: [['負極', '電池で電子を出す(酸化が起こる)電極'], ['正極', '電池で電子を受け取る(還元が起こる)電極'], ['活物質', '電極で実際に反応して電子をやりとりする物質'], ['起電力', '電池の両極の間の電位差'], ['二次電池', '充電してくり返し使える電池'], ['陰極', '電気分解で電源の負極につなぐ電極(還元が起こる)'], ['陽極', '電気分解で電源の正極につなぐ電極(酸化が起こる)'], ['ファラデー定数', '電子 1 mol の電気量の大きさ。9.65×10⁴ C/mol']],
    miss: ['電池の負極と電気分解の陰極を同じと考える。どちらで「酸化」が起こるかを、電子の出入りで確かめます。', '水溶液の電気分解で、Na や K が陰極に析出すると書いてしまう。イオン化傾向の大きい金属イオンの代わりに水が還元されます。', '電子の物質量を求めずに、いきなり電気量から質量を出そうとする。まず電子の mol を出すのが基本です。', '鉛蓄電池の放電で、負極の鉛が溶けて軽くなると考える。実際は PbSO₄ が付着して重くなります。', '電流×時間の「時間」を分のまま使う。秒(s)に直してから計算します。'],
    sum: ['電池の負極は酸化、正極は還元。イオン化傾向の大きい金属が負極。', 'ダニエル電池は Zn→Zn²⁺、Cu²⁺→Cu。鉛蓄電池は放電で両極が PbSO₄ になる。', '燃料電池は H₂ と O₂ から水をつくり、電気を取り出す。', '電気分解の陰極は還元、陽極は酸化。反応しにくいイオンの代わりに水が反応する。', '電子の mol＝It÷(9.65×10⁴)。工業では NaOH・銅・アルミニウムの製造に使われる。'],
    next: '次は「無機物質(典型元素と遷移元素)」に進みましょう。ここで学んだ酸化還元や電気分解が、元素ごとの性質や製法の理解に役立ちます。'
  };

  // ===== 無機物質 =====
  L.c4_inorg = {
    goal: 'ハロゲン・酸素と硫黄・窒素などの非金属元素と、金属元素の代表的な性質・反応・工業的製法を説明でき、金属イオンの分離の手順を組み立てられるようになる。',
    intro: '水道水の消毒には塩素、自動車のバッテリーには硫酸、肥料にはアンモニアが使われています。無機物質は、身のまわりのあらゆる製品の原料です。覚えることが多い分野ですが、「酸化還元反応か」「酸と塩基の反応か」に分けて考えると、反応の多くは理論化学の知識で説明できます。',
    pre: '【周期表】の縦の列を【族】、横の行を【周期】といいます。同じ族の元素は価電子の数が同じなので、性質が似ています。\n1族・2族と 12〜18族の元素を【典型元素】、3〜11族の元素を【遷移元素】といいます。遷移元素はすべて金属元素です。\n反応の種類は、主に2つに分けられます。電子のやりとりがある【酸化還元反応】と、H⁺ のやりとりがある【酸と塩基の反応】です。「弱酸の塩＋強酸→強酸の塩＋弱酸」(例:FeS＋H₂SO₄→FeSO₄＋H₂S)のような反応も、酸と塩基の反応の一つです。\n気体の集め方は、水に溶けにくい気体は【水上置換】、水に溶けやすく空気より重い気体は【下方置換】、水に溶けやすく空気より軽い気体は【上方置換】です。',
    secs: [
      { h: '元素の分類と酸化物', t: '典型元素は、同じ族どうしで性質がよく似ています。例えば 1族(H を除く)はアルカリ金属、17族はハロゲン、18族は貴ガスとよばれ、族ごとにまとまった性質をもちます。\n遷移元素は、最外殻の電子の数が 1〜2 個のものが多いため、同じ周期のとなりどうしでも性質が似ています。色のついたイオンや化合物が多い、【錯イオン】をつくりやすい、触媒になるものが多い、といった特徴があります。\n酸化物は、性質で3つに分けられます。非金属元素の酸化物(CO₂・SO₂ など)は、水と反応して酸になったり塩基と反応したりする【酸性酸化物】。金属元素の酸化物(Na₂O・CaO など)は、酸と反応する【塩基性酸化物】。Al・Zn・Sn・Pb の酸化物は、酸とも強塩基とも反応する【両性酸化物】です。\nAl・Zn・Sn・Pb のように、酸とも強塩基とも反応する金属を【両性金属】といいます。後で学ぶ金属イオンの分離で重要になります。',
        key: '非金属の酸化物は酸性酸化物、金属の酸化物は塩基性酸化物。Al・Zn・Sn・Pb は両性。' },
      { h: 'ハロゲン(17族)', t: 'ハロゲンの単体は二原子分子で、原子番号が大きいほど分子間力が大きくなり、融点・沸点が高くなります。F₂ は淡黄色の気体、Cl₂ は黄緑色の気体、Br₂ は赤褐色の液体、I₂ は黒紫色の固体です。\nハロゲン原子は電子を1個受け取って1価の陰イオンになりやすいので、単体は酸化力をもちます。酸化力の強さは F₂＞Cl₂＞Br₂＞I₂ です。そのため、2KBr＋Cl₂→2KCl＋Br₂ は起こりますが、逆の反応は起こりません。\n塩素の実験室での製法は、酸化マンガン(Ⅳ)に濃塩酸を加えて加熱する方法です:MnO₂＋4HCl→MnCl₂＋Cl₂＋2H₂O。塩素は水に少し溶け、Cl₂＋H₂O ⇄ HCl＋HClO となります。次亜塩素酸 HClO の強い酸化力が、殺菌・漂白に使われます。\nハロゲン化水素のうち、HCl・HBr・HI の水溶液は強酸ですが、フッ化水素酸(HF の水溶液)は弱酸です。HF はガラスの主成分 SiO₂ を溶かすので、ポリエチレンの容器に保存します(SiO₂＋6HF→H₂SiF₆＋2H₂O)。\nハロゲン化銀のうち AgF は水に溶けますが、AgCl(白色)・AgBr(淡黄色)・AgI(黄色)は水に溶けにくい沈殿です。',
        key: '酸化力は F₂＞Cl₂＞Br₂＞I₂。HF だけは弱酸でガラスを溶かす。AgCl 白・AgBr 淡黄・AgI 黄。',
        ex: [{ q: '酸化マンガン(Ⅳ) MnO₂ 8.7 g に十分な量の濃塩酸を加えて加熱した。発生する塩素は標準状態で何 L?(O＝16、Mn＝55、気体 1 mol は標準状態で 22.4 L)', hint: 'MnO₂ 1 mol から Cl₂ が何 mol できるかを、反応式から読みます。', steps: ['MnO₂ の式量は 55＋16×2＝87。8.7 g は 8.7÷87＝0.10 mol。', '反応式 MnO₂＋4HCl→MnCl₂＋Cl₂＋2H₂O より、MnO₂ 1 mol から Cl₂ 1 mol。', 'Cl₂ は 0.10 mol なので、22.4×0.10＝2.24 L。'], a: '2.24 L', check: '濃塩酸は「十分な量」なので、MnO₂ のほうで量が決まることを確かめます。' }] },
      { h: '酸素と硫黄(16族)', t: '酸素には、酸素 O₂ とオゾン O₃ という【同素体】(同じ元素からなる性質のちがう単体)があります。オゾンは淡青色・特異臭の気体で、強い酸化力をもちます。\n硫黄には、斜方硫黄・単斜硫黄・ゴム状硫黄の同素体があります。硫化水素 H₂S は無色・腐卵臭の有毒な気体で、水に少し溶けて弱酸性を示し、強い還元剤です。硫化鉄(Ⅱ)に希硫酸を加えると発生します(FeS＋H₂SO₄→FeSO₄＋H₂S)。\n二酸化硫黄 SO₂ は無色・刺激臭の気体で、ふつうは還元剤としてはたらきます。ただし、より強い還元剤の H₂S に対しては酸化剤としてはたらきます(SO₂＋2H₂S→3S＋2H₂O)。\n硫酸は【接触法】でつくります。硫黄を燃やして SO₂ にし、酸化バナジウム(Ⅴ) V₂O₅ を触媒として SO₃ にします(2SO₂＋O₂→2SO₃)。SO₃ を濃硫酸に吸収させて発煙硫酸とし、これを希硫酸でうすめて濃硫酸にします。\n濃硫酸は、不揮発性(沸点が高い)、吸湿性(乾燥剤になる)、脱水作用(有機物から H と O を水として奪う)、加熱すると酸化作用(Cu＋2H₂SO₄→CuSO₄＋SO₂＋2H₂O)を示します。希硫酸は強い酸です。濃硫酸をうすめるときは、多量の熱が出るので、水に濃硫酸を少しずつ加えます。',
        key: '硫酸は接触法(V₂O₅ 触媒)。濃硫酸は不揮発性・吸湿性・脱水作用・熱濃硫酸の酸化作用。',
        ex: [{ q: '接触法で、硫黄 3.2 kg がすべて硫酸 H₂SO₄ になったとすると、何 kg の H₂SO₄ が得られる?(H＝1.0、O＝16、S＝32)', hint: '途中の反応をすべて書かなくても、S 原子の数は保存されます。', steps: ['S→SO₂→SO₃→H₂SO₄ と変化し、S 原子 1 個から H₂SO₄ 1 分子ができる。', 'S 3.2 kg は 3200÷32＝100 mol。', 'H₂SO₄ も 100 mol で、モル質量は 98 g/mol → 98×100＝9800 g＝9.8 kg。'], a: '9.8 kg', check: '元素(S)の数に注目すると、途中の反応式の係数をそろえなくても計算できます。' }] },
      { h: '窒素とリン(15族)', t: '窒素 N₂ は空気の体積の約 78% を占める、反応しにくい気体です。\nアンモニア NH₃ は無色・刺激臭の気体で、水によく溶けて弱塩基性を示します。空気より軽いので上方置換で集めます。実験室では、塩化アンモニウムと水酸化カルシウムを混ぜて加熱してつくります(2NH₄Cl＋Ca(OH)₂→CaCl₂＋2H₂O＋2NH₃)。工業的には、Fe₃O₄ を主成分とする触媒を使い、N₂＋3H₂ ⇄ 2NH₃ で合成します(【ハーバー・ボッシュ法】)。\n一酸化窒素 NO は無色で水に溶けにくく、空気にふれるとすぐ酸化されて赤褐色の二酸化窒素 NO₂ になります(2NO＋O₂→2NO₂)。銅に希硝酸を加えると NO が、濃硝酸を加えると NO₂ が発生します。3Cu＋8HNO₃→3Cu(NO₃)₂＋2NO＋4H₂O、Cu＋4HNO₃→Cu(NO₃)₂＋2NO₂＋2H₂O。\n硝酸は【オストワルト法】でつくります。①白金触媒でアンモニアを酸化:4NH₃＋5O₂→4NO＋6H₂O。②2NO＋O₂→2NO₂。③3NO₂＋H₂O→2HNO₃＋NO。全体をまとめると NH₃＋2O₂→HNO₃＋H₂O です。硝酸は強い酸で酸化力が強く、光で分解するので褐色びんに保存します。Fe・Ni・Al は濃硝酸には表面に酸化物の膜ができて溶けません(【不動態】)。\nリンの同素体には、空気中で自然発火するため水中に保存する黄リン(猛毒)と、マッチ箱の側薬に使われる赤リンがあります。リンを燃やすとできる十酸化四リン P₄O₁₀ は、強い吸湿性があり乾燥剤に使われます。',
        key: 'NH₃ はハーバー・ボッシュ法(Fe₃O₄)、硝酸はオストワルト法(Pt)。全体 NH₃＋2O₂→HNO₃＋H₂O。',
        ex: [{ q: 'オストワルト法で、アンモニア 1.7 kg がすべて硝酸になったとすると、何 kg の HNO₃ が得られる?(H＝1.0、N＝14、O＝16)', hint: '全体の反応式 NH₃＋2O₂→HNO₃＋H₂O を使います。', steps: ['NH₃ のモル質量は 17 g/mol。1.7 kg は 1700÷17＝100 mol。', '全体の式より、NH₃ 1 mol から HNO₃ 1 mol。', 'HNO₃ のモル質量は 1.0＋14＋16×3＝63 g/mol → 63×100＝6300 g＝6.3 kg。'], a: '6.3 kg', check: '③で生じた NO は①②にもどして再利用されるので、全体では N 原子 1 個が HNO₃ 1 分子になる、と確かめられます。' }] },
      { h: '金属元素の性質', t: '【アルカリ金属】(Li・Na・K など)は、1価の陽イオンになりやすく、常温の水と激しく反応して水素を発生します(2Na＋2H₂O→2NaOH＋H₂)。空気中の酸素や水と反応しやすいので、石油(灯油)の中に保存します。\n【2族元素】のうち Ca・Sr・Ba は常温の水と反応します。カルシウムの化合物には、酸化カルシウム CaO(生石灰)、水酸化カルシウム Ca(OH)₂(消石灰)、炭酸カルシウム CaCO₃(石灰石・大理石の主成分)などがあります。\n【炎色反応】:Li 赤、Na 黄、K 赤紫、Ca 橙赤、Sr 紅、Ba 黄緑、Cu 青緑。元素の検出に使います。\nアルミニウムは両性金属で、塩酸にも水酸化ナトリウム水溶液にも溶けて水素を発生します(2Al＋2NaOH＋6H₂O→2Na[Al(OH)₄]＋3H₂)。\n遷移元素のイオンには色のついたものが多く、Fe²⁺ は淡緑色、Fe³⁺ は黄褐色、Cu²⁺ は青色です。金属イオンに分子や陰イオンが配位結合したものを錯イオンといい、[Cu(NH₃)₄]²⁺(深青色)、[Ag(NH₃)₂]⁺(無色)、[Zn(NH₃)₄]²⁺(無色)などがあります。',
        key: '炎色反応:Li 赤・Na 黄・K 赤紫・Ca 橙赤・Sr 紅・Ba 黄緑・Cu 青緑。' },
      { h: '金属イオンの分離', t: '複数の金属イオンを含む水溶液から、試薬を順に加えて1種類ずつ沈殿させて分けることを、金属イオンの【系統分離】といいます。大切なのは、加える試薬の順番です。\n①希塩酸を加える:Ag⁺ が AgCl(白)、Pb²⁺ が PbCl₂(白)として沈殿します。\n②酸性のまま硫化水素を通じる:Cu²⁺ が CuS(黒)として沈殿します。Zn²⁺・Fe²⁺ などは、酸性では硫化物が沈殿しません。\n③煮沸して H₂S を追い出し、希硝酸で Fe²⁺ を Fe³⁺ に酸化してから、アンモニア水を過剰に加える:Fe(OH)₃(赤褐色)、Al(OH)₃(白)が沈殿します。Zn²⁺ は [Zn(NH₃)₄]²⁺ となって溶けたまま残ります。\n④塩基性のまま硫化水素を通じる:ZnS(白)が沈殿します。⑤炭酸アンモニウムを加える:Ca²⁺・Ba²⁺ が炭酸塩(白)として沈殿します。⑥最後に残った Na⁺・K⁺ は炎色反応で確かめます。\n覚えておくと便利な性質:水酸化ナトリウム水溶液を過剰に加えると溶ける水酸化物は、両性の Al・Zn・Sn・Pb のもの。アンモニア水を過剰に加えると錯イオンをつくって溶けるのは、Ag⁺・Cu²⁺・Zn²⁺ などです。',
        key: '分離の順:希塩酸(Ag⁺・Pb²⁺)→酸性で H₂S(Cu²⁺)→NH₃ 水(Fe³⁺・Al³⁺)→塩基性で H₂S(Zn²⁺)→(NH₄)₂CO₃(Ca²⁺・Ba²⁺)。',
        ex: [{ q: 'Ag⁺・Cu²⁺・Fe³⁺・Zn²⁺ を含む水溶液から、4種類のイオンを1つずつ沈殿として分ける手順を考えよう。', hint: '「その試薬で1種類だけが沈殿する」順番を考えます。', steps: ['希塩酸を加えると、Ag⁺ だけが AgCl(白)として沈殿する。ろ過して分ける。', 'ろ液は酸性なので、硫化水素を通じると Cu²⁺ だけが CuS(黒)として沈殿する。ろ過する。', 'ろ液を煮沸して H₂S を追い出し、アンモニア水を過剰に加えると、Fe(OH)₃(赤褐色)が沈殿する。Zn²⁺ は [Zn(NH₃)₄]²⁺ として溶けたまま。', 'ろ液(塩基性)に硫化水素を通じると、ZnS(白)が沈殿する。'], a: '希塩酸→AgCl、H₂S(酸性)→CuS、NH₃ 水(過剰)→Fe(OH)₃、H₂S(塩基性)→ZnS', check: '最初に NaOH 水溶液を加えると、多くの水酸化物が一度に沈殿してしまい、うまく分けられません。1種類ずつ沈殿する順になっているかを確かめます。' }] },
      { h: 'もっと深く:気体の発生反応は「型」で理解できる', t: '無機化学に出てくる気体の発生反応は数が多く見えますが、多くは数種類の【反応の型】に分けられます。型が分かれば、反応式を丸暗記しなくても自分で組み立てられます。\n①【弱酸の遊離】:弱酸の塩に強酸を加えると、強酸の塩ができて弱酸が追い出されます。CaCO₃＋2HCl→CaCl₂＋H₂O＋CO₂(炭酸は弱酸なので CO₂ と H₂O になって出ていく)、FeS＋H₂SO₄→FeSO₄＋H₂S などがこの型です。\n②【弱塩基の遊離】:弱塩基の塩に強塩基を加えると、弱塩基が追い出されます。2NH₄Cl＋Ca(OH)₂→CaCl₂＋2H₂O＋2NH₃ がこの型で、アンモニアの実験室での製法です。\n③【揮発性の酸の遊離】:不揮発性の濃硫酸と、揮発性の酸の塩を加熱すると、揮発性の酸が気体として出ていきます。NaCl＋H₂SO₄→NaHSO₄＋HCl が代表です。塩化水素は強酸ですが、気体として系の外に出ていくので反応が進みます。\n④【酸化還元反応】:金属と酸(Zn＋H₂SO₄→ZnSO₄＋H₂)、銅と硝酸(希硝酸で NO、濃硝酸で NO₂)、銅と熱濃硫酸(SO₂)、酸化マンガン(Ⅳ)と濃塩酸(Cl₂)などです。電子のやりとりを半反応式で書けば係数が決まります。\n⑤【熱分解】:2KClO₃→2KCl＋3O₂(MnO₂ が触媒)などです。過酸化水素水に MnO₂ を加える 2H₂O₂→2H₂O＋O₂ も、触媒による分解です。\nこのように、「強いものが弱いものを追い出す」「出ていくものがあれば進む」「電子のやりとり」という3つの見方で、ほとんどの反応が説明できます。',
        key: '弱酸・弱塩基の遊離、揮発性の酸の遊離、酸化還元、熱分解。型で考えれば反応式は組み立てられる。' },
      { h: '入試ではこう出る:気体の製法・捕集法・乾燥剤の組み合わせ', t: '気体の単元では、「製法」「捕集法」「乾燥剤」「検出法」をセットで問う問題が定番です。装置図を見せて、まちがいを指摘させる問題もよく出ます。\n【捕集法】は、水への溶けやすさと空気(平均分子量 約 29)との重さで決まります。水に溶けにくい気体(H₂、O₂、N₂、NO、CO、CH₄ など)は【水上置換】。水に溶けやすく空気より軽い NH₃ は【上方置換】。水に溶けやすく空気より重い気体(Cl₂、HCl、CO₂、H₂S、SO₂、NO₂ など)は【下方置換】です。CO₂ は水に少し溶けるだけなので、水上置換で集めることもあります。\n【乾燥剤】は「酸と塩基は反応する」が基本です。濃硫酸や十酸化四リン P₄O₁₀ は酸性の乾燥剤なので、塩基性の NH₃ には使えません。ソーダ石灰(CaO と NaOH)は塩基性なので、酸性の気体(CO₂、Cl₂、HCl、SO₂ など)には使えません。\n例外として覚えるのは2つです。塩化カルシウムは中性ですが、NH₃ と結びついてしまうので NH₃ には使えません。濃硫酸は酸化力があるので、還元性のある H₂S の乾燥には使えません。\n塩素の製法では、発生した気体に含まれる HCl と水蒸気を取り除くため、まず【水】、次に【濃硫酸】の順に通します。順番を逆にすると、せっかく乾燥させた気体に水蒸気が入ってしまいます。',
        key: '捕集:水に溶けにくい→水上、溶けて軽い→上方、溶けて重い→下方。乾燥剤:酸性の気体に塩基性の乾燥剤は使えない(逆も)。',
        ex: [{ q: '酸化マンガン(Ⅳ)に濃塩酸を加えて加熱し、発生した気体を洗気びん X、Y の順に通してから集めた。X、Y に入れる物質と、その順番の理由、塩素の捕集法を答えよ。', hint: '発生した塩素には、塩化水素と水蒸気が混ざっています。', steps: ['発生する気体には、濃塩酸から出た HCl と水蒸気が含まれる。', 'X には【水】を入れる。HCl は水によく溶けるので取り除かれる(塩素も少し溶けるが、HCl のほうがはるかに溶けやすい)。', 'Y には【濃硫酸】を入れて水蒸気を取り除く。', '先に濃硫酸を通すと、あとの水で再び水蒸気が入るので、水→濃硫酸の順にする。', '塩素は水に溶け、空気より重いので下方置換で集める。'], a: 'X:水(HCl を除く)、Y:濃硫酸(水蒸気を除く)。乾燥は最後に行うのでこの順。捕集は下方置換。', check: 'Cl₂ の分子量は 71 で、空気の平均分子量 約 29 より大きいので、下方置換が適しています。' },
          { q: '次の(1)〜(3)の気体を乾燥させるのに適した乾燥剤を、濃硫酸・塩化カルシウム・ソーダ石灰からすべて選べ。(1)アンモニア (2)二酸化炭素 (3)硫化水素', hint: '酸と塩基の関係と、2つの例外を思い出します。', steps: ['(1)NH₃ は塩基性。酸性の濃硫酸は不可、塩化カルシウムは NH₃ と結びつくので不可。ソーダ石灰だけが使える。', '(2)CO₂ は酸性。塩基性のソーダ石灰は不可。濃硫酸と塩化カルシウムは使える。', '(3)H₂S は酸性で還元性がある。ソーダ石灰は不可、濃硫酸は H₂S を酸化してしまうので不可。塩化カルシウムが使える。'], a: '(1)ソーダ石灰 (2)濃硫酸、塩化カルシウム (3)塩化カルシウム', check: 'どの気体にも使える乾燥剤はない、と気づくことが大切です。塩化カルシウムは中性なので使える範囲が広いですが、アンモニアだけは例外です。' }] }
    ],
    drill: [
      { lv: 1, q: '炎色反応で、次の元素は何色を示すか。(1)Ca (2)Ba (3)Li', a: '(1)橙赤色 (2)黄緑色 (3)赤色', exp: '炎色反応は、元素の種類ごとに決まった色の光が出る現象です。Na 黄、K 赤紫、Ca 橙赤、Cu 青緑、Li 赤、Sr 紅(深赤)、Ba 黄緑 をセットで覚えます。\nLi と Sr はどちらも赤系なので、「Li は赤、Sr は紅(深い赤)」と区別しておきましょう。' },
      { lv: 1, q: '次の気体を集めるのに適した捕集法を答えよ。(1)アンモニア (2)一酸化窒素 (3)二酸化窒素', a: '(1)上方置換 (2)水上置換 (3)下方置換', exp: '(1)NH₃ は水に非常によく溶け、分子量 17 で空気より軽いので上方置換です。\n(2)NO は水に溶けにくいので水上置換です。また、空気中の酸素とすぐ反応して NO₂ になるので、空気にふれさせない水上置換が適しています。\n(3)NO₂ は水に溶けて反応し、分子量 46 で空気より重いので下方置換です。' },
      { lv: 1, q: '亜鉛に希硫酸を加えると発生する気体は何か。化学反応式で答えよ。', a: '水素。Zn＋H₂SO₄→ZnSO₄＋H₂', exp: '亜鉛は水素よりイオン化傾向が大きいので、酸の H⁺ に電子をわたして水素を発生させます(酸化還元反応)。\nZn→Zn²⁺＋2e⁻、2H⁺＋2e⁻→H₂ をまとめると、Zn＋2H⁺→Zn²⁺＋H₂ です。' },
      { lv: 2, q: '炭酸カルシウム 5.0 g に十分な量の塩酸を加えた。発生する二酸化炭素は標準状態で何 L か。(CaCO₃＝100、気体 1 mol は標準状態で 22.4 L)', a: '約 1.1 L', exp: 'CaCO₃＋2HCl→CaCl₂＋H₂O＋CO₂ で、CaCO₃ 1 mol から CO₂ 1 mol が発生します(弱酸の遊離)。\nCaCO₃ は 5.0÷100＝0.050 mol なので、CO₂ も 0.050 mol、体積は 0.050×22.4＝1.12≒1.1 L です。' },
      { lv: 2, q: 'Al³⁺、Zn²⁺、Fe³⁺ をそれぞれ含む水溶液に、(1)水酸化ナトリウム水溶液を過剰に加える (2)アンモニア水を過剰に加える とき、沈殿が溶けるのはどのイオンの場合か。', a: '(1)Al³⁺ と Zn²⁺ (2)Zn²⁺', exp: 'どのイオンも、少量の塩基で水酸化物の沈殿(Al(OH)₃、Zn(OH)₂、Fe(OH)₃)をつくります。\n(1)Al と Zn は【両性元素】なので、水酸化物が過剰の NaOH に溶けて [Al(OH)₄]⁻、[Zn(OH)₄]²⁻ になります。\n(2)Zn²⁺ はアンモニアと錯イオン [Zn(NH₃)₄]²⁺ をつくるので、過剰のアンモニア水に溶けます。Al(OH)₃ は溶けません。Fe(OH)₃ はどちらにも溶けません。' },
      { lv: 2, q: 'アンモニアソーダ法(ソルベー法)で、塩化ナトリウム 117 kg がすべて炭酸ナトリウムになったとすると、何 kg の Na₂CO₃ が得られるか。(NaCl＝58.5、Na₂CO₃＝106)', a: '106 kg', exp: '全体の反応をまとめると 2NaCl＋CaCO₃→Na₂CO₃＋CaCl₂ で、NaCl 2 mol から Na₂CO₃ 1 mol ができます。途中の式を全部たどらなくても、Na 原子の数が保存されることから 2:1 と分かります。\nNaCl は 117÷58.5＝2.0 kmol なので、Na₂CO₃ は 1.0 kmol、106 kg です。' },
      { lv: 3, q: 'Fe₂O₃ を質量で 80% 含む鉄鉱石 1.0 t から、理論上何 kg の鉄が得られるか。(O＝16、Fe＝56)', a: '560 kg', exp: '鉄鉱石に含まれる Fe₂O₃ は 1000×0.80＝800 kg。Fe₂O₃ の式量は 2×56＋3×16＝160 なので、800÷160＝5.0 kmol。\nFe₂O₃ 1 mol に Fe は 2 mol 含まれるので、鉄は 10 kmol、10×56＝560 kg です。\n溶鉱炉では CO が還元剤となって Fe₂O₃＋3CO→2Fe＋3CO₂ と反応しますが、鉄原子の数は変わらないので、反応式を使わなくても求められます。' },
      { lv: 3, q: '次の酸化物を、酸性酸化物・塩基性酸化物・両性酸化物に分類せよ。また、SO₃ と Al₂O₃ がそれぞれ水酸化ナトリウム水溶液と反応するときの化学反応式を書け。CaO、SO₃、Al₂O₃、Na₂O、P₄O₁₀', a: '酸性:SO₃、P₄O₁₀ 塩基性:CaO、Na₂O 両性:Al₂O₃。SO₃＋2NaOH→Na₂SO₄＋H₂O、Al₂O₃＋2NaOH＋3H₂O→2Na[Al(OH)₄]', exp: '一般に、非金属元素の酸化物は酸性酸化物、金属元素(特に典型金属の陽性の強いもの)の酸化物は塩基性酸化物です。Al・Zn・Sn・Pb の酸化物は、酸とも強塩基とも反応する両性酸化物です。\nSO₃ は水と反応すると H₂SO₄ になる酸性酸化物なので、NaOH と中和して Na₂SO₄ と水ができます。\nAl₂O₃ は強塩基と反応して、テトラヒドロキシドアルミン酸イオン [Al(OH)₄]⁻ をつくります。採点では、両性酸化物の反応で水 H₂O が反応物に入ることを書けているかがポイントです。' }
    ],
    faq: [
      ['ハロゲンの酸化力が、F₂ から I₂ に向かって弱くなるのはなぜ?', '原子番号が大きくなるほど原子が大きくなり、原子核が外から来た電子を引きつける力が弱くなるからです。電子を受け取りにくくなるので、相手を酸化する力(酸化力)が弱くなります。'],
      ['硫化水素で沈殿させるとき、酸性か塩基性かで結果が変わるのはなぜ?', 'H₂S ⇄ 2H⁺＋S²⁻ の電離平衡が関係しています。酸性では H⁺ が多いので平衡が左に移動し、S²⁻ が非常に少なくなります。そのため、溶解度積のとても小さい CuS だけが沈殿します。塩基性では S²⁻ が増えるので、ZnS なども沈殿します。'],
      ['無機化学は暗記ばかりで覚えきれません。どうすればよい?', 'まず反応を「酸化還元」「酸と塩基」「沈殿・錯イオン」に分類しましょう。そのうえで、気体の製法・工業的製法・沈殿の色の3つの表をつくり、くり返し見直すと効率よく覚えられます。'],
      ['濃硫酸は乾燥剤なのに、硫化水素の乾燥に使えないのはなぜ?', '濃硫酸には、水を吸う性質(吸湿性)のほかに、相手を酸化する性質(酸化力)があるからです。硫化水素は還元性が強い(電子を出しやすい)ので、濃硫酸に酸化されて硫黄などに変わってしまいます。\n乾燥剤を選ぶときは、「酸・塩基の関係」に加えて「酸化還元が起こらないか」も考える必要があります。']
    ],
    terms: [['典型元素', '1族・2族と12〜18族の元素。同族で性質がよく似る'], ['遷移元素', '3〜11族の元素。すべて金属で、有色のイオンや錯イオンが多い'], ['両性金属', '酸とも強塩基とも反応する金属(Al・Zn・Sn・Pb)'], ['同素体', '同じ元素からなる、性質の異なる単体(O₂ と O₃ など)'], ['接触法', 'V₂O₅ を触媒として SO₂ を SO₃ にし、硫酸をつくる方法'], ['オストワルト法', '白金を触媒としてアンモニアを酸化し、硝酸をつくる方法'], ['不動態', '表面に酸化物の膜ができて、それ以上反応が進まなくなった状態'], ['錯イオン', '金属イオンに分子や陰イオンが配位結合してできたイオン']],
    miss: ['ハロゲン化水素の酸の強さで、HF も強酸だと思いこむ。HF だけは弱酸です。', '濃硫酸と希硫酸の性質を混同する。脱水作用や吸湿性は濃硫酸、強い酸性は希硫酸の性質です。', '銅と硝酸の反応で、希硝酸と濃硝酸で出る気体を逆にする。「希は NO、濃は NO₂(O が多い)」と覚えます。', '金属イオンの分離で、試薬を加える順番を入れかえてしまう。各段階で「沈殿するのは1種類だけか」を確かめます。', '炎色反応の色を混同する(Ca と Sr、Ba と Cu など)。語呂合わせや表で、セットで覚えます。'],
    sum: ['酸化物は酸性・塩基性・両性に分かれる。Al・Zn・Sn・Pb は両性。', 'ハロゲンの酸化力は F₂＞Cl₂＞Br₂＞I₂。HF は弱酸でガラスを溶かす。', '硫酸は接触法、硝酸はオストワルト法、アンモニアはハーバー・ボッシュ法でつくる。', '濃硫酸は不揮発性・吸湿性・脱水作用・酸化作用をもつ。', '金属イオンは、試薬を順に加えて1種類ずつ沈殿させて分離する。'],
    next: '次は「有機化合物」に進みましょう。炭素を中心とした化合物の構造と、官能基ごとの反応を学びます。'
  };

  // ===== 有機化合物 =====
  L.c4_org = {
    goal: '元素分析から分子式を決め、異性体を書き分け、炭化水素・酸素を含む化合物・芳香族化合物の代表的な反応と、混合物の分離方法を説明できるようになる。',
    intro: '砂糖・アルコール・プラスチック・医薬品など、私たちの身のまわりは炭素を含む化合物であふれています。炭素の化合物は数千万種類以上もありますが、「どんな官能基(性質を決める原子のまとまり)をもつか」で整理すると、性質や反応をまとめて理解できます。',
    pre: '炭素原子は価電子を4個もち、ほかの原子と【共有結合】を4本つくります。水素は1本、酸素は2本、窒素は3本です。この「結合の手の数」が、構造式を書くときの基本ルールです。\n分子の中の原子のつながり方を線で表した式を【構造式】といいます。CH₃CH₂OH のように、官能基がわかるように略した式を【示性式】といいます。\n分子式は分子中の原子の数をそのまま表し、組成式は原子の数を最も簡単な整数比で表します。例えば酢酸は、分子式 C₂H₄O₂、組成式 CH₂O です。\n有機化合物では、酸素を受け取る、または水素を失う変化を【酸化】、その逆を【還元】と考えるとわかりやすいです。エタノール C₂H₆O がアセトアルデヒド C₂H₄O になるのは、水素を失っているので酸化です。',
    secs: [
      { h: '有機化合物の特徴と官能基', t: '炭素を含む化合物を【有機化合物】といいます。ただし、CO・CO₂・炭酸塩(CaCO₃ など)などは無機物質として扱います。有機化合物は、構成元素は C・H・O・N などと少ないのに種類がとても多く、一般に融点が低く、燃えやすいという特徴があります。\n炭素原子が鎖のようにつながったものを【鎖式化合物】、環になったものを【環式化合物】といいます。炭素どうしが単結合だけで結ばれたものを【飽和】、二重結合や三重結合を含むものを【不飽和】といいます。\n化合物の性質を決める原子のまとまりを【官能基】といいます。主なものは、ヒドロキシ基 −OH(アルコール・フェノール類)、ホルミル基 −CHO(アルデヒド)、カルボニル基 >C=O(ケトン)、カルボキシ基 −COOH(カルボン酸)、ニトロ基 −NO₂、アミノ基 −NH₂(アミン)、スルホ基 −SO₃H(スルホン酸)です。\nエステル結合 −COO− やエーテル結合 −O− も、性質を決める大切な結合です。同じ官能基をもつ化合物は、炭素の数がちがっても似た性質を示します。',
        key: '官能基で性質が決まる。−OH、−CHO、>C=O、−COOH、−NO₂、−NH₂、−SO₃H を構造とセットで覚える。' },
      { h: '元素分析と分子式の決定', t: '有機化合物の分子式は、【元素分析】で決めます。試料を完全燃焼させ、生じた H₂O を塩化カルシウム管に、CO₂ をソーダ石灰管に吸収させて、それぞれの質量を測ります。\n管をつなぐ順番は「塩化カルシウム管→ソーダ石灰管」です。ソーダ石灰は CO₂ だけでなく水も吸収してしまうので、先に水を取り除く必要があるからです。\n計算の手順:C の質量＝CO₂ の質量×12/44、H の質量＝H₂O の質量×2/18、O の質量＝試料の質量−(C＋H)。各質量を原子量で割って物質量の比を出し、最も簡単な整数比にしたものが組成式です。\n組成式に分子量をあてはめて、分子式を求めます。分子量は、気体の状態方程式や凝固点降下などから求めます。',
        key: 'C＝CO₂×12/44、H＝H₂O×2/18、O＝全体−C−H。物質量比→組成式→分子量で分子式。',
        ex: [{ q: 'C・H・O からなる化合物 4.6 mg を完全燃焼させると、CO₂ 8.8 mg と H₂O 5.4 mg が生じた。分子量が 46 のとき、分子式を求めよう。(H＝1.0、C＝12、O＝16)', hint: 'まず C と H の質量を求め、残りを O とします。', steps: ['C の質量＝8.8×12/44＝2.4 mg。', 'H の質量＝5.4×2/18＝0.60 mg。O の質量＝4.6−2.4−0.60＝1.6 mg。', '物質量の比 C:H:O＝2.4/12:0.60/1.0:1.6/16＝0.20:0.60:0.10＝2:6:1。組成式は C₂H₆O。', 'C₂H₆O の式量は 46 で分子量と等しいので、分子式も C₂H₆O。'], a: 'C₂H₆O', check: 'C₂H₆O にはエタノールとジメチルエーテルがあり、どちらかは性質(Na と反応するかなど)で決めます。分子式だけでは構造は決まらないことに注意します。' }] },
      { h: '異性体', t: '分子式が同じでも構造がちがう化合物を【異性体】といいます。\n原子のつながり方(骨格・官能基の種類や位置)がちがうものを【構造異性体】といいます。例:C₄H₁₀ にはブタン CH₃CH₂CH₂CH₃ と、2-メチルプロパン CH₃CH(CH₃)CH₃ の2つがあります。C₂H₆O にはエタノール CH₃CH₂OH とジメチルエーテル CH₃OCH₃ があります。\nつながり方は同じでも、空間的な配置がちがうものを【立体異性体】といいます。二重結合は回転できないので、2-ブテン CH₃CH=CHCH₃ には、同じ側に CH₃ があるシス形と、反対側にあるトランス形があります。これを【シス−トランス異性体】(幾何異性体)といいます。\n4つの異なる原子や原子団が結合した炭素原子を【不斉炭素原子】といいます。不斉炭素原子をもつ化合物には、右手と左手のように、鏡に映すと重なり合わない2つの異性体があり、【鏡像異性体】(光学異性体)といいます。乳酸 CH₃CH(OH)COOH がその例です。',
        key: '構造異性体=つながり方がちがう。シス−トランス異性体=二重結合が回転できない。鏡像異性体=不斉炭素原子をもつ。',
        ex: [{ q: '分子式 C₅H₁₂ で表されるアルカンの構造異性体をすべて答えよう。', hint: 'いちばん長い炭素の鎖が 5 個、4 個、3 個の場合に分けて考えます。', steps: ['炭素 5 個が一列:CH₃CH₂CH₂CH₂CH₃(ペンタン)。', '最も長い鎖が 4 個で、枝が 1 個:CH₃CH(CH₃)CH₂CH₃(2-メチルブタン)。枝を 3 番目につけても、反対から数えれば同じ分子。', '最も長い鎖が 3 個で、枝が 2 個:C(CH₃)₄(2,2-ジメチルプロパン)。', '以上の 3 種類。'], a: 'ペンタン、2-メチルブタン、2,2-ジメチルプロパンの 3 種類', check: '同じ分子を2回数えていないかを、「最も長い鎖の長さ」と「枝の位置」で確かめます。' }] },
      { h: '脂肪族炭化水素', t: '炭素と水素だけからなる化合物を【炭化水素】といいます。\n【アルカン】(一般式 CₙH₂ₙ₊₂)は単結合だけからなる鎖式の飽和炭化水素で、メタン CH₄・エタン C₂H₆・プロパン C₃H₈ などがあります。反応しにくいですが、光を当てながら塩素と混ぜると、H が Cl に置きかわる【置換反応】が起こります(CH₄＋Cl₂→CH₃Cl＋HCl)。\n【アルケン】(CₙH₂ₙ)は二重結合を1つもちます。エチレン CH₂=CH₂ が代表例で、二重結合のうち1本が切れて、ほかの原子が結びつく【付加反応】を起こしやすいです。例えば、赤褐色の臭素水にアルケンを通すと、臭素が付加して色が消えます(CH₂=CH₂＋Br₂→CH₂BrCH₂Br)。これは不飽和結合の検出に使われます。\n【アルキン】(CₙH₂ₙ₋₂)は三重結合を1つもちます。アセチレン C₂H₂ は、炭化カルシウムに水を加えるとできます(CaC₂＋2H₂O→C₂H₂＋Ca(OH)₂)。アセチレンに水が付加すると、不安定なビニルアルコールを経てアセトアルデヒドになります。',
        key: 'アルカンは置換反応、アルケン・アルキンは付加反応。臭素水の脱色で不飽和結合を検出する。',
        ex: [{ q: 'あるアルケン 2.8 g に臭素を付加させたところ、臭素 Br₂ 16 g がちょうど反応した。このアルケンの分子式を求めよう。(H＝1.0、C＝12、Br＝80)', hint: 'アルケンは二重結合を1つもつので、1 mol に Br₂ 1 mol が付加します。', steps: ['Br₂ の分子量は 160。16 g は 16÷160＝0.10 mol。', 'アルケン 1 mol に Br₂ 1 mol が付加するので、アルケンも 0.10 mol。', 'アルケンの分子量は 2.8÷0.10＝28。', 'CₙH₂ₙ の分子量は 14n なので、14n＝28 より n＝2。分子式は C₂H₄。'], a: 'C₂H₄(エチレン)', check: 'C₂H₄ の分子量は 12×2＋1.0×4＝28 で、求めた値と一致します。' }] },
      { h: '酸素を含む脂肪族化合物', t: '【アルコール】は −OH をもち、ナトリウムと反応して水素を発生します(2C₂H₅OH＋2Na→2C₂H₅ONa＋H₂)。−OH が結合した炭素に、炭素が何個ついているかで第一級・第二級・第三級に分けます。第一級アルコールは酸化されるとアルデヒドを経てカルボン酸に、第二級アルコールはケトンになり、第三級アルコールは酸化されにくいです。\nエタノールに濃硫酸を加えて加熱すると、約 130℃では分子間で脱水してジエチルエーテルが、約 160〜170℃では分子内で脱水してエチレンが生じます。\n【アルデヒド】(−CHO)は酸化されやすく、還元性を示します。アンモニア性硝酸銀水溶液から銀を析出させる【銀鏡反応】や、フェーリング液を還元して赤色の Cu₂O を沈殿させる反応が、ホルミル基の検出に使われます。CH₃CO− や CH₃CH(OH)− の構造をもつ物質は、ヨウ素と水酸化ナトリウム水溶液を加えて温めると黄色のヨードホルム CHI₃ を生じます(【ヨードホルム反応】)。\n【カルボン酸】(−COOH)は弱酸ですが、炭酸より強い酸です。カルボン酸とアルコールに濃硫酸を少量加えて加熱すると、水が取れて【エステル】ができます(CH₃COOH＋C₂H₅OH ⇄ CH₃COOC₂H₅＋H₂O)。この反応をエステル化といいます。\nエステルに水酸化ナトリウム水溶液を加えて加熱すると、カルボン酸の塩とアルコールに分解されます。これを【けん化】といいます。油脂(高級脂肪酸とグリセリンのエステル)をけん化すると、セッケンができます。',
        key: '第一級アルコール→アルデヒド→カルボン酸。アルデヒドは銀鏡反応・フェーリング液の還元。CH₃CO− はヨードホルム反応。',
        ex: [{ q: '酢酸エチル CH₃COOC₂H₅ 8.8 g を完全にけん化するのに必要な水酸化ナトリウムは何 g?(H＝1.0、C＝12、O＝16、Na＝23)', hint: 'CH₃COOC₂H₅＋NaOH→CH₃COONa＋C₂H₅OH です。', steps: ['酢酸エチル C₄H₈O₂ の分子量は 12×4＋1.0×8＋16×2＝88。8.8 g は 0.10 mol。', '反応式より、エステル 1 mol に NaOH 1 mol が反応する。', 'NaOH は 0.10 mol で、モル質量 40 g/mol → 40×0.10＝4.0 g。'], a: '4.0 g', check: 'エステル結合が1つなら NaOH は 1 mol、油脂のようにエステル結合が3つなら 3 mol 必要です。結合の数を確かめます。' }] },
      { h: '芳香族化合物', t: 'ベンゼン C₆H₆ のように、ベンゼン環をもつ化合物を【芳香族化合物】といいます。ベンゼン環の炭素どうしの結合は、単結合と二重結合の中間の性質をもち、とても安定です。そのため、付加反応より置換反応が起こりやすいです。\nベンゼンの主な置換反応:鉄(または塩化鉄(Ⅲ))を触媒に塩素と反応させるとクロロベンゼン(ハロゲン化)、濃硝酸と濃硫酸の混合物と反応させるとニトロベンゼン(ニトロ化)、濃硫酸と加熱するとベンゼンスルホン酸(スルホン化)ができます。\n【フェノール】C₆H₅OH は、−OH がベンゼン環に直接ついた化合物で、弱酸性を示します(炭酸より弱い)。塩化鉄(Ⅲ)水溶液で紫色になります。工業的には、ベンゼンとプロペンからクメンをつくり、酸化・分解してフェノールとアセトンを得ます(【クメン法】)。\nトルエンを酸化すると安息香酸 C₆H₅COOH ができます。サリチル酸に無水酢酸を反応させるとアセチルサリチル酸(解熱鎮痛剤)、メタノールと濃硫酸で反応させるとサリチル酸メチル(消炎鎮痛剤)ができます。\n【アニリン】C₆H₅NH₂ は弱塩基で、ニトロベンゼンをスズと塩酸で還元し、水酸化ナトリウム水溶液を加えて得ます。さらし粉水溶液で赤紫色になります。アニリンを冷やしながら亜硝酸ナトリウムと塩酸で反応させると塩化ベンゼンジアゾニウムができ(ジアゾ化)、これをナトリウムフェノキシドと反応させると橙赤色の p-ヒドロキシアゾベンゼンができます(ジアゾカップリング)。',
        key: 'ベンゼンは置換反応を起こしやすい。フェノールは FeCl₃ で紫色、アニリンはさらし粉で赤紫色。' },
      { h: '芳香族化合物の分離', t: '芳香族化合物の混合物は、酸・塩基の性質のちがいを利用して分離します。有機化合物は水に溶けにくくジエチルエーテルに溶けやすいものが多いですが、塩になると水に溶けるようになります。\n酸の強さは、スルホン酸＞カルボン酸＞炭酸(CO₂＋H₂O)＞フェノール です。弱い酸の塩に強い酸を加えると、弱い酸が追い出されます。\n炭酸水素ナトリウム NaHCO₃ 水溶液と反応するのは、炭酸より強い酸(カルボン酸など)だけです。水酸化ナトリウム水溶液とは、カルボン酸もフェノールも反応して塩になります。塩酸と反応して塩になるのは、アニリンのような塩基です。\nトルエンやニトロベンゼンのように酸性も塩基性も示さない(中性の)物質は、どの水溶液とも反応せず、エーテル層に残ります。',
        key: '酸の強さ:スルホン酸＞カルボン酸＞炭酸＞フェノール。NaHCO₃ はカルボン酸だけ、NaOH はフェノールも、塩酸はアニリンを水層へ。',
        ex: [{ q: 'アニリン・フェノール・安息香酸・トルエンを含むジエチルエーテル溶液から、4つを分ける手順を考えよう。', hint: '「どの水溶液を加えると、どれが塩になって水層に移るか」を順に考えます。', steps: ['塩酸を加えて振ると、塩基のアニリンだけがアニリン塩酸塩になって水層に移る。', '残ったエーテル層に NaHCO₃ 水溶液を加えると、炭酸より強い安息香酸だけが安息香酸ナトリウムとして水層に移る。', 'さらに NaOH 水溶液を加えると、フェノールがナトリウムフェノキシドとして水層に移る。', 'エーテル層には、中性のトルエンが残る。'], a: '塩酸→アニリン、NaHCO₃ 水溶液→安息香酸、NaOH 水溶液→フェノール、エーテル層にトルエン', check: '先に NaOH 水溶液を加えると、安息香酸とフェノールが同時に水層に移ってしまいます。NaHCO₃ を先にする理由を確かめます。' }] },
      { h: 'もっと深く:反応の「型」と酸化数で有機化学をつなぐ', t: '有機化学の反応はたくさんありますが、多くは【置換・付加・脱離・縮合】の4つの型と、【酸化・還元】に分けられます。型を意識すると、知らない物質の反応も予想できます。\n二重結合や三重結合をもつアルケン・アルキンは、π結合が切れやすいので【付加反応】を起こします。一方、ベンゼン環は、6個の炭素の間に電子が均等に広がった特別に安定な構造なので、付加よりも、環の形を保ったまま H がほかの原子と入れかわる【置換反応】(ニトロ化・スルホン化・ハロゲン化)が起こりやすくなります。\nアルコールの酸化は、炭素の酸化数で整理できます。第一級アルコール R−CH₂OH は酸化されてアルデヒド R−CHO、さらにカルボン酸 R−COOH になります。このとき、−OH のついた炭素の酸化数は −1→＋1→＋3 と上がっていきます。第二級アルコールはケトンになり、第三級アルコールは −OH のついた炭素に H がないので酸化されにくいのです。\nアルデヒドが還元性(銀鏡反応・フェーリング液の還元)を示すのは、まだ酸化される余地がある(カルボン酸になれる)からです。ギ酸 HCOOH はカルボン酸ですが、ホルミル基(アルデヒド基)の構造ももつので、還元性を示します。\n脱水も、条件で型が変わります。エタノールを濃硫酸と約 130℃で加熱すると2分子から水がとれる縮合(ジエチルエーテル)、約 170℃では1分子から水がとれる脱離(エチレン)になります。温度で生成物が変わる例として、入試でよく問われます。',
        key: '付加(不飽和結合)・置換(ベンゼン環)・脱離・縮合。アルコールの酸化は炭素の酸化数が上がる変化。' },
      { h: '入試ではこう出る:構造決定は「分子式→不飽和度→反応→候補をしぼる」', t: '有機化学の個別試験では、元素分析から分子式を出し、反応の結果から構造を1つに決める【構造決定】がもっともよく出ます。手順を型として身につけておくと、どんな物質でも同じ流れで解けます。\n①分子式を出す(元素分析と分子量)。②【不飽和度】を計算する。CₙHₘOₓ の不飽和度は (2n＋2−m)/2 で、二重結合や環が1つあるごとに1ふえます。ベンゼン環は1つで不飽和度4です。O の数は不飽和度に影響しません。③反応の情報から官能基をしぼる。Na と反応して H₂ を出す→−OH や −COOH、NaHCO₃ と反応して CO₂ を出す→−COOH、銀鏡反応→−CHO、ヨードホルム反応→CH₃CO− または CH₃CH(OH)− をもつ、など。④残った候補を、不斉炭素原子の有無や酸化生成物の情報で1つにしぼる。\n異性体をもれなく書き出す練習も大切です。炭素骨格(まっすぐ・枝分かれ)を先に決め、そこに官能基をつける位置を順に動かすと、もれや重複が防げます。\n時間配分のコツ:候補を全部書き出してから条件で消していく方法は確実ですが、時間がかかります。不飽和度と「最も情報の多い条件」(ヨードホルム反応や酸化生成物など)を先に使って候補をしぼると速くなります。',
        key: '不飽和度＝(2n＋2−m)/2。反応の情報で官能基を決め、不斉炭素や酸化生成物で候補を1つにしぼる。',
        ex: [{ q: '分子式 C₄H₁₀O の化合物について、(1)構造異性体は全部で何種類あるか。(2)そのうち、酸化するとケトンになるものの名前を答えよ。(3)不斉炭素原子をもつものはどれか。', hint: 'C₄H₁₀O の不飽和度は 0 です。アルコールとエーテルに分けて数えます。', steps: ['不飽和度は (2×4＋2−10)/2＝0 なので、二重結合も環もない。アルコールかエーテル。', 'アルコール:1-ブタノール、2-ブタノール、2-メチル-1-プロパノール、2-メチル-2-プロパノールの 4 種類。', 'エーテル:ジエチルエーテル、メチルプロピルエーテル、メチルイソプロピルエーテル(2-メトキシプロパン)の 3 種類。合計 7 種類。', '酸化してケトンになるのは第二級アルコールの 2-ブタノール(生成物は 2-ブタノン)。', '2-ブタノールの 2 番目の炭素には、H・OH・CH₃・C₂H₅ の4種類がつくので、不斉炭素原子をもつ。'], a: '(1)7 種類 (2)2-ブタノール (3)2-ブタノール', check: '2-メチル-2-プロパノールは第三級アルコールなので酸化されにくく、1-ブタノールと 2-メチル-1-プロパノールは第一級なのでアルデヒドになります。条件に合うのが 2-ブタノールだけであることが確かめられます。' },
          { q: '分子式 C₈H₁₀ で、ベンゼン環をもつ化合物 A がある。A を過マンガン酸カリウムで十分に酸化すると化合物 B ができ、B を加熱すると分子内で脱水して酸無水物になった。A の名前を答えよ。', hint: 'C₈H₁₀ の芳香族炭化水素は 4 種類あります。酸化でベンゼン環についた炭化水素基はどうなるでしょう。', steps: ['C₈H₁₀ の芳香族炭化水素は、エチルベンゼンと o-・m-・p-キシレンの 4 種類。', 'ベンゼン環に直接ついた炭化水素基は、KMnO₄ で酸化されると −COOH になる。エチルベンゼン→安息香酸、キシレン→フタル酸類。', '分子内で脱水して酸無水物になるには、2つの −COOH が隣り合っている必要がある。', '隣り合う(オルト位の)−COOH をもつのはフタル酸で、もとは o-キシレン。'], a: 'o-キシレン(B はフタル酸)', check: 'p-キシレンを酸化するとテレフタル酸になり、−COOH が離れているので分子内脱水は起こりません(テレフタル酸は PET の原料です)。' }] }
    ],
    drill: [
      { lv: 1, q: '次の分子式の不飽和度を求めよ。(1)C₆H₆ (2)C₃H₆ (3)C₂H₆O', a: '(1)4 (2)1 (3)0', exp: '不飽和度は (2n＋2−m)/2(n は C の数、m は H の数)で、O は無視します。\n(1)(14−6)/2＝4:ベンゼン環(環1＋二重結合3つ分)。(2)(8−6)/2＝1:二重結合1つ(プロペン)か環1つ(シクロプロパン)。(3)(6−6)/2＝0:エタノールかジメチルエーテル。' },
      { lv: 1, q: '次の官能基の名前を答えよ。(1)−CHO (2)−COOH (3)−NH₂ (4)−NO₂', a: '(1)ホルミル基(アルデヒド基) (2)カルボキシ基 (3)アミノ基 (4)ニトロ基', exp: '官能基は、化合物の性質を決める原子のまとまりです。−CHO はアルデヒドの性質(還元性)、−COOH は酸性、−NH₂ は塩基性を示します。\n−NO₂ はベンゼンのニトロ化で導入され、還元すると −NH₂ になります(ニトロベンゼン→アニリン)。' },
      { lv: 1, q: 'エタノールを二クロム酸カリウムの硫酸酸性溶液で穏やかに酸化すると化合物 X ができ、X をさらに酸化すると化合物 Y ができる。X と Y の名前を答えよ。', a: 'X:アセトアルデヒド、Y:酢酸', exp: 'エタノールは第一級アルコールなので、酸化されるとアルデヒドになり、さらに酸化されるとカルボン酸になります。\nCH₃CH₂OH→CH₃CHO(アセトアルデヒド)→CH₃COOH(酢酸)。\nX は還元性をもつので、銀鏡反応やフェーリング液の還元を示します。' },
      { lv: 2, q: '次のうち、ヨードホルム反応を示すものをすべて選べ。メタノール、エタノール、アセトン、酢酸、2-プロパノール', a: 'エタノール、アセトン、2-プロパノール', exp: 'ヨードホルム反応は、CH₃CO− の構造、または酸化されてそれになる CH₃CH(OH)− の構造をもつ化合物で起こり、黄色の CHI₃ が沈殿します。\nエタノール CH₃CH₂OH と 2-プロパノール CH₃CH(OH)CH₃ は CH₃CH(OH)− をもち、アセトン CH₃COCH₃ は CH₃CO− をもちます。\n酢酸 CH₃COOH は CH₃CO− をもつように見えますが、カルボキシ基の一部なので反応しません。ここがひっかけです。' },
      { lv: 2, q: '次のうち、銀鏡反応を示すものをすべて選べ。アセトン、ギ酸、酢酸、アセトアルデヒド', a: 'ギ酸、アセトアルデヒド', exp: '銀鏡反応はホルミル基(−CHO)をもつ物質が、アンモニア性硝酸銀水溶液の Ag⁺ を還元して銀を析出させる反応です。\nアセトアルデヒドは −CHO をもちます。ギ酸 HCOOH はカルボン酸ですが、H−CO− の部分がホルミル基の形をしているので還元性を示します。\nアセトン(ケトン)と酢酸は −CHO をもたないので反応しません。' },
      { lv: 2, q: '飽和1価カルボン酸 CₙH₂ₙ₊₁COOH 1.48 g を中和するのに、0.50 mol/L 水酸化ナトリウム水溶液 40 mL が必要だった。このカルボン酸の分子量と名前を答えよ。(H＝1.0、C＝12、O＝16)', a: '分子量 74、プロピオン酸(プロパン酸)C₂H₅COOH', exp: '1価の酸なので、カルボン酸の物質量＝NaOH の物質量＝0.50×0.040＝0.020 mol。\n分子量は 1.48÷0.020＝74。\nCₙH₂ₙ₊₁COOH の分子量は 14n＋46 なので、14n＋46＝74 より n＝2。C₂H₅COOH(プロピオン酸)です。' },
      { lv: 3, q: '分子式 C₄H₈ で表されるアルケンは何種類あるか。シス-トランス異性体も区別して答えよ。', a: '4 種類', exp: '不飽和度は 1 なので、アルケン(二重結合1つ)かシクロアルカン(環1つ)ですが、ここではアルケンだけを数えます。\n炭素骨格がまっすぐなもの:1-ブテン、2-ブテン。2-ブテンは二重結合の両側の炭素にそれぞれ H と CH₃ がつくので、シス形とトランス形がある。\n枝分かれしたもの:2-メチルプロペン(二重結合の片側の炭素に CH₃ が2つつくので、シス-トランス異性体はない)。\n合計 1＋2＋1＝4 種類です。シクロブタン・メチルシクロプロパンを含めると C₄H₈ は 6 種類になります。' },
      { lv: 3, q: '分子式 C₄H₈O₂ のエステル E を加水分解すると、カルボン酸 A とアルコール B ができた。A は銀鏡反応を示し、B を酸化するとケトンになった。E の構造式(示性式)と名前を答えよ。', a: 'HCOOCH(CH₃)₂、ギ酸イソプロピル(ギ酸1-メチルエチル)', exp: '銀鏡反応を示すカルボン酸はギ酸 HCOOH なので、A はギ酸です。\nE の炭素は 4 個で、ギ酸の部分が 1 個なので、アルコール B の炭素は 3 個。酸化してケトンになるのは第二級アルコールなので、B は 2-プロパノール CH₃CH(OH)CH₃ です。\nしたがって E は HCOOCH(CH₃)₂。分子式は C₄H₈O₂ と一致します。\n採点のポイントは、「銀鏡反応→ギ酸」「ケトン→第二級アルコール」の2つの根拠を書けているかです。' }
    ],
    faq: [
      ['フェノールは酸なのに、炭酸水素ナトリウム水溶液に溶けないのはなぜ?', 'フェノールは炭酸よりも弱い酸だからです。弱い酸は、自分より強い酸(炭酸)の塩から酸を追い出せません。そのため NaHCO₃ とは反応せず、より強い塩基の NaOH とだけ反応します。'],
      ['アルコールの −OH と、フェノールの −OH は同じではないの?', '同じヒドロキシ基ですが、ベンゼン環に直接ついているかどうかで性質がちがいます。フェノールの −OH は H⁺ を放出しやすく弱酸性を示しますが、アルコールの水溶液は中性です。'],
      ['ベンゼンは二重結合をもつように見えるのに、付加反応が起こりにくいのはなぜ?', 'ベンゼン環の電子は環全体に広がっていて、特別に安定な状態になっているからです。付加反応をするとこの安定な構造がこわれてしまうので、環を保ったまま進む置換反応のほうが起こりやすくなります。'],
      ['不斉炭素原子があると、なぜ「鏡像異性体」ができるの?', '炭素の4本の結合は正四面体の頂点の方向を向いています。4つにすべてちがう原子や原子団がつくと、右手と左手のように、鏡に映した形どうしを重ねられない2種類の分子ができます。これが【鏡像異性体】(光学異性体)です。\n2つは沸点や融点などの性質がほぼ同じですが、偏光面を回転させる向きが逆になります。また、生物の体内では、酵素などが片方だけを見分けるので、味やにおい、薬としてのはたらきがちがうことがあります。']
    ],
    terms: [['官能基', '有機化合物の性質を決める原子のまとまり'], ['示性式', '官能基がわかるように略した化学式(CH₃COOH など)'], ['構造異性体', '分子式が同じで、原子のつながり方がちがう化合物'], ['不斉炭素原子', '4つの異なる原子・原子団が結合した炭素原子'], ['付加反応', '不飽和結合が切れて、ほかの原子が結びつく反応'], ['エステル化', 'カルボン酸とアルコールから水が取れてエステルができる反応'], ['けん化', 'エステルを塩基で加水分解して、塩とアルコールにする反応'], ['ジアゾカップリング', 'ジアゾニウム塩とフェノール類などからアゾ化合物ができる反応']],
    miss: ['元素分析で、O の質量を計算せずに組成式を出してしまう。「全体−C−H」で O を必ず求めます。', 'C₄H₁₀ などの構造異性体を、折り曲げただけの同じ分子まで数えてしまう。いちばん長い鎖の長さで分類して確かめます。', 'エタノールの脱水で、温度と生成物を逆に覚える。「高温(約 170℃)では分子内でエチレン」と覚えます。', '芳香族の分離で、NaHCO₃ と NaOH の役割を混同する。酸の強さの順番に照らして考えます。', 'ヨードホルム反応を示す構造を、−OH があればよいと思いこむ。CH₃CH(OH)− または CH₃CO− の構造が必要です。'],
    sum: ['有機化合物の性質は官能基で決まる。', '元素分析は C＝CO₂×12/44、H＝H₂O×2/18 から組成式、分子量で分子式を決める。', '異性体には構造異性体・シス−トランス異性体・鏡像異性体がある。', 'アルカンは置換反応、アルケンは付加反応。アルコール→アルデヒド→カルボン酸と酸化される。', '芳香族化合物は置換反応が起こりやすい。分離は酸・塩基の強さのちがいを使う。'],
    next: '次は「高分子化合物」に進みましょう。ここで学んだ官能基の反応(エステル化・脱水縮合など)が、糖・タンパク質・プラスチックのでき方につながります。'
  };

  // ===== 高分子化合物 =====
  L.c4_poly = {
    goal: '糖類・アミノ酸とタンパク質・核酸の構造と性質を説明し、合成高分子が付加重合・縮合重合・開環重合のどれでできるかを、単量体の構造から判断できるようになる。',
    intro: 'ご飯のデンプン、肉のタンパク質、衣服のナイロン、ペットボトルの PET。これらはどれも、小さな分子が数百〜数万個もつながってできた巨大な分子です。この単元では、こうした【高分子化合物】が、どんな小さな単位からどのようにつながってできているのかを学びます。',
    pre: '分子量がおよそ 1 万以上の化合物を【高分子化合物】といいます。くり返しつながる小さな分子を【単量体】(モノマー)、つながってできた大きな分子を【重合体】(ポリマー)、つながりの数を【重合度】といいます。\n二重結合をもつ分子は【付加反応】を起こします(有機化合物の単元で学習)。この性質を使って、多数の分子をつなげることができます。\n2つの分子から水などの小さな分子が取れて結びつく反応を【縮合】といいます。例:カルボン酸とアルコールのエステル化(−COO− ができる)、カルボン酸とアミンからアミド結合(−CO−NH−)ができる反応です。\n縮合の逆に、水が加わって分解される反応を【加水分解】といいます。消化は、食べ物の高分子を加水分解して小さな分子にするはたらきです。',
    secs: [
      { h: '高分子化合物の分類と重合の種類', t: '高分子化合物は、自然界にある【天然高分子】(デンプン・セルロース・タンパク質・核酸・天然ゴムなど)と、人工的につくる【合成高分子】(ナイロン・ポリエチレンなど)に分けられます。\n単量体をつなげる反応(重合)には、主に3種類あります。二重結合が開いてつながる【付加重合】、水などが取れながらつながる【縮合重合】、環状の分子の環が開いてつながる【開環重合】です。\n合成高分子の多くは、重合度がそろっていないため、分子量に幅があります。そこで、分子量は平均分子量で表します。平均重合度＝平均分子量÷くり返し単位の式量で求めます。\n高分子は分子量が一定でないため、決まった融点を示さず、加熱するとある温度範囲でやわらかくなります(軟化点)。',
        key: '重合は付加重合・縮合重合・開環重合の3種類。平均重合度＝平均分子量÷くり返し単位の式量。',
        ex: [{ q: '平均分子量 5.0×10⁴ のポリ塩化ビニル −[CH₂−CHCl]ₙ− の平均重合度を求めよう。(H＝1.0、C＝12、Cl＝35.5)', hint: 'くり返し単位 CH₂CHCl の式量を求めます。', steps: ['くり返し単位 C₂H₃Cl の式量は 12×2＋1.0×3＋35.5＝62.5。', '平均重合度＝5.0×10⁴÷62.5。', '計算すると 800。'], a: '800', check: '62.5×800＝50000＝5.0×10⁴ となり、平均分子量と一致します。' }] },
      { h: '単糖と二糖', t: '糖類は、一般式 Cₘ(H₂O)ₙ で表されるものが多く、炭水化物ともよばれます。それ以上加水分解されない最小単位を【単糖】、単糖 2 分子が脱水縮合したものを【二糖】といいます。\n代表的な単糖は、グルコース(ブドウ糖)・フルクトース(果糖)・ガラクトースで、どれも分子式 C₆H₁₂O₆ の異性体です。グルコースは水溶液中で、環状構造(α形・β形)と鎖状構造が平衡状態にあります。鎖状構造にホルミル基 −CHO があるため、還元性を示し、銀鏡反応やフェーリング液の還元を起こします。フルクトースも水溶液中で還元性を示します。\n代表的な二糖(分子式 C₁₂H₂₂O₁₁)は、マルトース(麦芽糖:グルコース＋グルコース)、スクロース(ショ糖:グルコース＋フルクトース)、ラクトース(乳糖:ガラクトース＋グルコース)、セロビオース(グルコース＋グルコース)です。\nスクロースは、グルコースとフルクトースが、それぞれ還元性を生む部分どうしで結合しているため、還元性を示しません。スクロースを加水分解した、グルコースとフルクトースの混合物を【転化糖】といいます。\nグルコースは、酵母のもつ酵素群チマーゼによって、エタノールと二酸化炭素に分解されます(【アルコール発酵】:C₆H₁₂O₆→2C₂H₅OH＋2CO₂)。',
        key: '単糖 C₆H₁₂O₆、二糖 C₁₂H₂₂O₁₁。二糖のうちスクロースだけ還元性なし。アルコール発酵 C₆H₁₂O₆→2C₂H₅OH＋2CO₂。',
        ex: [{ q: 'グルコース 36 g をすべてアルコール発酵させると、エタノールは何 g 生じる?(H＝1.0、C＝12、O＝16)', hint: 'グルコース 1 mol からエタノール 2 mol ができます。', steps: ['グルコース C₆H₁₂O₆ のモル質量は 180 g/mol。36 g は 36÷180＝0.20 mol。', '反応式より、エタノールは 0.20×2＝0.40 mol。', 'エタノール C₂H₅OH のモル質量は 46 g/mol → 46×0.40＝18.4 g。'], a: '18.4 g(約 18 g)', check: 'CO₂ も 0.40 mol(17.6 g)できます。18.4＋17.6＝36 g で、質量保存の法則が成り立っています。' }] },
      { h: '多糖類', t: '多数の単糖が脱水縮合した高分子を【多糖類】といい、(C₆H₁₀O₅)ₙ で表されます。代表例はデンプンとセルロースで、どちらもグルコースからできていますが、性質は大きくちがいます。\n【デンプン】は α-グルコースが縮合した多糖です。直鎖状でらせん構造をとる【アミロース】と、枝分かれの多い【アミロペクチン】からなります。ヨウ素ヨウ化カリウム水溶液で青紫色になる【ヨウ素デンプン反応】は、デンプンのらせん構造の中にヨウ素が入りこむことで起こります。\nデンプンは、酵素アミラーゼでマルトースに、さらにマルターゼでグルコースに加水分解されます。動物の体内では、グリコーゲンという多糖としてたくわえられます。\n【セルロース】は β-グルコースが縮合した多糖で、まっすぐにのびた分子どうしが水素結合で束になり、じょうぶな繊維になります。植物の細胞壁の主成分で、ヨウ素デンプン反応は示しません。セルロースを溶かして再び繊維にしたものをレーヨン(再生繊維)、セルロースを無水酢酸でアセチル化したものをアセテート(半合成繊維)といいます。',
        key: 'デンプン=α-グルコース(ヨウ素デンプン反応で青紫)、セルロース=β-グルコース(じょうぶな繊維)。',
        ex: [{ q: 'デンプン 81 g を完全に加水分解すると、グルコースは何 g 得られる?(H＝1.0、C＝12、O＝16)', hint: '(C₆H₁₀O₅)ₙ＋nH₂O→nC₆H₁₂O₆ です。くり返し単位 1 個からグルコース 1 分子ができます。', steps: ['くり返し単位 C₆H₁₀O₅ の式量は 162。81 g はくり返し単位 81÷162＝0.50 mol 分。', 'くり返し単位 1 mol からグルコース 1 mol ができるので、グルコースは 0.50 mol。', 'グルコースのモル質量 180 g/mol → 180×0.50＝90 g。'], a: '90 g', check: '水が加わるので、生成物の質量(90 g)がもとのデンプン(81 g)より大きくなるのが正しい結果です。差の 9 g は加わった水 0.50 mol 分です。' }] },
      { h: 'アミノ酸とタンパク質', t: '同じ炭素原子にアミノ基 −NH₂ とカルボキシ基 −COOH が結合した化合物を【α-アミノ酸】といい、R−CH(NH₂)−COOH で表されます。タンパク質をつくるアミノ酸は約 20 種類で、グリシン(R＝H)以外は不斉炭素原子をもつため、鏡像異性体があります。\nアミノ酸は、結晶中や水溶液中では −COO⁻ と −NH₃⁺ をあわせもつ【双性イオン】として存在し、酸とも塩基とも反応します(両性化合物)。アミノ酸の電荷の総和が 0 になる pH を【等電点】といい、グリシンでは約 6.0 です。\nアミノ酸のカルボキシ基と別のアミノ酸のアミノ基が脱水縮合してできる結合 −CO−NH− を【ペプチド結合】といいます。多数のアミノ酸がペプチド結合でつながったものがポリペプチドで、タンパク質はポリペプチドからできています。\nタンパク質のアミノ酸の配列順序を【一次構造】、水素結合によるらせん状の α-ヘリックスやシート状の β-シートを【二次構造】といい、さらに折りたたまれて立体的な形(三次構造・四次構造)になります。加熱や強い酸・塩基、重金属イオン、アルコールなどで立体構造がこわれ、性質が変わることを【変性】といいます。\nタンパク質の検出反応:【ビウレット反応】(NaOH 水溶液と CuSO₄ 水溶液で赤紫色、ペプチド結合を2つ以上もつトリペプチド以上で起こる)、【キサントプロテイン反応】(濃硝酸で加熱すると黄色、冷却後アンモニア水で橙黄色、ベンゼン環の検出)、硫黄の検出(NaOH で加熱後、酢酸鉛(Ⅱ)水溶液で黒色の PbS が沈殿)。アミノ酸そのものは、ニンヒドリン反応(赤紫〜青紫色)で検出します。\n生体内で触媒としてはたらくタンパク質を【酵素】といいます。特定の物質(基質)にだけはたらく基質特異性をもち、最もよくはたらく温度(最適温度、多くは 35〜40℃付近)や pH(最適 pH、ペプシンは約 2、トリプシンは約 8)があります。',
        key: 'α-アミノ酸がペプチド結合 −CO−NH− でつながってタンパク質になる。ビウレット(赤紫)・キサントプロテイン(黄)・ニンヒドリン(赤紫〜青紫)。',
        ex: [{ q: 'グリシン(分子量 75)とアラニン(分子量 89)各 1 分子からできるジペプチドは何種類あり、その分子量はいくつ?(鏡像異性体は区別しない)', hint: 'どちらのアミノ酸のカルボキシ基が使われるかで、2通りの並び方があります。', steps: ['グリシンの −COOH とアラニンの −NH₂ が結合すると Gly−Ala、アラニンの −COOH とグリシンの −NH₂ が結合すると Ala−Gly になる。', 'この2つは原子のつながり方がちがう別の化合物なので、2種類。', 'ペプチド結合が1つできるときに H₂O(分子量 18)が1分子取れる。', '分子量は 75＋89−18＝146。'], a: '2種類、分子量 146', check: 'どちらのジペプチドも、同じ2分子から水1分子が取れたものなので、分子量は同じ 146 になります。' }] },
      { h: '核酸', t: '【核酸】は、遺伝情報の保存と伝達にはたらく天然高分子で、DNA(デオキシリボ核酸)と RNA(リボ核酸)があります。\n核酸の単量体は【ヌクレオチド】で、リン酸・糖・塩基が結合したものです。ヌクレオチドのリン酸と、別のヌクレオチドの糖の部分が縮合して、長い鎖になります。\nDNA の糖はデオキシリボース、塩基はアデニン(A)・グアニン(G)・シトシン(C)・チミン(T)の4種類です。DNA は2本の鎖が塩基どうしの水素結合でつながった【二重らせん構造】をとり、A と T、G と C が必ず対になります(【相補性】)。\nRNA の糖はリボース、塩基は A・G・C とウラシル(U)で、T の代わりに U を使います。RNA はふつう1本鎖で、DNA の遺伝情報をもとにタンパク質を合成するときにはたらきます。',
        key: 'DNA:デオキシリボース・A/T/G/C・二重らせん(A−T、G−C)。RNA:リボース・A/U/G/C・1本鎖。',
        ex: [{ q: 'ある二本鎖 DNA で、アデニン(A)が全塩基数の 30% をしめていた。グアニン(G)は何% か。', hint: 'A と T、G と C の数は等しくなります。', steps: ['A と T は対になるので、T も 30%。', 'A＋T＝60% なので、G＋C＝100−60＝40%。', 'G と C は等しいので、G＝40÷2＝20%。'], a: '20%', check: 'A 30＋T 30＋G 20＋C 20＝100% になっているかを確かめます。' }] },
      { h: '合成高分子:付加重合', t: 'ビニル基 CH₂=CH− をもつ単量体は、二重結合が開いて【付加重合】します。nCH₂=CHX→−[CH₂−CHX]ₙ− の形で、X の種類によって性質のちがう高分子になります。\n主な例:ポリエチレン(X＝H、袋・容器)、ポリプロピレン(X＝CH₃)、ポリ塩化ビニル(X＝Cl、水道管)、ポリスチレン(X＝C₆H₅、発泡スチロール)、ポリ酢酸ビニル(X＝OCOCH₃)などです。\nポリ酢酸ビニルをけん化するとポリビニルアルコールになり、これをホルムアルデヒドで処理(アセタール化)して水に溶けにくくしたものが、日本で開発された合成繊維【ビニロン】です。適度に −OH が残るので吸湿性があります。\n鎖状の構造をもつ高分子は、加熱するとやわらかくなり、冷やすと固まります(【熱可塑性樹脂】)。一方、フェノール樹脂・尿素樹脂・メラミン樹脂のように、立体網目状の構造をもつ高分子は、加熱しても軟化せず、かたくなります(【熱硬化性樹脂】)。\n天然ゴムは、イソプレン C₅H₈ が付加重合した構造(シス形のポリイソプレン)をもちます。硫黄を加えて加熱する【加硫】によって、鎖どうしが硫黄原子で橋かけされ、弾性が強くなります。合成ゴムには、ブタジエンゴムや、スチレンとブタジエンを共重合させたスチレン−ブタジエンゴム(SBR)などがあります。',
        key: 'ビニル化合物は付加重合。鎖状は熱可塑性、立体網目状は熱硬化性。ゴムは加硫で弾性が増す。' },
      { h: '合成高分子:縮合重合と開環重合', t: '2つの官能基をもつ単量体どうしが、水などを取りながら次々に結合することを【縮合重合】といいます。\n【ナイロン66】は、アジピン酸 HOOC(CH₂)₄COOH とヘキサメチレンジアミン H₂N(CH₂)₆NH₂ の縮合重合でできます。−COOH と −NH₂ から水が取れて、アミド結合 −CO−NH− が多数できるので、【ポリアミド】ともよばれます。\n【ナイロン6】は、環状の ε-カプロラクタムの環が開いてつながる【開環重合】でつくられます。くり返し単位にアミド結合をもつ点はナイロン66と同じです。\n【ポリエチレンテレフタラート】(PET)は、テレフタル酸とエチレングリコールの縮合重合でできる【ポリエステル】で、ペットボトルや衣料に使われます。\nほかにも、ベンゼン環をアミド結合でつないだ強度の高いアラミド繊維、微生物によって分解される生分解性高分子のポリ乳酸、水中のイオンを交換するイオン交換樹脂など、目的に合わせたさまざまな高分子がつくられています。',
        key: 'ナイロン66=アジピン酸＋ヘキサメチレンジアミン(縮合重合)、ナイロン6=ε-カプロラクタム(開環重合)、PET=テレフタル酸＋エチレングリコール。' },
      { h: 'もっと深く:糖の還元性はどこから来るのか', t: 'グルコースは、結晶ではおもに環状構造をとっていますが、水に溶かすと【α形・鎖状構造・β形】の3つがつり合った平衡状態になります。鎖状構造はわずかしかありませんが、ホルミル基(−CHO)をもちます。\n銀鏡反応やフェーリング液の還元が起こると、鎖状構造の分子が反応して減ります。すると平衡が移動して環状の分子が次々と鎖状構造になり、結果としてグルコース全体が反応します。グルコースの還元性は、この「開いた鎖」から来ているのです。\n環が開けるかどうかは、1位の炭素(環の中で O と隣り合い、−OH がついた炭素)が自由かどうかで決まります。マルトースやラクトースは、片方の糖の1位の −OH が結合に使われていても、もう片方の糖の1位の −OH が自由なので、環を開くことができ、還元性を示します。\nスクロースは、グルコースの1位とフルクトースの2位(フルクトースの環を開く位置)どうしが結合しているので、どちらの環も開けません。そのため還元性がありません。ただし、酵素インベルターゼや酸で加水分解すると、グルコースとフルクトースの混合物(転化糖)になり、還元性を示すようになります。\nデンプンやセルロースも、鎖の端にしか自由な1位の −OH がなく、分子全体に対してほとんどないので、還元性はほとんど示しません。このように、還元性の有無は「環を開ける部分が残っているか」で統一的に説明できます。',
        key: '還元性は環が開いた鎖状構造(−CHO など)から。スクロースは開ける部分どうしで結合しているので還元性なし。' },
      { h: '入試ではこう出る:高分子の計算は「くり返し単位」でそろえる', t: '高分子の計算問題は、ほとんどが【くり返し単位】の式量を使えば解けます。平均重合度 n＝平均分子量÷くり返し単位の式量 が基本です。\n縮合重合でできた高分子では、くり返し単位の中に結合がいくつ含まれるかに注意します。ナイロン66 のくり返し単位 −[CO−(CH₂)₄−CO−NH−(CH₂)₆−NH]− には、アミド結合が2つ含まれます。PET のくり返し単位には、エステル結合が2つ含まれます。\n反応による質量の変化を問う問題もよく出ます。たとえば、セルロースのアセチル化では、くり返し単位の3つの −OH がそれぞれ −OCOCH₃ になり、1つあたり式量が 42 ふえます。ビニロンの合成では、ポリビニルアルコールの −OH 2つとホルムアルデヒド1分子が反応して水1分子がとれ、−OH 2つにつき質量が 30−18＝12 ふえます。\nひっかけは、重合度とくり返し単位の数が一致しない場合です。ナイロン66 の n はくり返し単位の数で、そこに含まれるアミド結合は約 2n 個です。また、単量体の分子量ではなく、くり返し単位の式量で割ることを忘れないようにしましょう(縮合重合では水がとれる分だけ単量体の分子量の和より小さくなります)。\n時間配分のコツ:くり返し単位の式量は、よく出るもの(ポリエチレン 28、ポリ塩化ビニル 62.5、ナイロン66 226、PET 192、セルロース・デンプン 162)を覚えておくと速くなります。',
        key: '平均重合度＝平均分子量÷くり返し単位の式量。くり返し単位に含まれる結合の数と、反応での質量変化に注意。',
        ex: [{ q: '平均分子量 2.26×10⁴ のナイロン66 がある。(1)平均重合度を求めよ。(2)この分子1個に含まれるアミド結合はおよそ何個か。(H＝1.0、C＝12、N＝14、O＝16)', hint: 'くり返し単位は −[CO−(CH₂)₄−CO−NH−(CH₂)₆−NH]− です。', steps: ['くり返し単位の分子式は C₁₂H₂₂N₂O₂。式量は 12×12＋22×1.0＋2×14＋2×16＝144＋22＋28＋32＝226。', '平均重合度 n＝2.26×10⁴÷226＝100。', 'くり返し単位1つにアミド結合 −CO−NH− が2つ含まれる。', 'アミド結合はおよそ 2×100＝200 個(厳密には端の分を除いて 199 個)。'], a: '(1)100 (2)約 200 個', check: 'ナイロン66 はアジピン酸(分子量 146)とヘキサメチレンジアミン(分子量 116)から水 2 分子がとれてくり返し単位ができるので、146＋116−36＝226 と確かめられます。' },
          { q: 'ポリビニルアルコール 100 g の −OH のうち 30% をホルムアルデヒドでアセタール化してビニロンをつくった。得られるビニロンは何 g か。(H＝1.0、C＝12、O＝16)', hint: '−OH 2 つと HCHO 1 分子が反応し、水 1 分子がとれます。', steps: ['ポリビニルアルコールのくり返し単位 −[CH₂−CH(OH)]− の式量は 44。100 g に含まれる −OH は 100÷44≒2.27 mol。', 'アセタール化される −OH は 2.27×0.30≒0.682 mol。', '−OH 2 mol あたり HCHO(30)が加わり H₂O(18)がとれるので、質量は 12 g ふえる。', '増加量は 0.682÷2×12≒4.1 g。ビニロンは 100＋4.1≒104 g。'], a: '約 104 g', check: '式でまとめると増加量＝100×0.30×12/(44×2)＝4.09 g です。アセタール化で −OH がへるので、ビニロンは水に溶けにくくなります(ただし適度に −OH が残るので吸湿性があります)。' }] }
    ],
    drill: [
      { lv: 1, q: '次の高分子の単量体を答えよ。(1)ポリスチレン (2)ポリ酢酸ビニル (3)ポリエチレンテレフタラート(PET)', a: '(1)スチレン (2)酢酸ビニル (3)エチレングリコールとテレフタル酸', exp: '(1)(2)は付加重合でできるので、単量体の二重結合が開いてつながります。名前の「ポリ」を外したものが単量体です。\n(3)PET は縮合重合でできるので、2種類の単量体(2価アルコールのエチレングリコールと、2価カルボン酸のテレフタル酸)から水がとれてエステル結合でつながります。' },
      { lv: 1, q: '次の二糖を加水分解すると、何ができるか。(1)マルトース (2)スクロース (3)ラクトース', a: '(1)グルコース2分子 (2)グルコースとフルクトース (3)グルコースとガラクトース', exp: '二糖は単糖2分子が脱水縮合したものなので、加水分解すると2分子の単糖にもどります。\nマルトースは麦芽糖、スクロースはショ糖(砂糖)、ラクトースは乳糖です。単糖はどれも C₆H₁₂O₆ の異性体です。' },
      { lv: 1, q: '次の反応で検出できる物質を答えよ。(1)ニンヒドリン反応 (2)ヨウ素デンプン反応', a: '(1)アミノ酸(アミノ基)(赤紫〜青紫色) (2)デンプン(青紫色)', exp: '(1)ニンヒドリンはアミノ基と反応して赤紫〜青紫色になるので、アミノ酸やタンパク質の検出に使います。\n(2)ヨウ素は、デンプン(アミロース)のらせん構造の中に入りこんで青紫色を示します。加熱するとらせんがほどけて色が消え、冷やすともどります。' },
      { lv: 2, q: '平均分子量 2.8×10⁵ のポリエチレンの平均重合度を求めよ。(H＝1.0、C＝12)', a: '1.0×10⁴', exp: 'ポリエチレンのくり返し単位は −[CH₂−CH₂]− で、式量は 28 です。\n平均重合度＝2.8×10⁵÷28＝1.0×10⁴。\n単量体のエチレン C₂H₄ も分子量 28 ですが、これは付加重合では原子がとれないからです。縮合重合ではこうはなりません。' },
      { lv: 2, q: 'グリシン(分子量 75)、アラニン(分子量 89)、フェニルアラニン(分子量 165)を1分子ずつ使ってできる鎖状のトリペプチドは何種類あるか。また、その分子量を求めよ。(鏡像異性体は区別しない)', a: '6 種類、分子量 293', exp: 'ペプチドには向き(N 末端と C 末端)があるので、3種類のアミノ酸の並べ方は 3×2×1＝6 通りで、すべて別の物質になります。\n3分子がつながるとペプチド結合が2つでき、水が2分子とれます。分子量は 75＋89＋165−2×18＝329−36＝293 です。' },
      { lv: 2, q: 'グリシンを pH 2 の緩衝液に溶かして電気泳動を行うと、グリシンは陽極側・陰極側のどちらへ移動するか。理由も答えよ。', a: '陰極側。酸性では −NH₃⁺ をもつ陽イオンが多くなるから。', exp: 'アミノ酸は水溶液中で、陽イオン・双性イオン・陰イオンが平衡にあります。グリシンの等電点は約 6 です。\npH が等電点より小さい(酸性の)とき、H⁺ が多いので −COO⁻ が −COOH にもどり、H₃N⁺−CH₂−COOH という陽イオンが多くなります。\n陽イオンは陰極に引かれるので、陰極側へ移動します。等電点では全体の電荷が 0 になり、ほとんど移動しません。' },
      { lv: 3, q: 'セルロース 16.2 g をすべてトリアセチルセルロースにすると、何 g になるか。(H＝1.0、C＝12、O＝16)', a: '28.8 g', exp: 'セルロースのくり返し単位 C₆H₁₀O₅(式量 162)には −OH が3つあり、[C₆H₇O₂(OH)₃] と書けます。\n3つの −OH がすべて −OCOCH₃ になると [C₆H₇O₂(OCOCH₃)₃] で、−OH 1つあたり式量が 42(−OH 17 が −OCOCH₃ 59 に)ふえるので、式量は 162＋3×42＝288。\nくり返し単位の数は変わらないので、16.2÷162＝0.10 mol のくり返し単位から 0.10×288＝28.8 g になります。' },
      { lv: 3, q: '100 塩基対からなる二本鎖 DNA で、アデニン(A)が全塩基数の 20% だった。塩基対の間の水素結合は全部で何本あるか。(A−T 間は2本、G−C 間は3本とする)', a: '260 本', exp: '全塩基数は 200 個。A は 20% で 40 個、相補的な T も 40 個。残りの 120 個が G と C で、60 個ずつです。\nA−T 対は 40 組、G−C 対は 60 組。\n水素結合は 40×2＋60×3＝80＋180＝260 本です。G−C 対が多い DNA ほど水素結合が多く、二本鎖がほどけにくい(高い温度が必要)ことにつながります。' }
    ],
    faq: [
      ['デンプンとセルロースは同じグルコースからできているのに、なぜ性質がちがうの?', 'つながっているグルコースの形(α形かβ形か)がちがうからです。α-グルコースがつながったデンプンはらせん状になり、β-グルコースがつながったセルロースはまっすぐのびて分子どうしが水素結合で束になります。この形のちがいが、溶けやすさや消化のされやすさのちがいを生みます。'],
      ['付加重合と縮合重合は、どうやって見分けるの?', '単量体の構造を見ます。C=C 二重結合をもつ単量体1種類からできるなら付加重合です。−COOH と −NH₂、−COOH と −OH のように、反応する官能基を2つずつもつ単量体からできるなら縮合重合で、水などの小さな分子が取れます。'],
      ['タンパク質を加熱すると、元にもどらないのはなぜ?', '加熱によって、立体構造を支えていた水素結合などが切れ、形がくずれて(変性して)しまうからです。いったんくずれた形は、冷やしても元のようには折りたたまれないことが多く、ゆで卵が生卵にもどらないのはこのためです。'],
      ['フルクトースはアルデヒド基をもたないのに、なぜ還元性を示すの?', 'フルクトースも水溶液中では環状構造と鎖状構造が平衡になっています。鎖状構造では −CO−CH₂OH(ケトン基の隣に −OH がついた構造)をもち、この部分が還元性を示すため、銀鏡反応やフェーリング液の還元が起こります。\nつまり、還元性の有無は「ホルミル基があるか」だけでなく、「水溶液中で環を開いて還元性のある構造になれるか」で決まると考えるとよいでしょう。']
    ],
    terms: [['単量体', '重合体をつくる、くり返しの単位となる小さな分子(モノマー)'], ['重合度', '重合体の中で単量体がつながった数'], ['還元性', '相手を還元するはたらき。ホルミル基などをもつ糖が示す'], ['ペプチド結合', 'アミノ酸どうしが脱水縮合してできる −CO−NH− の結合'], ['等電点', 'アミノ酸の電荷の総和が 0 になる pH'], ['ヌクレオチド', 'リン酸・糖・塩基からなる核酸の単量体'], ['熱可塑性樹脂', '加熱するとやわらかくなる鎖状構造の合成樹脂'], ['開環重合', '環状の単量体の環が開いてつながる重合']],
    miss: ['二糖はすべて還元性を示すと思いこむ。スクロースだけは還元性を示しません。', 'デンプンとセルロースの単量体を、どちらも同じ「グルコース」とだけ覚える。α形とβ形のちがいまでセットで覚えます。', 'ビウレット反応とキサントプロテイン反応で、検出できる構造を取りちがえる。ビウレットはペプチド結合、キサントプロテインはベンゼン環です。', 'ナイロン6を縮合重合と答えてしまう。ε-カプロラクタムの開環重合です。', '重合度の計算で、単量体の分子量ではなく重合体の分子量そのもので割ってしまう。くり返し単位の式量で割ります。'],
    sum: ['高分子は付加重合・縮合重合・開環重合でできる。平均重合度＝平均分子量÷くり返し単位の式量。', '単糖 C₆H₁₂O₆・二糖 C₁₂H₂₂O₁₁。スクロースだけ還元性なし。', 'デンプンは α-グルコース、セルロースは β-グルコースからなる。', 'タンパク質は α-アミノ酸がペプチド結合でつながったもの。呈色反応で検出する。', '核酸はヌクレオチドからなり、DNA は A−T、G−C の対で二重らせんをつくる。', 'ナイロン66・PET は縮合重合、ナイロン6は開環重合、ポリエチレンなどは付加重合。'],
    next: 'これで化学の主な単元はひととおり終わりです。次は、理論化学(物質の状態・平衡)と有機化学の計算問題を組み合わせた入試レベルの演習に取り組み、知識をつなげて使えるようにしましょう。'
  };
})(WPS.LESSONS);
